eateInfo *pDepthStencilState;\\n  const VkPipelineColorBlendStateCreateInfo *pColorBlendState;\\n  const VkPipelineDynamicStateCreateInfo *pDynamicState;\\n  VkPipelineLayout layout;\\n  VkRenderPass renderPass;\\n  uint32_t subpass;\\n  VkPipeline basePipelineHandle;\\n  int32_t basePipelineIndex;\\n} VkGraphicsPipelineCreateInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkPipelineCreateFlags flags;\\n  VkPipelineShaderStageCreateInfo stage;\\n  VkPipelineLayout layout;\\n  VkPipeline basePipelineHandle;\\n  int32_t basePipelineIndex;\\n} VkComputePipelineCreateInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkRenderPassCreateFlags flags;\\n  uint32_t attachmentCount;\\n  const VkAttachmentDescription *pAttachments;\\n  uint32_t subpassCount;\\n  const VkSubpassDescription *pSubpasses;\\n  uint32_t dependencyCount;\\n  const VkSubpassDependency *pDependencies;\\n} VkRenderPassCreateInfo;\\n\\ntypedef struct {\\n  VkComponentSwizzle r;\\n  VkComponentSwizzle g;\\n  VkComponentSwizzle b;\\n  VkComponentSwizzle a;\\n} VkComponentMapping;\\n\\ntypedef struct {\\n  VkImageAspectFlags aspectMask;\\n  uint32_t baseMipLevel;\\n  uint32_t levelCount;\\n  uint32_t baseArrayLayer;\\n  uint32_t layerCount;\\n} VkImageSubresourceRange;\\n\\ntypedef union {\\n  float float32[4];\\n  int32_t int32[4];\\n  uint32_t uint32[4];\\n} VkClearColorValue;\\n\\ntypedef struct {\\n  float depth;\\n  uint32_t stencil;\\n} VkClearDepthStencilValue;\\n\\ntypedef union {\\n  VkClearColorValue color;\\n  VkClearDepthStencilValue depthStencil;\\n} VkClearValue;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkFlags flags;\\n  VkImage image;\\n  VkImageViewType viewType;\\n  VkFormat format;\\n  VkComponentMapping components;\\n  VkImageSubresourceRange subresourceRange;\\n} VkImageViewCreateInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkFramebufferCreateFlags flags;\\n  VkRenderPass renderPass;\\n  uint32_t attachmentCount;\\n  const void *pAttachments;\\n  uint32_t width;\\n  uint32_t height;\\n  uint32_t layers;\\n} VkFramebufferCreateInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkCommandPoolCreateFlags flags;\\n  uint32_t queueFamilyIndex;\\n} VkCommandPoolCreateInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkCommandPool commandPool;\\n  VkCommandBufferLevel level;\\n  uint32_t commandBufferCount;\\n} VkCommandBufferAllocateInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkCommandBufferUsageFlags flags;\\n  const void *pInheritanceInfo;\\n} VkCommandBufferBeginInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkFlags flags;\\n} VkSemaphoreCreateInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkFlags flags;\\n} VkFenceCreateInfo;\\n\\ntypedef struct {\\n  uint32_t binding;\\n  VkDescriptorType descriptorType;\\n  uint32_t descriptorCount;\\n  VkShaderStageFlags stageFlags;\\n  const void *pImmutableSamplers;\\n} VkDescriptorSetLayoutBinding;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkDescriptorSetLayoutCreateFlags flags;\\n  uint32_t bindingCount;\\n  const VkDescriptorSetLayoutBinding *pBindings;\\n} VkDescriptorSetLayoutCreateInfo;\\n\\ntypedef struct {\\n  VkDescriptorType type;\\n  uint32_t descriptorCount;\\n} VkDescriptorPoolSize;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkDescriptorPoolCreateFlags flags;\\n  uint32_t maxSets;\\n  uint32_t poolSizeCount;\\n  const VkDescriptorPoolSize *pPoolSizes;\\n} VkDescriptorPoolCreateInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkDescriptorPool descriptorPool;\\n  uint32_t descriptorSetCount;\\n  const VkDescriptorSetLayout *pSetLayouts;\\n} VkDescriptorSetAllocateInfo;\\n\\ntypedef struct {\\n  VkBuffer buffer;\\n  VkDeviceSize offset;\\n  VkDeviceSize range;\\n} VkDescriptorBufferInfo;\\n\\ntypedef struct {\\n  VkSampler sampler;\\n  VkImageView imageView;\\n  VkImageLayout imageLayout;\\n} VkDescriptorImageInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkDescriptorSet dstSet;\\n  uint32_t dstBinding;\\n  uint32_t dstArrayElement;\\n  uint32_t descriptorCount;\\n  VkDescriptorType descriptorType;\\n  const VkDescriptorImageInfo *pImageInfo;\\n  const VkDescriptorBufferInfo *pBufferInfo;\\n  const void *pTexelBufferView;\\n} VkWriteDescriptorSet;\\n\\ntypedef struct {\\n  uint32_t minImageCount;\\n  uint32_t maxImageCount;\\n  VkExtent2D currentExtent;\\n  VkExtent2D minImageExtent;\\n  VkExtent2D maxImageExtent;\\n  uint32_t maxImageArrayLayers;\\n  VkSurfaceTransformFlagsKHR supportedTransforms;\\n  VkSurfaceTransformFlagBitsKHR currentTransform;\\n  VkCompositeAlphaFlagsKHR supportedCompositeAlpha;\\n  VkImageUsageFlags supportedUsageFlags;\\n} VkSurfaceCapabilitiesKHR;\\n\\ntypedef struct {\\n  VkFormat format;\\n  VkColorSpaceKHR colorSpace;\\n} VkSurfaceFormatKHR;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkSwapchainCreateFlagsKHR flags;\\n  VkSurfaceKHR surface;\\n  uint32_t minImageCount;\\n  VkFormat imageFormat;\\n  VkColorSpaceKHR imageColorSpace;\\n  VkExtent2D imageExtent;\\n  uint32_t imageArrayLayers;\\n  VkImageUsageFlags imageUsage;\\n  VkSharingMode imageSharingMode;\\n  uint32_t queueFamilyIndexCount;\\n  const uint32_t *pQueueFamilyIndices;\\n  VkSurfaceTransformFlagBitsKHR preTransform;\\n  VkCompositeAlphaFlagBitsKHR compositeAlpha;\\n  VkPresentModeKHR presentMode;\\n  VkBool32 clipped;\\n  VkSwapchainKHR oldSwapchain;\\n} VkSwapchainCreateInfoKHR;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkRenderPass renderPass;\\n  VkFramebuffer framebuffer;\\n  VkRect2D renderArea;\\n  uint32_t clearValueCount;\\n  const VkClearValue *pClearValues;\\n} VkRenderPassBeginInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  uint32_t waitSemaphoreCount;\\n  const VkSemaphore *pWaitSemaphores;\\n  const VkPipelineStageFlags *pWaitDstStageMask;\\n  uint32_t commandBufferCount;\\n  const VkCommandBuffer *pCommandBuffers;\\n  uint32_t signalSemaphoreCount;\\n  const VkSemaphore *pSignalSemaphores;\\n} VkSubmitInfo;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  uint32_t waitSemaphoreCount;\\n  const VkSemaphore *pWaitSemaphores;\\n  uint32_t swapchainCount;\\n  const VkSwapchainKHR *pSwapchains;\\n  const uint32_t *pImageIndices;\\n  VkResult *pResults;\\n} VkPresentInfoKHR;\\n\\n/* VK_KHR_present_id: a present can be numbered, and VK_KHR_present_wait waits\\n   for one of those numbers to have reached the display. Chained onto\\n   VkPresentInfoKHR, one id per swapchain. */\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  uint32_t swapchainCount;\\n  const uint64_t *pPresentIds;\\n} VkPresentIdKHR;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  void *pNext;\\n  VkBool32 presentId;\\n} VkPhysicalDevicePresentIdFeaturesKHR;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  void *pNext;\\n  VkBool32 presentWait;\\n} VkPhysicalDevicePresentWaitFeaturesKHR;\\n\\n/* The 1.1 way of asking about features: the ones named by chaining their own\\n   structures onto this, which is what an extension added after 1.0 needs. */\\ntypedef struct {\\n  VkStructureType sType;\\n  void *pNext;\\n  VkPhysicalDeviceFeatures features;\\n} VkPhysicalDeviceFeatures2;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkFlags srcAccessMask;\\n  VkFlags dstAccessMask;\\n  VkImageLayout oldLayout;\\n  VkImageLayout newLayout;\\n  uint32_t srcQueueFamilyIndex;\\n  uint32_t dstQueueFamilyIndex;\\n  VkImage image;\\n  VkImageSubresourceRange subresourceRange;\\n} VkImageMemoryBarrier;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkFlags srcAccessMask;\\n  VkFlags dstAccessMask;\\n} VkMemoryBarrier;\\n\\ntypedef int32_t VkFilter;\\ntypedef int32_t VkSamplerMipmapMode;\\ntypedef int32_t VkSamplerAddressMode;\\ntypedef int32_t VkBorderColor;\\ntypedef VkFlags VkSamplerCreateFlags;\\n\\ntypedef struct {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkSamplerCreateFlags flags;\\n  VkFilter magFilter;\\n  VkFilter minFilter;\\n  VkSamplerMipmapMode mipmapMode;\\n  VkSamplerAddressMode addressModeU;\\n  VkSamplerAddressMode addressModeV;\\n  VkSamplerAddressMode addressModeW;\\n  float mipLodBias;\\n  VkBool32 anisotropyEnable;\\n  float maxAnisotropy;\\n  VkBool32 compareEnable;\\n  int32_t compareOp;\\n  float minLod;\\n  float maxLod;\\n  VkBorderColor borderColor;\\n  VkBool32 unnormalizedCoordinates;\\n} VkSamplerCreateInfo;\\n\\nVkResult vkGetPhysicalDeviceProperties(VkPhysicalDevice physicalDevice,\\n                                       VkPhysicalDeviceProperties *pProperties);\\n\\nvoid vkGetPhysicalDeviceMemoryProperties(\\n    VkPhysicalDevice physicalDevice,\\n    VkPhysicalDeviceMemoryProperties *pMemoryProperties);\\n\\nvoid vkGetPhysicalDeviceFeatures(VkPhysicalDevice physicalDevice,\\n                                 VkPhysicalDeviceFeatures *pFeatures);\\n\\nvoid vkGetPhysicalDeviceQueueFamilyProperties(\\n    VkPhysicalDevice physicalDevice, uint32_t *pQueueFamilyPropertyCount,\\n    VkQueueFamilyProperties *pQueueFamilyProperties);\\n\\nVkResult vkGetPhysicalDeviceSurfaceCapabilitiesKHR(\\n    VkPhysicalDevice physicalDevice, VkSurfaceKHR surface,\\n    VkSurfaceCapabilitiesKHR *pSurfaceCapabilities);\\n\\nVkResult vkGetPhysicalDeviceSurfaceFormatsKHR(\\n    VkPhysicalDevice physicalDevice, VkSurfaceKHR surface,\\n    uint32_t *pSurfaceFormatCount, VkSurfaceFormatKHR *pSurfaceFormats);\\n\\nVkResult vkGetPhysicalDeviceSurfacePresentModesKHR(\\n    VkPhysicalDevice physicalDevice, VkSurfaceKHR surface,\\n    uint32_t *pPresentModeCount, VkPresentModeKHR *pPresentModes);\\n\\nVkResult vkCreatePipelineLayout(VkDevice device,\\n                                const VkPipelineLayoutCreateInfo *pCreateInfo,\\n                                const VkAllocationCallbacks *pAllocator,\\n                                VkPipelineLayout *pPipelineLayout);\\n\\nVkResult vkCreateGraphicsPipelines(\\n    VkDevice device, VkPipelineCache pipelineCache, uint32_t createInfoCount,\\n    const VkGraphicsPipelineCreateInfo *pCreateInfos,\\n    const VkAllocationCallbacks *pAllocator, VkPipeline *pPipelines);\\n\\nVkResult vkCreateRenderPass(VkDevice device,\\n                            const VkRenderPassCreateInfo *pCreateInfo,\\n                            const VkAllocationCallbacks *pAllocator,\\n                            VkRenderPass *pRenderPass);\\n\\nVkResult vkCreateImageView(VkDevice device,\\n                           const VkImageViewCreateInfo *pCreateInfo,\\n                           const VkAllocationCallbacks *pAllocator,\\n                           VkImageView *pView);\\n\\nVkResult vkCreateFramebuffer(VkDevice device,\\n                             const VkFramebufferCreateInfo *pCreateInfo,\\n                             const VkAllocationCallbacks *pAllocator,\\n                             VkFramebuffer *pFramebuffer);\\n\\nvoid vkGetBufferMemoryRequirements(VkDevice device, VkBuffer buffer,\\n                                   VkMemoryRequirements *pMemoryRequirements);\\n\\nvoid vkGetImageMemoryRequirements(VkDevice device, VkImage image,\\n                                  VkMemoryRequirements *pMemoryRequirements);\\n\\nVkResult vkCreateImage(VkDevice device, const VkImageCreateInfo *pCreateInfo,\\n                       const VkAllocationCallbacks *pAllocator,\\n                       VkImage *pImage);\\n\\nVkResult vkBindImageMemory(VkDevice device, VkImage image,\\n                           VkDeviceMemory memory, VkDeviceSize memoryOffset);\\n\\nvoid vkCmdCopyBufferToImage(VkCommandBuffer commandBuffer, VkBuffer srcBuffer,\\n                            VkImage dstImage, VkImageLayout dstImageLayout,\\n                            uint32_t regionCount,\\n                            const VkBufferImageCopy *pRegions);\\n\\nvoid vkCmdCopyImageToBuffer(VkCommandBuffer commandBuffer, VkImage srcImage,\\n                            VkImageLayout srcImageLayout, VkBuffer dstBuffer,\\n                            uint32_t regionCount,\\n                            const VkBufferImageCopy *pRegions);\\n\\ntypedef struct {\\n  VkDeviceSize srcOffset;\\n  VkDeviceSize dstOffset;\\n  VkDeviceSize size;\\n} VkBufferCopy;\\n\\nvoid vkCmdCopyBuffer(VkCommandBuffer commandBuffer, VkBuffer srcBuffer,\\n                     VkBuffer dstBuffer, uint32_t regionCount,\\n                     const VkBufferCopy *pRegions);\\n\\nVkResult vkAllocateMemory(VkDevice device,\\n                          const VkMemoryAllocateInfo *pAllocateInfo,\\n                          const VkAllocationCallbacks *pAllocator,\\n                          VkDeviceMemory *pMemory);\\n\\nVkResult vkBindBufferMemory(VkDevice device, VkBuffer buffer,\\n                            VkDeviceMemory memory, VkDeviceSize memoryOffset);\\n\\nVkResult vkMapMemory(VkDevice device, VkDeviceMemory memory,\\n                     VkDeviceSize offset, VkDeviceSize size, VkFlags flags,\\n                     void **ppData);\\n\\nvoid vkUnmapMemory(VkDevice device, VkDeviceMemory memory);\\n\\nVkResult vkCreateCommandPool(VkDevice device,\\n                             const VkCommandPoolCreateInfo *pCreateInfo,\\n                             const VkAllocationCallbacks *pAllocator,\\n                             VkCommandPool *pCommandPool);\\n\\nVkResult vkCreateDescriptorSetLayout(\\n    VkDevice device, const VkDescriptorSetLayoutCreateInfo *pCreateInfo,\\n    const VkAllocationCallbacks *pAllocator, VkDescriptorSetLayout *pSetLayout);\\n\\nVkResult vkCreateDescriptorPool(VkDevice device,\\n                                const VkDescriptorPoolCreateInfo *pCreateInfo,\\n                                const VkAllocationCallbacks *pAllocator,\\n                                VkDescriptorPool *pDescriptorPool);\\n\\nVkResult\\nvkAllocateDescriptorSets(VkDevice device,\\n                         const VkDescriptorSetAllocateInfo *pAllocateInfo,\\n                         VkDescriptorSet *pDescriptorSets);\\n\\nvoid vkUpdateDescriptorSets(VkDevice device, uint32_t descriptorWriteCount,\\n                            const VkWriteDescriptorSet *pDescriptorWrites,\\n                            uint32_t descriptorCopyCount,\\n                            const void *pDescriptorCopies);\\n\\nVkResult\\nvkAllocateCommandBuffers(VkDevice device,\\n                         const VkCommandBufferAllocateInfo *pAllocateInfo,\\n                         VkCommandBuffer *pCommandBuffers);\\n\\nVkResult vkBeginCommandBuffer(VkCommandBuffer commandBuffer,\\n                              const VkCommandBufferBeginInfo *pBeginInfo);\\n\\nVkResult vkEndCommandBuffer(VkCommandBuffer commandBuffer);\\n\\nvoid vkCmdBeginRenderPass(VkCommandBuffer commandBuffer,\\n                          const VkRenderPassBeginInfo *pRenderPassBegin,\\n                          VkSubpassContents contents);\\n\\nvoid vkCmdEndRenderPass(VkCommandBuffer commandBuffer);\\n\\nvoid vkCmdBindPipeline(VkCommandBuffer commandBuffer,\\n                       VkPipelineBindPoint pipelineBindPoint,\\n                       VkPipeline pipeline);\\n\\nvoid vkCmdDraw(VkCommandBuffer commandBuffer, uint32_t vertexCount,\\n               uint32_t instanceCount, uint32_t firstVertex,\\n               uint32_t firstInstance);\\n\\nVkResult vkQueueSubmit(VkQueue queue, uint32_t submitCount,\\n                       const VkSubmitInfo *pSubmits, uint64_t fence);\\n\\nVkResult vkQueueWaitIdle(VkQueue queue);\\n\\nvoid vkGetDeviceQueue(VkDevice device, uint32_t queueFamilyIndex,\\n                      uint32_t queueIndex, VkQueue *pQueue);\\n\\nVkResult vkCreateSemaphore(VkDevice device,\\n                           const VkSemaphoreCreateInfo *pCreateInfo,\\n                           const VkAllocationCallbacks *pAllocator,\\n                           VkSemaphore *pSemaphore);\\n\\nVkResult vkCreateFence(VkDevice device, const VkFenceCreateInfo *pCreateInfo,\\n                       const VkAllocationCallbacks *pAllocator,\\n                       VkFence *pFence);\\n\\nVkResult vkCreateSwapchainKHR(VkDevice device,\\n                              const VkSwapchainCreateInfoKHR *pCreateInfo,\\n                              const VkAllocationCallbacks *pAllocator,\\n                              VkSwapchainKHR *pSwapchain);\\n\\nVkResult vkGetSwapchainImagesKHR(VkDevice device, VkSwapchainKHR swapchain,\\n                                 uint32_t *pSwapchainImageCount,\\n                                 VkImage *pSwapchainImages);\\n\\nVkResult vkAcquireNextImageKHR(VkDevice device, VkSwapchainKHR swapchain,\\n                               uint64_t timeout, VkSemaphore semaphore,\\n                               VkFence fence, uint32_t *pImageIndex);\\n\\nVkResult vkQueuePresentKHR(VkQueue queue, const VkPresentInfoKHR *pPresentInfo);\\n\\nVkResult vkGetPhysicalDeviceFeatures2(VkPhysicalDevice physicalDevice,\\n                                       VkPhysicalDeviceFeatures2 *pFeatures);\\n\\nvoid vkCmdUpdateBuffer(VkCommandBuffer commandBuffer, VkBuffer dstBuffer,\\n                       VkDeviceSize dstOffset, VkDeviceSize dataSize,\\n                       const void *pData);\\n\\nVkResult vkWaitForFences(VkDevice device, uint32_t fenceCount,\\n                         const VkFence *pFences, VkBool32 waitAll,\\n                         uint64_t timeout);\\n\\nVkResult vkResetFences(VkDevice device, uint32_t fenceCount,\\n                       const VkFence *pFences);\\n\\nvoid vkCmdSetViewport(VkCommandBuffer commandBuffer, uint32_t firstViewport,\\n                      uint32_t viewportCount, const VkViewport *pViewports);\\n\\nvoid vkCmdSetScissor(VkCommandBuffer commandBuffer, uint32_t firstScissor,\\n                     uint32_t scissorCount, const VkRect2D *pScissors);\\n\\nvoid vkCmdBindVertexBuffers(VkCommandBuffer commandBuffer,\\n                            uint32_t firstBinding, uint32_t bindingCount,\\n                            const VkBuffer *pBuffers,\\n                            const VkDeviceSize *pOffsets);\\n\\ntypedef int32_t VkIndexType;\\n\\nvoid vkCmdBindIndexBuffer(VkCommandBuffer commandBuffer, VkBuffer buffer,\\n                          VkDeviceSize offset, VkIndexType indexType);\\n\\nvoid vkCmdDrawIndexed(VkCommandBuffer commandBuffer, uint32_t indexCount,\\n                      uint32_t instanceCount, uint32_t firstIndex,\\n                      int32_t vertexOffset, uint32_t firstInstance);\\n\\n/* Parameters for one indexed draw read from a buffer instead of written into\\n   the command stream. stride in vkCmdDrawIndexedIndirect is the distance\\n   between consecutive commands, so an array of these carries a whole frame's\\n   draws in one call. firstInstance needs the drawIndirectFirstInstance\\n   feature, which is universally available on desktop. */\\ntypedef struct {\\n  uint32_t indexCount;\\n  uint32_t instanceCount;\\n  uint32_t firstIndex;\\n  int32_t vertexOffset;\\n  uint32_t firstInstance;\\n} VkDrawIndexedIndirectCommand;\\n\\nvoid vkCmdDrawIndexedIndirect(VkCommandBuffer commandBuffer, VkBuffer buffer,\\n                              VkDeviceSize offset, uint32_t drawCount,\\n                              uint32_t stride);\\n\\ntypedef uint32_t VkXlibSurfaceCreateFlagsKHR;\\ntypedef uint32_t VkWin32SurfaceCreateFlagsKHR;\\n\\ntypedef struct VkXlibSurfaceCreateInfoKHR {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkXlibSurfaceCreateFlagsKHR flags;\\n  void *dpy;\\n  uint64_t window;\\n} VkXlibSurfaceCreateInfoKHR;\\n\\ntypedef struct VkWin32SurfaceCreateInfoKHR {\\n  VkStructureType sType;\\n  const void *pNext;\\n  VkWin32SurfaceCreateFlagsKHR flags;\\n  void *hinstance;\\n  void *hwnd;\\n} VkWin32SurfaceCreateInfoKHR;\\n\\nVkResult vkCreateXlibSurfaceKHR(VkInstance instance,\\n                                const VkXlibSurfaceCreateInfoKHR *pCreateInfo,\\n                                const VkAllocationCallbacks *pAllocator,\\n                                VkSurfaceKHR *pSurface);\\n\\nVkResult vkCreateWin32SurfaceKHR(VkInstance instance,\\n                                 const VkWin32SurfaceCreateInfoKHR *pCreateInfo,\\n                                 const VkAllocationCallbacks *pAllocator,\\n                                 VkSurfaceKHR *pSurface);\\n\\nVkResult vkCreateSampler(VkDevice device,\\n                         const VkSamplerCreateInfo *pCreateInfo,\\n                         const VkAllocationCallbacks *pAllocator,\\n                         VkSampler *pSampler);\\n\\nvoid vkDestroySampler(VkDevice device, VkSampler sampler,\\n                      const VkAllocationCallbacks *pAllocator);\\n\\nVkResult vkCreateComputePipelines(\\n    VkDevice device, VkPipelineCache pipelineCache, uint32_t createInfoCount,\\n    const VkComputePipelineCreateInfo *pCreateInfos,\\n    const VkAllocationCallbacks *pAllocator, VkPipeline *pPipelines);\\n\\nvoid vkCmdDispatch(VkCommandBuffer commandBuffer, uint32_t groupCountX,\\n                   uint32_t groupCountY, uint32_t groupCountZ);\\n\\nvoid vkCmdPushConstants(VkCommandBuffer commandBuffer, VkPipelineLayout layout,\\n                        VkShaderStageFlags stageFlags, uint32_t offset,\\n                        uint32_t size, const void *pValues);\\n\\nvoid vkCmdPipelineBarrier(VkCommandBuffer commandBuffer, VkFlags srcStageMask,\\n                          VkFlags dstStageMask, VkFlags dependencyFlags,\\n                          uint32_t memoryBarrierCount,\\n                          const void *pMemoryBarriers,\\n                          uint32_t bufferMemoryBarrierCount,\\n                          const void *pBufferMemoryBarriers,\\n                          uint32_t imageMemoryBarrierCount,\\n                          const VkImageMemoryBarrier *pImageMemoryBarriers);\\n\")\n\nlocal vkEnums = require(\"vkapi.ffi.enums\")\n\n---@class vk: vk.RawEnums\n---@field ApplicationInfo fun(init: vk.ffi.ApplicationInfo?): vk.ffi.ApplicationInfo\n---@field InstanceCreateInfo fun(init: vk.ffi.InstanceCreateInfo?): vk.ffi.InstanceCreateInfo\n---@field DeviceQueueCreateInfo fun(init: vk.ffi.DeviceQueueCreateInfo?): vk.ffi.DeviceQueueCreateInfo\n---@field DeviceCreateInfo fun(init: vk.ffi.DeviceCreateInfo?): vk.ffi.DeviceCreateInfo\n---@field BufferCreateInfo fun(init: vk.ffi.BufferCreateInfo?): vk.ffi.BufferCreateInfo\n---@field ShaderModuleCreateInfo fun(init: vk.ffi.ShaderModuleCreateInfo?): vk.ffi.ShaderModuleCreateInfo\n---@field PipelineLayoutCreateInfo fun(init: vk.ffi.PipelineLayoutCreateInfo?): vk.ffi.PipelineLayoutCreateInfo\n---@field PipelineShaderStageCreateInfo fun(init: vk.ffi.PipelineShaderStageCreateInfo?): vk.ffi.PipelineShaderStageCreateInfo\n---@field PipelineVertexInputStateCreateInfo fun(init: vk.ffi.PipelineVertexInputStateCreateInfo?): vk.ffi.PipelineVertexInputStateCreateInfo\n---@field PipelineInputAssemblyStateCreateInfo fun(init: vk.ffi.PipelineInputAssemblyStateCreateInfo?): vk.ffi.PipelineInputAssemblyStateCreateInfo\n---@field PipelineViewportStateCreateInfo fun(init: vk.ffi.PipelineViewportStateCreateInfo?): vk.ffi.PipelineViewportStateCreateInfo\n---@field PipelineRasterizationStateCreateInfo fun(init: vk.ffi.PipelineRasterizationStateCreateInfo?): vk.ffi.PipelineRasterizationStateCreateInfo\n---@field PipelineMultisampleStateCreateInfo fun(init: vk.ffi.PipelineMultisampleStateCreateInfo?): vk.ffi.PipelineMultisampleStateCreateInfo\n---@field PipelineDepthStencilStateCreateInfo fun(init: vk.ffi.PipelineDepthStencilStateCreateInfo?): vk.ffi.PipelineDepthStencilStateCreateInfo\n---@field PipelineColorBlendStateCreateInfo fu