of the text over it.\n-- A highlight of the text's own colour would be invisible on a background of a shade near it, which\n-- is the one thing a highlight cannot be.\nlocal SELECTION_R, SELECTION_G, SELECTION_B = 0.23, 0.51, 0.96\nlocal SELECTION_TEXT_R, SELECTION_TEXT_G, SELECTION_TEXT_B = 1.0, 1.0, 1.0\n\n-- How wide a highlight is at the least, which is what an empty line inside a selection is drawn as:\n-- a line of nothing selected still has to look like it is part of what is selected.\nlocal SELECTION_LEAST = 6\n\n-- A byte past the end of a line, which is what a click at the left of a right-to-left line comes to:\n-- the bytes of such a line run from its right, so its left end is past every byte of it. The layout\n-- clamps a column past the end of a line to the end of it -- see `Layout:setCaret`.\nlocal PAST_THE_LINE = 1 << 24\n\n---@class wonderland.plugin.UI.Clip\n---@field left number\n---@field top number\n---@field right number\n---@field bottom number\n\n---@param batch wonderland.QuadBatch\n---@param clip wonderland.plugin.UI.Clip\n---@param windowWidth number\n---@param windowHeight number\n---@param left number\n---@param top number\n---@param right number\n---@param bottom number\n---@param z number\n---@param r number\n---@param g number\n---@param b number\n---@param a number\n---@param texture number\n---@param u0 number\n---@param v0 number\n---@param u1 number\n---@param v1 number\n---@param radius number? # How round the box's corners are, in pixels, nothing for square ones\n---@param band number? # How sharp the edge of it is, one pixel either side by default\n---@param grow number? # How far past the box the quad is drawn: a shadow is its own blur\nlocal function clippedQuad(batch, clip, windowWidth, windowHeight, left, top, right, bottom, z, r, g, b, a,\n\ttexture, u0, v0, u1, v1, radius, band, grow, own)\n\t-- A quad that is drawn past its box is one whose edge is spread out, so what is drawn is the\n\t-- box and the space the spreading needs; the box itself is what the corner arithmetic is about.\n\tlocal drawnLeft, drawnTop = left - (grow or 0), top - (grow or 0)\n\tlocal drawnRight, drawnBottom = right + (grow or 0), bottom + (grow or 0)\n\t-- The quad the box asked for, when all of it shows. Most quads are inside the clip -- only the\n\t-- ones at the edge of a pane that scrolls are not -- and working out where a quad is cut costs\n\t-- a pair of divisions, so the ones that need nothing are the ones that get nothing.\n\tif drawnLeft >= clip.left and drawnTop >= clip.top and drawnRight <= clip.right and drawnBottom <= clip.bottom then\n\t\t-- Cut and square are a call each rather than one argument to the same call: they are not\n\t\t-- drawn in the same numbers, and a screen of text is nearly all of one of them.\n\t\tif band or (radius and radius > 0) then\n\t\t\tbatch:roundQuad(\n\t\t\t\ttoNDC(drawnLeft, windowWidth),\n\t\t\t\t-toNDC(drawnTop, windowHeight),\n\t\t\t\ttoNDC(drawnRight, windowWidth),\n\t\t\t\t-toNDC(drawnBottom, windowHeight),\n\t\t\t\tz,\n\t\t\t\tr, g, b, a,\n\t\t\t\ttexture,\n\t\t\t\tu0, v0, u1, v1,\n\t\t\t\tradius or 0,\n\t\t\t\ttoNDC(left, windowWidth),\n\t\t\t\t-toNDC(top, windowHeight),\n\t\t\t\ttoNDC(right, windowWidth),\n\t\t\t\t-toNDC(bottom, windowHeight),\n\t\t\t\tband,\n\t\t\t\town\n\t\t\t)\n\t\telse\n\t\t\tbatch:quad(\n\t\t\t\ttoNDC(left, windowWidth),\n\t\t\t\t-toNDC(top, windowHeight),\n\t\t\t\ttoNDC(right, windowWidth),\n\t\t\t\t-toNDC(bottom, windowHeight),\n\t\t\t\tz,\n\t\t\t\tr, g, b, a,\n\t\t\t\ttexture,\n\t\t\t\tu0, v0, u1, v1,\n\t\t\t\town\n\t\t\t)\n\t\tend\n\n\t\treturn\n\tend\n\n\tlocal atLeft = drawnLeft < clip.left and clip.left or drawnLeft\n\tlocal atTop = drawnTop < clip.top and clip.top or drawnTop\n\tlocal atRight = drawnRight > clip.right and clip.right or drawnRight\n\tlocal atBottom = drawnBottom > clip.bottom and clip.bottom or drawnBottom\n\n\tif atRight <= atLeft or atBottom <= atTop then\n\t\treturn\n\tend\n\n\tlocal du = (u1 - u0) / (drawnRight - drawnLeft)\n\tlocal dv = (v1 - v0) / (drawnBottom - drawnTop)\n\n\t-- What is drawn is what is inside the clip but the corners are the corners of the whole box: a\n\t-- box cut down to a sliver by the pane it is in is still a box with round corners, and the\n\t-- corners of the sliver are not corners of it.\n\tif band or (radius and radius > 0) then\n\t\tbatch:roundQuad(\n\t\t\ttoNDC(atLeft, windowWidth),\n\t\t\t-toNDC(atTop, windowHeight),\n\t\t\ttoNDC(atRight, windowWidth),\n\t\t\t-toNDC(atBottom, windowHeight),\n\t\t\tz,\n\t\t\tr, g, b, a,\n\t\t\ttexture,\n\t\t\tu0 + du * (atLeft - drawnLeft), v0 + dv * (atTop - drawnTop),\n\t\t\tu0 + du * (atRight - drawnLeft), v0 + dv * (atBottom - drawnTop),\n\t\t\tradius or 0,\n\t\t\ttoNDC(left, windowWidth),\n\t\t\t-toNDC(top, windowHeight),\n\t\t\ttoNDC(right, windowWidth),\n\t\t\t-toNDC(bottom, windowHeight),\n\t\t\tband,\n\t\t\town\n\t\t)\n\n\t\treturn\n\tend\n\n\tbatch:quad(\n\t\ttoNDC(atLeft, windowWidth),\n\t\t-toNDC(atTop, windowHeight),\n\t\ttoNDC(atRight, windowWidth),\n\t\t-toNDC(atBottom, windowHeight),\n\t\tz,\n\t\tr, g, b, a,\n\t\ttexture,\n\t\tu0 + du * (atLeft - drawnLeft), v0 + dv * (atTop - drawnTop),\n\t\tu0 + du * (atRight - drawnLeft), v0 + dv * (atBottom - drawnTop),\n\t\town\n\t)\nend\n\n---@param batch wonderland.QuadBatch\n---@param bx number\n---@param by number\n---@param bw number\n---@param bh number\n---@param r number\n---@param g number\n---@param b number\n---@param a number\n---@param z number\n---@param windowWidth number\n---@param windowHeight number\nlocal function addBorderQuad(batch, clip, bx, by, bw, bh, r, g, b, a, z, windowWidth, windowHeight)\n\tif bw <= 0 or bh <= 0 then\n\t\treturn\n\tend\n\n\tclippedQuad(batch, clip, windowWidth, windowHeight, bx, by, bx + bw, by + bh, convertZ(z + 1), r, g, b, a, 0,\n\t\t0, 0, 1, 1)\nend\n\n--- A line is drawn from the run it measured into, which is where its glyphs are. A run of\n--- several lines is drawn line by line, each of them placed in the box on its own: a line that\n--- is not as wide as the box is aligned by its own width, not by the widest one in the run.\n---@param batch wonderland.QuadBatch\n---@param run wonderland.font.Run\n---@param node wonderland.Node\n---@param x number # Absolute, so the glyphs land on whole pixels\n---@param y number\n---@param z number\n---@param fontManager FontManager\n---@param windowWidth number\n---@param windowHeight number\n---@param value string? # What the run was measured from, where a selection is counted in its bytes\n---@param from number? # The first byte of it a selection covers, where there is one\n---@param to number?\nlocal function generateTextQuads(batch, clip, run, node, x, y, z, fontManager, windowWidth, windowHeight,\n\tvalue, from, to)\n\tlocal r, g, b = node.fgR / 255, node.fgG / 255, node.fgB / 255\n\tlocal selecting = value ~= nil and from ~= nil and to ~= nil and from < to\n\tlocal lineBase = 0\n\n\t-- The picture a glyph is drawn from is the one it was measured in, because a line may be drawn\n\t-- by more than one face: a character the font an app named has no glyph for is drawn from the\n\t-- face after it in the chain, and the run's glyphs name the picture each of them is in. What\n\t-- the font itself answers with is where a glyph with no picture of its own is drawn from, which\n\t-- is a glyph of a font that was measured with no gpu under it.\n\tlocal font = node.font ~= 0 and fontManager:get(node.font - 1)\n\t\tor assert(fontManager:getDefault(), \"No font to draw text with: load one and make it the default\")\n\n\tlocal zIndex = convertZ(z)\n\n\t-- One array of glyphs and one of lines, read by index: the run was measured as structs, so\n\t-- drawing a line costs a handful of loads rather than a table lookup per glyph.\n\tfor lineIndex = 0, run.lineCount - 1 do\n\t\tlocal line = run.lines[lineIndex]\n\n\t\t-- A line may be given more room than it needs, and then it says where in that room it sits.\n\t\tlocal offset = 0\n\t\tif node.justify == 1 then\n\t\t\toffset = math.floor((node.width - line.width) / 2 + 0.5)\n\t\telseif node.justify == 2 then\n\t\t\toffset = node.width - line.width\n\t\tend\n\n\t\tlocal originX = x + offset\n\n\t\tfor at = 0, line.count - 1 do\n\t\t\tlocal glyph = assert(run.glyphs)[line.first + at]\n\t\t\tlocal picture = glyph.texture ~= 0 and glyph.texture or font:picture()\n\t\t\tlocal gr, gg, gb = r, g, b\n\n\t\t\t-- A glyph the selection covers is drawn in the colour that reads on the highlight rather\n\t\t\t-- than in the colour of the text: what a glyph came from is the byte it kept, so which\n\t\t\t-- side of the selection it is on is a comparison of bytes.\n\t\t\tif selecting then\n\t\t\t\tlocal byte = lineBase + glyph.cluster\n\n\t\t\t\tif byte >= from and byte < to then\n\t\t\t\t\tgr, gg, gb = SELECTION_TEXT_R, SELECTION_TEXT_G, SELECTION_TEXT_B\n\t\t\t\tend\n\t\t\tend\n\n\t\t\t-- A glyph that is a picture of its own -- an emoji -- is drawn as the picture rather\n\t\t\t-- than through the text's colour: what the colour is of it is how opaque the element is.\n\t\t\tclippedQuad(batch, clip, windowWidth, windowHeight, originX + glyph.x, y + glyph.y,\n\t\t\t\toriginX + glyph.x + glyph.width, y + glyph.y + glyph.height, zIndex, gr, gg, gb,\n\t\t\t\tnode.fgA / 255, picture, glyph.u0, glyph.v0, glyph.u1, glyph.v1, nil, nil, nil,\n\t\t\t\tglyph.own)\n\t\tend\n\n\t\tif selecting then\n\t\t\tlocal break_ = value:find(\"\\n\", lineBase + 1, true)\n\n\t\t\tif break_ ~= nil then\n\t\t\t\tlineBase = break_\n\t\t\tend\n\t\tend\n\tend\nend\n\n--- Where the caret is, as the pen it sits at, given the byte of the line it is at.\n---\n--- A glyph is not a character, so the byte is looked up among the glyphs and what is answered is the\n--- pen that glyph was placed at. A line that reads right to left runs the other way: the caret for a\n--- byte is at the far edge of the glyphs that byte came from.\n---@param run wonderland.font.Run\n---@param line number\n---@param byte number # How many bytes of that line come before the caret\n---@return number pen # From the left edge of the run\n---@return number lineStep # How tall a line of it is, which the caret is drawn no taller than\nlocal function caretPen(run, line, byte)\n\tlocal lineStep = run.height / run.lineCount\n\tlocal glyphs = run.glyphs\n\tlocal glyphLine = run.lines[line] ---@type wonderland.font.Line\n\n\tif glyphs == nil or glyphLine == nil or glyphLine.count <= 0 then\n\t\treturn 0, lineStep\n\tend\n\n\tlocal first, count = glyphLine.first, glyphLine.count\n\n\t-- A glyph is not always the whole of a character: a mark sits on a letter, in the same bytes, and\n\t-- is placed where it is placed. So a byte is worth the edge of the group its glyphs make -- the\n\t-- right edge of it where the line reads right to left, the left where it does not.\n\tif glyphLine.rtl ~= 0 then\n\t\tlocal pen = nil\n\n\t\tfor at = 0, count - 1 do\n\t\t\tlocal glyph = glyphs[first + at]\n\n\t\t\tif glyph.cluster >= byte then\n\t\t\t\tlocal edge = glyph.pen + glyph.advance\n\n\t\t\t\tif pen == nil or edge > pen then\n\t\t\t\t\tpen = edge\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\n\t\treturn pen or 0, lineStep\n\tend\n\n\tlocal pen = nil\n\n\tfor at = 0, count - 1 do\n\t\tlocal glyph = glyphs[first + at]\n\n\t\tif glyph.cluster >= byte and (pen == nil or glyph.pen < pen) then\n\t\t\tpen = glyph.pen\n\t\tend\n\tend\n\n\tif pen ~= nil then\n\t\treturn pen, lineStep\n\tend\n\n\t-- A byte past every glyph puts the caret where the line stops rather than nowhere.\n\treturn glyphLine.width, lineStep\nend\n\n--- Where a line of a run is drawn inside the box it is in: a line may be given more room than it\n--- needs, and then it says where in that room it sits -- which is where the glyphs of it are drawn,\n--- and so where the caret beside them goes and where a click on them lands.\n---@param node wonderland.Node\n---@param line wonderland.font.Line?\n---@return number # From the left edge of the box\nlocal function lineOffset(node, line)\n\tif line == nil or node.run == 0 then\n\t\treturn 0\n\tend\n\n\tif node.justify == 1 then\n\t\treturn math.floor((node.width - line.width) / 2 + 0.5)\n\telseif node.justify == 2 then\n\t\treturn node.width - line.width\n\tend\n\n\treturn 0\nend\n\n--- The run a field's caret and its selection are placed against: the value, measured in the font\n--- the field is drawn in -- what a line is drawn in is what its parents said unless it named one\n--- itself -- and cut to the box where the field cuts its line, so that a caret lands in the text\n--- that is on screen rather than in the text that was too long for it. See `wonderland.plugin.Layout`,\n--- which is where a line is cut.\n---@param element wonderland.Element\n---@param node wonderland.Node\n---@param value string\n---@param fontManager FontManager\n---@return wonderland.font.Run\nlocal function fieldRun(element, node, value, fontManager)\n\tlocal font = element.fontId ~= 0 and fontManager:get(element.fontId)\n\t\tor assert(fontManager:getDefault(), \"No font to draw text with: load one and make it the default\")\n\tlocal maxWidth = bit.band(node.styleFlags, style.PRESENT.ellipsis) ~= 0\n\t\t\tand (node.width - node.paddingLeft - node.paddingRight)\n\t\tor nil\n\n\treturn font:getRun(value, maxWidth)\nend\n\n--- The quads a selection is drawn as: on every line it touches, the room between the two bytes of it\n--- on that line, in the pens that line was drawn along. The pens are the caret's own -- a caret and\n--- the highlight beside it agree about where a character is -- and where the selection runs off the\n--- end of a line, the room it comes to is the ink of the line rather than the advance of it: the room\n--- a line takes goes on past its last letter, over the space after it and the bearings either side,\n--- and a highlight drawn to there is a blue box with nothing in it.\n---\n--- What it is drawn in is the blue a selection is drawn in everywhere, and what the text over it is\n--- drawn in is the colour that reads on that blue -- see `generateTextQuads`.\n---@param batch wonderland.QuadBatch\n---@param clip wonderland.plugin.UI.Clip\n---@param caret wonderland.plugin.UI.Caret\n---@param element wonderland.Element\n---@param node wonderland.Node\n---@param x number\n---@param y number\n---@param z number\n---@param fontManager FontManager\n---@param windowWidth number\n---@param windowHeight number\nlocal function selectionQuads(batch, clip, caret, element, node, x, y, z, fontManager, windowWidth, windowHeight)\n\tlocal value = strings[caret.value]\n\tlocal from, to = caret.from, caret.to\n\n\tif value == nil or from == nil or to == nil or from >= to then\n\t\treturn\n\tend\n\n\tlocal run = fieldRun(element, node, value, fontManager)\n\tlocal lineStep = run.height / run.lineCount\n\tlocal zIndex = convertZ(z)\n\tlocal start = 1\n\n\tfor line = 0, run.lineCount - 1 do\n\t\tlocal newline = value:find(\"\\n\", start, true)\n\t\t-- The line's own bytes of the value, as the half open range a selection is counted in.\n\t\tlocal lineFrom, lineTo = start - 1, (newline or #value + 1) - 1\n\t\tlocal first, last = math.max(from, lineFrom), math.min(to, lineTo)\n\t\tlocal whole = from <= lineFrom and to > lineTo\n\n\t\tif first < last or whole then\n\t\t\tlocal glyphLine = run.lines[line] ---@type wonderland.font.Line\n\t\t\tlocal offset = lineOffset(node, glyphLine)\n\t\t\t-- Both pens are taken into locals first: a call in the last argument of `math.min` is a\n\t\t\t-- call that hands over *all* of what it returns, and `caretPen` answers with the pen and\n\t\t\t-- the height of a line -- which is a left edge a line's height away from the right one.\n\t\t\tlocal penFirst = caretPen(run, line, first - lineFrom)\n\t\t\tlocal penLast = caretPen(run, line, last - lineFrom)\n\t\t\tlocal left = math.min(penFirst, penLast)\n\t\t\tlocal right = math.max(penFirst, penLast)\n\n\t\t\tif last == first then\n\t\t\t\tright = left + SELECTION_LEAST\n\t\t\tend\n\n\t\t\t-- Where the ink of the line is, which is what an end of the selection that leaves the line\n\t\t\t-- is drawn to: the advance of a line carries on past its last letter, so a selection of the\n\t\t\t-- whole of it would otherwise be a blue box with a space's worth of nothing in it.\n\t\t\tlocal inkedLeft, inkedRight = nil, nil\n\t\t\tlocal glyphs = assert(run.glyphs)\n\n\t\t\tfor at = 0, glyphLine.count - 1 do\n\t\t\t\tlocal glyph = glyphs[glyphLine.first + at]\n\n\t\t\t\tif glyph.width > 0 then\n\t\t\t\t\tinkedLeft = math.min(inkedLeft or glyph.x, glyph.x)\n\t\t\t\t\tinkedRight = math.max(inkedRight or (glyph.x + glyph.width), glyph.x + glyph.width)\n\t\t\t\tend\n\t\t\tend\n\n\t\t\tif from <= lineFrom and inkedLeft ~= nil then\n\t\t\t\tleft = inkedLeft\n\t\t\tend\n\n\t\t\tif to >= lineTo and inkedRight ~= nil then\n\t\t\t\tright = inkedRight\n\t\t\tend\n\n\t\t\tclippedQuad(batch, clip, windowWidth, windowHeight, x + offset + left, y + line * lineStep,\n\t\t\t\tx + offset + right, y + line * lineStep + lineStep, zIndex, SELECTION_R, SELECTION_G,\n\t\t\t\tSELECTION_B, 1.0, 0, 0, 0, 1, 1)\n\t\tend\n\n\t\tstart = lineTo + 2\n\tend\nend\n\n--- Where the caret of a field is drawn this frame, and what it is drawn as, kept on the caret the\n--- walk was handed: a frame is built once and the quad of it is drawn last, so what a blink needs\n--- to put back is the whole of what is decided here.\n---\n--- What it is placed from is a line of text -- the one the field draws, or the field's own content\n--- origin where it draws none -- so `x` and `y` are that line's top left corner rather than the\n--- field's: where a field puts the text it draws is the app's, and a field that centres it is one\n--- whose caret is beside the text rather than at the top of the box.\n---@param caret wonderland.plugin.UI.Caret\n---@param element wonderland.Element # What the line belongs to, which is where its font is\n---@param node wonderland.Node # The node it is drawn as, which is what says how it is aligned\n---@param x number # Absolute, as the walk has it\n---@param y number\n---@param z number\n---@param clip wonderland.plugin.UI.Clip\n---@param fontManager FontManager\nlocal function placeCaret(caret, element, node, x, y, z, clip, fontManager)\n\tlocal value = strings[caret.value]\n\tlocal run = fieldRun(element, node, value, fontManager)\n\tlocal pen, lineStep = caretPen(run, caret.line, caret.column)\n\tlocal height = lineStep - CARET_INSET * 2\n\tlocal line = run.lines[caret.line] ---@type wonderland.font.Line\n\n\t-- A line that is given more room than it needs sits where it says in it, which is where it is\n\t-- drawn: the caret goes with it, and a line with no room of its own starts at nought.\n\tcaret.left = x + lineOffset(node, line) + pen\n\tcaret.top = y + caret.line * lineStep + CARET_INSET\n\tcaret.right = caret.left + CARET_WIDTH\n\tcaret.bottom = caret.top + (height > 0 and height or lineStep)\n\tcaret.z = z + 2\n\tcaret.clip = clip\n\tcaret.placed = true\nend\n\n--- The first line of text drawn inside an element, and where it ended up: the line a caret is\n--- placed from, found the way the walk finds it -- the field's own, if it draws one, and otherwise\n--- the first line of whatever it draws.\n---@param screen wonderland.Layout.Screen\n---@param index number\n---@param parentX number\n---@param parentY number\n---@param element wonderland.Element\n---@param inField boolean?\n---@return wonderland.Node? node\n---@return number? x\n---@return number? y\n---@return wonderland.font.Run? run\nlocal function findFieldText(screen, index, parentX, parentY, element, inField)\n\tlocal node = screen:node(index)\n\tlocal x, y = parentX + node.x, parentY + node.y\n\tlocal inside = inField or pointers[node.element] == element\n\n\tif inside and node.run ~= 0 and node.visible ~= 0 then\n\t\treturn node, x, y, screen.runs[node.run]\n\tend\n\n\tfor at = 0, node.childCount - 1 do\n\t\tlocal foundNode, foundX, foundY, foundRun = findFieldText(screen,\n\t\t\tscreen.childIndices[node.firstChild + at - 1], x, y, element, inside)\n\n\t\tif foundNode ~= nil then\n\t\t\treturn foundNode, foundX, foundY, foundRun\n\t\tend\n\tend\n\n\treturn nil\nend\n\n--- Where a point in a line of text is, as a line and a byte of it. A point past the end of a line is\n--- the end of that line; one above the first line or below the last is the first or the last.\n\n--- What a glyph came from is the byte it kept, so a click lands at a character boundary.\n---@param run wonderland.font.Run\n---@param node wonderland.Node # What the line is drawn as, which is what says how it is aligned\n---@param x number # Absolute, where the line starts\n---@param y number\n---@param pointX number\n---@param pointY number\n---@return number line\n---@return number byte # How many bytes of that line come before the caret\nlocal function caretAtPoint(run, node, x, y, pointX, pointY)\n\tlocal step = run.height / run.lineCount\n\tlocal line = math.floor((pointY - y) / step)\n\n\tif line < 0 then\n\t\tline = 0\n\telseif line > run.lineCount - 1 then\n\t\tline = run.lineCount - 1\n\tend\n\n\tlocal glyphLine = run.lines[line] ---@type wonderland.font.Line\n\tlocal glyphs = run.glyphs\n\n\tif glyphLine == nil or glyphs == nil or glyphLine.count <= 0 then\n\t\treturn line, 0\n\tend\n\n\t-- Measured from the same left edge and across the same pens the line was drawn along, so a click\n\t-- between two glyphs puts the caret where those two glyphs are.\n\tlocal first, count = glyphLine.first, glyphLine.count\n\tlocal target = pointX - x - lineOffset(node, glyphLine)\n\n\t-- A line that reads right to left is drawn from the right, so a gap between two of its glyphs is\n\t-- the byte the glyph on the right of the gap came from, and the gap at its far left is the end of\n\t-- the line.\n\tif glyphLine.rtl ~= 0 then\n\t\tfor at = 0, count - 1 do\n\t\t\tlocal glyph = glyphs[first + at]\n\n\t\t\tif target < glyph.pen + glyph.advance / 2 then\n\t\t\t\treturn line, at > 0 and glyphs[first + at - 1].cluster or PAST_THE_LINE\n\t\t\tend\n\t\tend\n\n\t\treturn line, glyphs[first + count - 1].cluster\n\tend\n\n\tlocal best, bestDistance = PAST_THE_LINE, math.abs(glyphLine.width - target)\n\n\tfor at = 0, count - 1 do\n\t\tlocal glyph = glyphs[first + at]\n\t\tlocal distance = math.abs(glyph.pen - target)\n\n\t\tif distance < bestDistance then\n\t\t\tbest, bestDistance = glyph.cluster, distance\n\t\tend\n\tend\n\n\treturn line, best\nend\n\n---@param batch wonderland.QuadBatch\n---@param caret wonderland.plugin.UI.Caret\n---@param windowWidth number\n---@param windowHeight number\nlocal function addCaretQuad(batch, caret, windowWidth, windowHeight)\n\tif not caret.placed then\n\t\treturn\n\tend\n\n\tclippedQuad(batch, caret.clip, windowWidth, windowHeight, caret.left, caret.top, caret.right,\n\t\tcaret.bottom, convertZ(caret.z), caret.r, caret.g, caret.b, caret.a, 0, 0, 0, 1, 1)\nend\n\n--- Walks the laid out screen, which is an array of nodes: a walk is an index and an\n--- offset, and children are reached through the runs of child indices.\n---@param batch wonderland.QuadBatch\n---@param screen wonderland.Layout.Screen\n---@param index number\n---@param parentX number\n---@param parentY number\n---@param windowWidth number\n---@param windowHeight number\n---@param parentZ number?\n---@param fontManager FontManager\n---@param caret wonderland.plugin.UI.Caret? # The caret of the field that has the keyboard, if one has it\n---@param inField boolean? # Whether this node is inside that field, which is where the caret is\n---@param canvas wonderland.Canvas # What an element that draws its own shapes draws them with\nlocal function generateNodeQuads(batch, screen, clip, index, parentX, parentY, windowWidth, windowHeight, parentZ,\n\tfontManager, caret, inField, canvas)\n\tlocal node = screen:node(index)\n\tlocal x, y = parentX + node.x, parentY + node.y\n\tlocal z = math.max(node.zIndex, parentZ or 0)\n\n\t-- The element behind this node, which is what says whether it has a canvas of its own to draw\n\t-- and which field it belongs to. The caret's half of that is only looked at when there is a\n\t-- caret to place: a screen with no field focused has nothing to compare against.\n\tlocal here = pointers[node.element]\n\tlocal element = caret and here or nil\n\tlocal inside = inField or (caret ~= nil and element ~= nil and element == caret.element)\n\n\t-- The colour of a caret is the field's, wherever in it the caret turns out to be placed from:\n\t-- one nothing named a colour for is drawn white, since a field whose text cannot be seen is one\n\t-- whose caret should at least be there.\n\tif caret ~= nil and inside and not inField and element ~= nil and element == caret.element then\n\t\tlocal field = node\n\n\t\tif field.fgA == 0 then\n\t\t\tcaret.r, caret.g, caret.b, caret.a = WHITE_R, WHITE_G, WHITE_B, WHITE_A\n\t\telse\n\t\t\tcaret.r, caret.g, caret.b, caret.a =\n\t\t\t\tfield.fgR / 255, field.fgG / 255, field.fgB / 255, field.fgA / 255\n\t\tend\n\tend\n\n\t-- The shadow first, so the box is drawn over it. It is the box itself, moved and drawn with\n\t-- its edge spread out: the quad it is drawn as is the box grown by that spreading, and the\n\t-- cut the shader makes is of the box, so what shows is the box's own shape going soft.\n\tif node.visible ~= 0 and node.shadowA > 0 then\n\t\tlocal blur = node.shadowBlur\n\t\tlocal band = blur > 0 and (1 / (2 * blur)) or 1\n\n\t\tclippedQuad(batch, clip, windowWidth, windowHeight, x + node.shadowX, y + node.shadowY,\n\t\t\tx + node.shadowX + node.width, y + node.shadowY + node.height, convertZ(z),\n\t\t\tnode.shadowR / 255, node.shadowG / 255, node.shadowB / 255, node.shadowA / 255,\n\t\t\t0, 0, 0, 1, 1, node.radius, band, blur + 1)\n\tend\n\n\tif node.visible ~= 0 and node.paint ~= 0 then\n\t\tlocal r, g, b, a = node.bgR, node.bgG, node.bgB, node.bgA\n\n\t\tif node.texture ~= 0 and r == 0 and g == 0 and b == 0 then\n\t\t\tr, g, b, a = WHITE_R, WHITE_G, WHITE_B, WHITE_A\n\t\tend\n\n\t\tclippedQuad(batch, clip, windowWidth, windowHeight, x, y, x + node.width, y + node.height,\n\t\t\tconvertZ(z), r, g, b, a, node.texture, node.u0, node.v0, node.u1, node.v1, node.radius)\n\tend\n\n\t-- What the element draws itself goes where its own text goes: over what is under it -- the\n\t-- background is drawn already -- and under its children, which are drawn after.\n\tif node.visible ~= 0 and here ~= nil and here.oncanvas ~= 0 then\n\t\tlocal draw = callbacks[here.oncanvas]\n\n\t\tif draw ~= nil then\n\t\t\t-- The room the padding and the border leave, which is the room a child of this element\n\t\t\t-- would get, and the depth everything of this element is drawn at.\n\t\t\tlocal left = x + node.paddingLeft\n\t\t\tlocal top = y + node.paddingTop\n\t\t\tlocal roomWidth = node.width - node.paddingLeft - node.paddingRight\n\t\t\t\t- node.borderLeft - node.borderRight\n\t\t\tlocal roomHeight = node.height - node.paddingTop - node.paddingBottom\n\t\t\t\t- node.borderTop - node.borderBottom\n\n\t\t\tdraw(canvas:draw(batch, clip, windowWidth, windowHeight, left, top, roomWidth, roomHeight,\n\t\t\t\tconvertZ(z), WHITE_TEXTURE))\n\t\tend\n\tend\n\n\tif node.visible ~= 0 and node.run ~= 0 then\n\t\tlocal value, from, to = nil, nil, nil\n\n\t\t-- A selection is drawn behind the text it covers, at the same depth: the batch is drawn in the\n\t\t-- order it was written, and what is written after is what shows. The node it is drawn on is\n\t\t-- the node the caret is placed from -- the first one inside the field, which is where the\n\t\t-- value is drawn -- so the highlight, the caret and the text are all about the same line.\n\t\tif caret ~= nil and inside and element ~= nil and not caret.covered then\n\t\t\tcaret.covered = true\n\t\t\tselectionQuads(batch, clip, caret, element, node, x, y, z, fontManager, windowWidth, windowHeight)\n\t\t\tvalue, from, to = strings[caret.value], caret.from, caret.to\n\t\tend\n\n\t\tgenerateTextQuads(batch, clip, assert(screen.runs[node.run]), node, x, y, z, fontManager, windowWidth,\n\t\t\twindowHeight, value, from, to)\n\tend\n\n\t-- Borders come after the box they are on, so they land on top of it.\n\tif node.visible ~= 0 then\n\t\tlocal r, g, b, a = node.borderR, node.borderG, node.borderB, node.borderA\n\t\tlocal width, height = node.width, node.height\n\n\t\tif node.borderTop > 0 then\n\t\t\taddBorderQuad(batch, clip, x, y, width, node.borderTop, r, g, b, a, z, windowWidth, windowHeight)\n\t\tend\n\n\t\tif node.borderBottom > 0 then\n\t\t\taddBorderQuad(batch, clip, x, y + height - node.borderBottom, width, node.borderBottom, r, g, b, a, z,\n\t\t\t\twindowWidth, windowHeight)\n\t\tend\n\n\t\tif node.borderLeft > 0 then\n\t\t\taddBorderQuad(batch, clip, x, y, node.borderLeft, height, r, g, b, a, z, windowWidth, windowHeight)\n\t\tend\n\n\t\tif node.borderRight > 0 then\n\t\t\taddBorderQuad(batch, clip, x + width - node.borderRight, y, node.borderRight, height, r, g, b, a, z,\n\t\t\t\twindowWidth, windowHeight)\n\t\tend\n\tend\n\n\t-- What a box that scrolls shows of its children is what is inside it: the clip is narrowed to\n\t-- it, and stays narrowed for everything below.\n\tlocal below = clip\n\n\tif node.scrolls ~= 0 then\n\t\tbelow = {\n\t\t\tleft = math.max(clip.left, x),\n\t\t\ttop = math.max(clip.top, y),\n\t\t\tright = math.min(clip.right, x + node.width),\n\t\t\tbottom = math.min(clip.bottom, y + node.height),\n\t\t}\n\tend\n\n\t-- The caret is placed from the line of text a field draws, which is the first one inside it --\n\t-- what a caret is beside is the text, and where the app put the text is where it goes. A field\n\t-- that draws none is placed from its own content origin, which is the fallback below.\n\tif caret ~= nil and inside and node.run ~= 0 and node.visible ~= 0 and not caret.placed then\n\t\tplaceCaret(caret, assert(element), node, x, y, z, below, fontManager)\n\tend\n\n\tfor at = 0, node.childCount - 1 do\n\t\tgenerateNodeQuads(batch, screen, below, screen.childIndices[node.firstChild + at - 1], x, y, windowWidth,\n\t\t\twindowHeight, z, fontManager, caret, inside, canvas)\n\tend\n\n\tif caret ~= nil and element ~= nil and element == caret.element and node.visible ~= 0 and not caret.placed then\n\t\tplaceCaret(caret, element, node, x + node.paddingLeft, y + node.paddingTop, z, below, fontManager)\n\tend\n\n\t-- A scroll bar is drawn over the strip it reserved, once the content is down: the track is the\n\t-- colour it was given made fainter, and the thumb is as much of the track as the box shows of\n\t-- the content. It is only there when there is something to scroll, which is what \"shows up\"\n\t-- means -- a list that fits has no bar.\n\tlocal bar = node.scrolls ~= 0 and screen.bars[index - 1]\n\n\tif node.visible ~= 0 and bar and bar.width > 0 and bar.max > 0 then\n\t\tlocal left = x + node.width - bar.width\n\t\tlocal thumb = node.height * (node.height / (node.height + bar.max))\n\n\t\tif thumb < bar.least then\n\t\t\tthumb = bar.least\n\t\tend\n\n\t\tif thumb > node.height then\n\t\t\tthumb = node.height\n\t\tend\n\n\t\t-- Where the thumb may travel is what is left of the box once the thumb is in it, so the\n\t\t-- end of the list puts the thumb's end at the end of the box rather than past it.\n\t\tlocal span = node.height - thumb\n\t\tlocal at = math.min(math.max(node.scroll / bar.max, 0), 1)\n\t\tlocal top = y + (span > 0 and at * span or 0)\n\n\t\t-- Drawn inside its own pane rather than the clip it is under, so a bar cannot come out of\n\t\t-- the box it belongs to and over whatever is beside it.\n\t\tclippedQuad(batch, below, windowWidth, windowHeight, left, y, left + bar.width, y + node.height,\n\t\t\tconvertZ(z), bar.r, bar.g, bar.b, bar.a * 0.25, 0, 0, 0, 1, 1)\n\t\tclippedQuad(batch, below, windowWidth, windowHeight, left, top, left + bar.width, top + thumb,\n\t\t\tconvertZ(z + 1), bar.r, bar.g, bar.b, bar.a, 0, 0, 0, 1, 1)\n\tend\nend\n\n\n--- A frame is asked for, at most one for each frame the display has time to show. What the\n--- question is asked about is a window, so what says when the last frame went out is kept with it.\n--- A frame asked for before that time is not lost: what the screen says goes into the frame that\n--- is still to come, and the event after this one asks again.\n---@param window wonderland.RenderWindow\n---@param forced boolean? # Whether the frame is the window's own, which is not held back\nfunction UI:requestRedraw(window, forced)\n\tlocal ctx = self.layoutPlugin.contexts[window]\n\tlocal at = now()\n\n\tif ctx then\n\t\t-- Whether the screen is what asked for the frame: a frame asked for by the screen is one\n\t\t-- that may not be worth drawing, and one asked for by the window is not.\n\t\tctx.asked = true\n\n\t\t-- What the events left is owed a screen, whether this frame is the one it is drawn in or\n\t\t-- one the display asks for later: a frame that is built without it is a frame of the screen\n\t\t-- before the events.\n\t\tctx.owed = true\n\n\t\t-- A frame the window manager asked for is the display's own time: one that was held back\n\t\t-- for coming too soon is the one that goes out then, so what a window shows is the state\n\t\t-- its events left rather than the state they left a frame ago.\n\t\tif not forced and not window.frameAsked and at - (ctx.framedAt or 0) < self.frameInterval then\n\t\t\treturn\n\t\tend\n\n\t\tctx.framedAt = at\n\tend\n\n\twindow.shouldRedraw = true -- shh. I'll figure out a way to make this use the eventhandler later.\nend\n\n--- A window that changed size is another solve of the same screen, because the screen is laid\n--- out against the window; one the pointer moved in may be drawn differently where the pointer\n--- is. Both are another repaint, and a repaint that comes out the same as the last one costs a\n--- solve and no more, so this does not have to be clever about which of them changed anything.\n---\n--- The screen is not built here, though: what these events change is what the *frame* is built\n--- from, and a frame is built once however many events asked for it. A pointer dragged across a\n--- window is hundreds of events a second and a frame each is sixty, so a screen built per event is\n--- a window that falls further behind the pointer the faster it is dragged -- and, once the events\n--- arrive faster than a screen is built, one that never draws at all.\n---\n--- The layout is asked before this is, because the plugins are asked in the order they were\n--- added, and it is the layout that says where the pointer is.\n---@param event winit.Event\n---@param _handler winit.EventManager\nfunction UI:event(event, _handler)\n\tlocal name = event.name\n\n\tif name == \"redraw\" then\n\t\treturn self:frame(event.window)\n\tend\n\n\tif name == \"resize\" or name == \"mouseMove\" or name == \"mousePress\"\n\t\tor name == \"mouseRelease\" or name == \"focusOut\" then\n\t\t-- A resize is the window rather than what the screen says, and how often it happens is\n\t\t-- the window manager's -- a size a frame is shown at, at worst -- so it is not rationed\n\t\t-- by the frame's time: a resize held back for coming too soon is a window left at the\n\t\t-- size it had, which is a window that looks frozen for as long as nothing else happens.\n\t\tself:requestRedraw(event.window, name == \"resize\")\n\tend\nend\n\n--- What a frame is remembered by: the field the caret is in, where it is, and what is selected\n--- there. A caret that moved is a frame to build again and one that only blinked is not -- and a\n--- selection that grew without the caret moving, which is what shift and an arrow key does at the\n--- end of a line, is a frame of its own as well.\n---@param ctx wonderland.plugin.Layout.Context\n---@param window wonderland.RenderWindow\n---@param layoutPlugin wonderland.plugin.Layout\n---@return string?\nlocal function caretKey(ctx, window, layoutPlugin)\n\tlocal element, line, column, from, to = layoutPlugin:getCaret(window)\n\n\tif element == nil then\n\t\treturn nil\n\tend\n\n\treturn table.concat({ tostring(ctx.focusedName), line, column, from or \"\", to or \"\" }, \":\")\nend\n\n--- The caret as this frame has it: which field it is for, where in it, and what is selected in it,\n--- or nothing where no field has the keyboard. What is typed into the field is kept by handle, since\n--- measuring it is what the caret's own place and the highlight are worked out from.\n---@param window wonderland.RenderWindow\n---@return wonderland.plugin.UI.Caret?\nfunction UI:caretFor(window)\n\tlocal element, line, column, from, to = self.layoutPlugin:getCaret(window)\n\n\tif element == nil then\n\t\treturn nil\n\tend\n\n\treturn {\n\t\telement = element,\n\t\tvalue = element.inputValue,\n\t\tline = line,\n\t\tcolumn = column,\n\t\tfrom = from,\n\t\tto = to,\n\t}\nend\n\n--- A click in a field, put where the caret goes: the point that was clicked, against the text the\n--- field draws -- the run of it, and where the walk put it -- as the line and the column the layout\n--- is told to put the caret at. It is against the frame that was on screen when the pointer went\n--- down, which is the one the pointer was over.\n---\n--- A field that draws no text of its own is left where the click put it, which is the end of what\n--- it holds: where in a field a click is is a question about the text in it, and a field with none\n--- has no answer to it.\n---@param window wonderland.RenderWindow\nfunction UI:caretClick(window)\n\tlocal ctx = self.layoutPlugin.contexts[window]\n\tlocal click = ctx and ctx.caretClick\n\n\tif click == nil or ctx == nil or ctx.focusedName == nil or ctx.ui == nil or ctx.screen == nil then\n\t\treturn\n\tend\n\n\t-- Taken whatever comes of it: a click that cannot be placed is a click that is done with, and\n\t-- one left behind would be put against a frame built later than the one it landed in.\n\tctx.caretClick = nil\n\n\tlocal element = self.layoutPlugin:getCaret(window)\n\n\tif element == nil then\n\t\treturn\n\tend\n\n\tlocal node, x, y, run = findFieldText(assert(ctx.screen), assert(ctx.root), 0, 0, element)\n\n\tif node == nil or x == nil or y == nil or run == nil then\n\t\treturn\n\tend\n\n\tlocal line, column = caretAtPoint(run, node, x, y, click.x, click.y)\n\tlocal anchorLine, anchorColumn = nil, nil\n\tlocal started = ctx.selectFrom\n\n\tif started ~= nil then\n\t\t-- The other end of the selection is where the press was, which is measured against the same\n\t\t-- frame the caret is: a drag is one selection made from where it started to where the pointer\n\t\t-- is now.\n\t\tanchorLine, anchorColumn = caretAtPoint(run, node, x, y, started.x, started.y)\n\n\t\t-- Kept while the pointer is held, so that a drag that is still going keeps the end it\n\t\t-- started from, and let go of once it is up: a click that is over is a click that is done\n\t\t-- with, as the point is.\n\t\tif ctx.pointer == nil or not ctx.pointer.pressed then\n\t\t\tctx.selectFrom = nil\n\t\tend\n\tend\n\n\tself.layoutPlugin:setCaret(window, line, column, anchorLine, anchorColumn)\nend\n\n--- The caret's clock: a caret is drawn for half a second and not for half a second, which is the\n--- one thing in a screen that changes on its own. What comes of it is one quad, so the frame it\n--- belongs to is not built again for it: see `UI:frame`.\n---@param ctx wonderland.plugin.Layout.Context\n---@return boolean blinked # Whether the caret came or went, which is a frame's worth of change\nfunction UI:blink(ctx)\n\tif ctx.focusedName == nil then\n\t\treturn false\n\tend\n\n\tif ctx.caretOn == nil then\n\t\t-- Nothing has blinked yet: a caret that comes with the typing starts by being shown.\n\t\tctx.caretOn, ctx.caretAt = true, now()\n\n\t\treturn false\n\tend\n\n\tif self.caretBlink <= 0 then\n\t\tctx.caretOn = true\n\n\t\treturn false\n\tend\n\n\tlocal at = now()\n\n\tif ctx.caretAt ~= nil and at - ctx.caretAt < self.caretBlink then\n\t\treturn false\n\tend\n\n\tctx.caretAt = at\n\tctx.caretOn = not ctx.caretOn\n\n\treturn true\nend\n\n--- What a screen has to do on its own, and when it next does it: a caret that blinks, a key held\n--- down in a field, and a gif moving on to its next frame. None of them is a whole screen -- a blink\n--- is one quad of the frame the gpu has, and a repeat is one character -- and all of them are what a\n--- loop with no timer in it has to be woken for.\n---\n--- This is what the loop is asked for the time of: it waits for the next event, of which an idle\n--- window has none, so a screen with something to do is one that has to say when it wants waking.\n--- The frame the end of that wait asks for is the caret coming or going or the key repeating, since\n--- whether either is due is the same clock this reads.\n---\n--- What a repeated key came to is handed back, because the value it edited is the app's: what an edit\n--- is told is the app rather than the screen, and where an event's message goes is the app -- so a\n--- repeat is a message from somewhere other than an event. See `app.run`, which passes it on.\n---\n--- A key held down is repeated here rather than by the keyboard, at the rate the layout was given\n--- rather than at the keyboard's: what a keyboard repeats of a held key is the same key, and taking\n--- its repeats as well would be the two rates added together -- a hold that takes two characters at\n--- some moments and one at others. Which presses are the keyboard's own is not something that can be\n--- worked out from what arrives, so it is not worked out: it is said, by the keyboard in winit,\n--- which marks the press of a repeat -- see `Layout:event`.\n---@param window wonderland.RenderWindow\n---@param handler winit.EventManager\n---@return any? message # What a key that was due to repeat came to, if one was due\nfunction UI:tick(window, handler)\n\tlocal ctx = self.layoutPlugin.contexts[window]\n\n\tif not ctx then\n\t\treturn\n\tend\n\n\tlocal layout = self.layoutPlugin\n\tlocal at = now()\n\tlocal due = nil ---@type number?\n\tlocal message = nil\n\n\tif ctx.repeatKey ~= nil and layout.keyRepeatInterval > 0 then\n\t\tif ctx.repeatAt == nil then\n\t\t\t-- A key that has just gone down, which is what having no next repeat yet means: what comes\n\t\t\t-- first is the wait before it repeats at all.\n\t\t\tctx.repeatAt = at + layout.keyRepeatDelay\n\t\tend\n\n\t\tif at >= ctx.repeatAt then\n\t\t\tmessage = layout:key(window, ctx.repeatKey, ctx.repeatMods, ctx.repeatTyped or ctx.repeatKey)\n\t\t\tctx.repeatAt = at + layout.keyRepeatInterval\n\n\t\t\t-- A frame of its own, for the same reason a blink is one: a repeat held back for coming\n\t\t\t-- too soon would leave the last of what a held key did on screen until the next event,\n\t\t\t-- which is the key coming up -- a character left behind.\n\t\t\t--\n\t\t\t-- Only where a repeat was a change, though: a key held at the end of what it can do --\n\t\t\t-- backspace in a field with nothing in front of the caret -- is a repeat that came to\n\t\t\t-- nothing, and a frame of the whole screen for nothing is the cost of a hold paid at the\n\t\t\t-- rate of a hold rather than the rate of what it does.\n\t\t\tif message ~= nil then\n\t\t\t\tself:requestRedraw(window, true)\n\t\t\tend\n\t\tend\n\n\t\tdue = ctx.repeatAt\n\tend\n\n\t-- The caret, which is the other thing a screen does with no event behind it. What has the\n\t-- keyboard is not always a caret: a thing the keyboard was tabbed to that answers a click is\n\t-- a keyboard with nothing blinking under it, and a frame every half second for a caret that\n\t-- is not there is a screen drawing itself for nothing.\n\tif self.caretBlink > 0 and self.layoutPlugin:getCaret(window) ~= nil then\n\t\tlocal blink = (ctx.caretAt or at) + self.caretBlink\n\n\t\tif at >= blink then\n\t\t\t-- What is due is a frame, and it is the caret's own clock that has kept it rather than the\n\t\t\t-- frame's: the frame's time is what holds a frame back, so it is not asked through it. The\n\t\t\t-- caret's coming or going is `UI:blink`, which the frame that comes of this runs.\n\t\t\tself:requestRedraw(window, true)\n\t\t\tblink = at + self.caretBlink\n\t\tend\n\n\t\tdue = due ~= nil and math.min(due, blink) or blink\n\tend\n\n\t-- A gif, which is the other thing a screen draws that changes with no event behind it. What\n\t-- frame of one is being shown is the clock's, and the frame is a texture and the part of a\n\t-- layer, which are what a style names: nothing short of a rebuild shows the next one. So a\n\t-- gif that moved on leaves the screen owed a frame, which the block below asks for at the\n\t-- display's own rate, and the time the one after it is due is what the loop is woken for.\n\tlocal shared = self.renderPlugin.sharedResources\n\tlocal assets = shared and shared.assets\n\n\tif assets ~= nil then\n\t\tif assets:advance(at) then\n\t\t\tctx.owed = true\n\t\tend\n\n\t\tlocal frames = assets:due()\n\n\t\tif frames ~= nil then\n\t\t\tdue = due ~= nil and math.min(due, frames) or frames\n\t\tend\n\tend\n\n\t-- What the app asked to be woken for, asked here because this is the one moment a loop with\n\t-- nothing in it has: it is what a player reads its position on, what a decoder takes the next\n\t-- frame out of a file on, and what a screen pacing itself to something other than the display\n\t-- -- a video, an audio clock -- is driven by. A callback that answered nothing is done with,\n\t-- and one that is done with is dropped here rather than kept to be asked again.\n\tlocal tickers = self.tickers\n\tlocal live = 0\n\n\tfor index = 1, #tickers do\n\t\tlocal ticker = tickers[index]\n\n\t\tif ticker.window == nil then\n\t\t\tticker.window = window\n\t\tend\n\n\t\tif not ticker.cancelled and ticker.window == window then\n\t\t\tif ticker.due == nil or at >= ticker.due then\n\t\t\t\tlocal wait = ticker.fn(at, window)\n\n\t\t\t\tif wait == nil then\n\t\t\t\t\tticker.cancelled = true\n\t\t\t\telse\n\t\t\t\t\tticker.due = at + math.max(wait, 0)\n\t\t\t\tend\n\t\t\tend\n\n\t\t\tif not ticker.cancelled then\n\t\t\t\tlive = live + 1\n\t\t\t\ttickers[live] = ticker\n\n\t\t\t\tlocal nextAt = assert(ticker.due)\n\n\t\t\t\tif nextAt <= at then\n\t\t\t\t\t-- A callback that wants to be asked again straight away is one that is racing\n\t\t\t\t\t-- the loop rather than the clock, and the loop is given no wait at all: it\n\t\t\t\t\t-- comes round as fast as it can, which is what decoding a burst of frames out\n\t\t\t\t\t-- of a file is.\n\t\t\t\t\tdue = due ~= nil and math.min(due, at) or at\n\t\t\t\telse\n\t\t\t\t\tdue = due ~= nil and math.min(due, nextAt) or nextAt\n\t\t\t\tend\n\t\t\tend\n\t\telseif not ticker.cancelled then\n\t\t\tlive = live + 1\n\t\t\ttickers[live] = ticker\n\t\tend\n\tend\n\n\tfor index = #tickers, live + 1, -1 do\n\t\ttickers[index] = nil\n\tend\n\n\t-- What the events left, drawn as soon as the display's time allows it. A frame that came too soon\n\t-- to go out is one the event after it would have asked for again -- and an event that never comes\n\t-- is a screen left showing what was typed before it, which is what a keystroke that landed on the\n\t-- heels of another frame would be. So the ask is made again here, where nothing has to arrive for\n\t-- the loop to be woken: the ration is the same one, so this is a frame at the rate of a frame and\n\t-- no faster.\n\tif ctx.owed then\n\t\tlocal ready = (ctx.framedAt or 0) + self.frameInterval\n\n\t\tif at >= ready then\n\t\t\tself:requestRedraw(window, true)\n\t\telse\n\t\t\tdue = due ~= nil and math.min(due, ready) or ready\n\t\tend\n\tend\n\n\tif due ~= nil then\n\t\thandler:setTimeout(due - at)\n\tend\n\n\treturn message\nend\n\n--- The quads of a frame, built from the screen the layout solved and handed to the gpu: the walk,\n--- and the caret of the field that has the keyboard added last so that a blink is the frame's last\n--- quad rather than a frame of its own.\n---\n--- The caret is what a frame's quads are remembered by as well as the screen: a caret that moved in\n--- a screen that did not is a frame the gpu has to be given again, and one that only blinked is\n--- the same frame with that last quad in or out -- which is what `UI:frame` tells apart.\n---@param window wonderland.RenderWindow\n---@param ctx wonderland.plugin.Layout.Context\n---@param key string? # The caret as this frame draws it, for the next one to tell it changed\nfunction UI:walk(window, ctx, key)\n\tlocal fontManager = assert(self.renderPlugin.sharedResources).fontManager\n\tlocal batch = self.batch\n\tlocal caret = self:caretFor(window)\n\n\t-- The size the frame is drawn into: the surface under the window rather than the size the\n\t-- window says it is, which is what the quads are written against and what the clip is. See\n\t-- `wonderland.plugin.Render:size`.\n\tlocal width, height = self.renderPlugin:size(window)\n\n\tbatch:reset()\n\tbatch:setViewport(width, height)\n\n\tgenerateNodeQuads(batch, assert(ctx.screen), { left = 0, top = 0, right = width,\n\t\tbottom = height }, assert(ctx.root), 0, 0, width, height, nil, fontManager, caret, nil, self.canvas)\n\n\t-- What the caret's quad is added to: the frame is the quads of the screen and then it, so a\n\t-- blink is this many of them and no more.\n\tctx.caret = caret and caret.placed and caret or nil\n\tctx.caretBase = batch.quads\n\n\t-- A caret that has not blinked yet is a caret that is drawn: nothing has said it should not be,\n\t-- and the first thing a field that takes the keyboard does is show where the typing goes.\n\tif ctx.caret ~= nil and ctx.caretOn ~= false then\n\t\taddCaretQuad(batch, ctx.caret, width, height)\n\tend\n\n\tself.renderPlugin:setRenderData(window, batch)\n\tctx.uploaded = true\n\tctx.frameKey = key\nend\n\n--- The caret coming or going: the last quad of the frame the gpu has is the caret's, so this is\n--- the frame without it or the frame with it again -- the quads are handed over and nothing is\n--- measured, solved or walked. It is the whole of what a blink costs.\n---@param window wonderland.RenderWindow\n---@param ctx wonderland.plugin.Layout.Context\nfunction UI:toggle(window, ctx)\n\tlocal caret = ctx.caret\n\n\tif caret == nil or ctx.caretBase == nil then\n\t\treturn\n\tend\n\n\tif ctx.caretOn then\n\t\tif self.batch.quads <= ctx.caretBase then\n\t\t\tlocal width, height = self.renderPlugin:size(window)\n\n\t\t\taddCaretQuad(self.batch, caret, width, height)\n\t\tend\n\telse\n\t\t-- Taken out with the runs it was in, which is what a frame is drawn from: what is left is\n\t\t-- the frame the gpu was given before the caret was put in.\n\t\tself.batch:truncate(ctx.caretBase)\n\tend\n\n\tself.renderPlugin:setRenderData(window, self.batch)\nend\n\n--- One frame of a window: the screen the state says, and the caret of the field that has the\n--- keyboard.\n---\n--- The screen is built when something is owed it -- what the events left, a window that changed\n--- size, a window that has never been drawn -- and not otherwise: a frame the display asked for\n--- with nothing behind it is a frame of what is already built, which is what keeps a window that\n--- is doing nothing from solving and drawing the whole of its ui at the rate of the display.\n---\n--- A frame the *screen* asked for that came out the same as the one already on screen is not drawn\n--- either: a pointer that moved across an element that does not change for it, a message that\n--- changed nothing the screen shows, and a window drawn again for a frame that is already there are\n--- frames that would show nothing new, and drawing one spends the display's time on it -- which is\n--- time the events behind it spend queued. A frame the *window* asked for is drawn whatever it\n--- comes out to, because what it is for is a window that lost what it was showing: an expose, a\n--- surface the gpu is not ready to draw into yet.\n---@param window wonderland.RenderWindow\nfunction UI:frame(window)\n\tlocal ctx = self.layoutPlugin.contexts[window]\n\n\tif not ctx then\n\t\treturn\n\tend\n\n\t-- Where a click in a field put the caret, before anything is built out of it: the point is\n\t-- against the frame that was on screen when the pointer went down, and the caret it comes to is\n\t-- one of the things this frame draws.\n\tself:caretClick(window)\n\n\t-- An ask is answered by the frame that comes out of it, which is where the window is told the\n\t-- frame is ready: see `X11Window:acknowledgeSync`, which is what puts the ask away.\n\tlocal asked = ctx.asked or window.frameAsked\n\n\tctx.asked = nil\n\n\t-- What the events left for the screen, which is the only reason to look at the view again.\n\tlocal owed = ctx.owed or not ctx.uploaded\n\n\tctx.owed = false\n\n\t-- What this frame draws into is taken before any of it is built: a screen laid out at the size\n\t-- of the last frame's target and drawn into this one's is a screen the compositor stretches,\n\t-- which during a resize is every frame of it.\n\tif (owed or not ctx.presented) and not self.renderPlugin:retarget(window) then\n\t\treturn\n\tend\n\n\tif owed then\n\t\tself.layoutPlugin:refreshView(window)\n\tend\n\n\t-- Where the caret is, which the frame's quads are remembered by as well as the screen: a caret\n\t-- that moved is a frame to build again, and one that only blinked is not.\n\tlocal key = caretKey(ctx, window, self.layoutPlugin)\n\n\tif key ~= ctx.frameKey then\n\t\t-- A caret that moved is drawn from the start of its blink, which is what an editor does\n\t\t-- while you type: one that happened to be out at the moment of the typing would be a caret\n\t\t-- that goes away exactly when it is looked at. The clock starts again *now* rather than\n\t\t-- being forgotten: a blink with no time to it is one that is due, and a caret that has just\n\t\t-- been moved would go out on the frame it was moved in.\n\t\tctx.caretOn, ctx.caretAt = true, now()\n\tend\n\n\tlocal blinked = self:blink(ctx)\n\tlocal built = false\n\n\tif owed then\n\t\t-- The screen that came out, the first frame of a window, and the caret that moved in a screen\n\t\t-- that did not: any of them is a frame the gpu does not have. A solve that came out the same,\n\t\t-- with a caret that stayed where it was, is not -- and that frame costs the view and no more.\n\t\tif assert(ctx.screen).changed or not ctx.uploaded or key ~= ctx.frameKey then\n\t\t\tbuilt = true\n\t\t\tself:walk(window, ctx, key)\n\t\tend\n\tend\n\n\t-- The caret coming or going is one quad of the frame the gpu already has -- which is a frame\n\t-- whether or not the screen was owed one, since the clock the caret blinks on is its own. A\n\t-- frame that was walked drew the caret as it is now, so there is nothing to put in or out.\n\tif blinked and not built then\n\t\tbuilt = true\n\t\tself:toggle(window, ctx)\n\tend\n\n\tif built or blinked or not asked or not ctx.presented then\n\t\tctx.presented = true\n\t\tctx.framedAt = now()\n\t\tself.renderPlugin:draw(assert(self.renderPlugin:getContext(window)))\n\tend\nend\n\n--- A repaint that is not a frame: a window being registered, or a screen drawn by hand. The screen\n--- is built and given to the gpu, and the frame it came out to is asked for, which is what a\n--- window loop draws.\n---@param window wonderland.RenderWindow\nfunction UI:refreshView(window)\n\t-- A click in a field is placed from the frame that was on screen when the pointer went down, so\n\t-- it is placed before this repaint builds the next one: see `UI:caretClick`.\n\tself:caretClick(window)\n\tself.layoutPlugin:refreshView(window)\n\n\tlocal ctx = self.layoutPlugin.contexts[window]\n\n\tif not ctx then\n\t\treturn\n\tend\n\n\tctx.owed = false\n\n\tlocal key = caretKey(ctx, window, self.layoutPlugin)\n\n\t-- A repaint that comes out the same, with a caret that stayed where it was, is a repaint that\n\t-- has nothing to upload and no frame to ask for: the gpu already has this one.\n\tif not (assert(ctx.screen).changed or not ctx.uploaded or key ~= ctx.frameKey) then\n\t\treturn\n\tend\n\n\tself:walk(window, ctx, key)\n\tself:requestRedraw(window)\nend\n\nreturn UI\n", "@wonderland.plugin.ui")(...) end
package.preload["hood-gl.queue"] = function(...) return load("local gl = require(\"glapi\")\nlocal GLCommandEncoder = require(\"hood-gl.command_encoder\")\n\n---@class hood-gl.Queue\n---@field private ctx hood-gl.Context # The headless GL context (resource ops, compute)\n---@field renderCtx hood-gl.Context?  # The window context; set by surface:configure\nlocal GLQueue = {}\nGLQueue.__index = GLQueue\n\n---@param ctx hood-gl.Context\nfunction GLQueue.new(ctx)\n\treturn setmetatable({ ctx = ctx }, GLQueue)\nend\n\n---@param buffer hood-gl.CommandBuffer\nfunction GLQueue:submit(buffer)\n\tself.ctx:makeCurrent()\n\tbuffer:execute(self.ctx, self.renderCtx)\nend\n\n---@param swapchain hood-gl.Swapchain\nfunction GLQueue:present(swapchain)\n\tself.ctx:makeCurrent()\n\tswapchain:present()\nend\n\nfunction GLQueue:waitIdle()\n\tself.ctx:makeCurrent()\n\tgl.finish()\nend\n\n--- Helper method to write data to a buffer\n---@param buffer hood-gl.Buffer\n---@param size number\n---@param data ffi.cdata*\n---@param offset number?\nfunction GLQueue:writeBuffer(buffer, size, data, offset)\n\tlocal cmd = GLCommandEncoder.new()\n\tcmd:writeBuffer(buffer, size, data, offset)\n\tself:submit(cmd:finish())\nend\n\n--- Helper method to write data to a texture\n---@param texture hood-gl.Texture\n---@param descriptor hood.TextureWriteDescriptor\n---@param data ffi.cdata*\nfunction GLQueue:writeTexture(texture, descriptor, data)\n\tlocal cmd = GLCommandEncoder.new()\n\tcmd:writeTexture(texture, descriptor, data)\n\tself:submit(cmd:finish())\nend\n\nreturn GLQueue\n", "@hood-gl.queue")(...) end
package.preload["wonderland.util.assets"] = function(...) return load("-- Pictures: what `image` decodes from a file, uploaded, and kept by path.\n--\n--   local logo = self.assets:image(\"logo.png\")\n--   div():style(sty():size(logo.width, logo.height):image(logo.texture, logo.uv))\n--\n-- The decoding is the `image` package's, which reads png, jpeg, gif and the rest of them, and what\n-- it decoded is handed to the texture manager, which is where a picture becomes something a style\n-- can name. A view function asks for the same picture on every repaint, so what a path came to is\n-- remembered and asking for it twice costs a lookup.\n--\n-- An animation is read a frame at a time rather than the whole of it at once:\n--\n--   local dance = self.assets:gif(\"dance.gif\")\n--   local frame = dance:current()\n--   div():style(sty():size(frame.width, frame.height):image(frame.texture, frame.uv))\n--\n-- A gif of eighty frames of a photograph is eighty frames of decoding and seventy megabytes, which\n-- read whole is a fifth of a second before anything is drawn and all of it held from then on. Read\n-- a frame at a time, the first frame is on screen in a few milliseconds, the rest are decoded and\n-- uploaded as the clock reaches them, and what a screen holds of a gif is the layers a few frames\n-- of it cycle through rather than every frame of it.\n--\n-- Which frame is current is the clock's, and the screen it is drawn on is asked for again when the\n-- next one is due. See `wonderland.plugin.UI:tick`, which owns that clock, and `Assets:advance`,\n-- which moves them on.\n--\n-- An animation whose frames come from somewhere other than a file -- a video being decoded, a\n-- camera, anything that hands over a picture -- is a stream the app writes into, and everything\n-- after the writing is the same: the same ring of layers, the same picture a style names, the same\n-- frame the screen is asked for again on.\n--\n--   local video = self.assets:stream({ width = 1920, height = 1080 })\n--\n--   self:every(1 / 60, function()          -- see `wonderland.Tick`\n--       local decoded = decodeTheNextFrame()\n--       if decoded then video:frame(decoded) end\n--   end)\n--\n--   local shown = video:current()\n--   div():style(sty():size(shown.width, shown.height):image(shown.texture, shown.uv))\nlocal image = require(\"image\")\nlocal time = require(\"wonderland.time\")\n\n--- One picture, uploaded: how big it is, and the texture a style draws it with.\n---@class wonderland.Asset\n---@field width number\n---@field height number\n---@field texture Texture # What a style is handed to draw it with\n---@field uv wonderland.UV # And the part of it to draw, which is the whole of a picture\n\n--- A frame of an animation, which is a picture shown for a while.\n---@class wonderland.Frame: wonderland.Asset\n---@field delay number # How long it is shown for, in seconds, as every time here is\n\n-- The least time a frame is shown for, in seconds. A file that names no delay, or one that names a\n-- millisecond, would otherwise be a screen rebuilt as fast as the loop can go.\nlocal MIN_DELAY = 0.02\n\n-- How many frames of an animation are read ahead of being drawn: the layers the frames are read\n-- into and cycle through. One would do for an animation drawn as it is played, and the ones past\n-- that are room for a screen that draws another frame of its own -- the one before this, a strip\n-- of what is coming -- without the layer under it being written over.\nlocal RING = 4\n\n-- What a picture that is the whole of its texture is sampled with. One table, because nothing\n-- reads it but a style, which copies the numbers out of it.\nlocal FULL = { u0 = 0, v0 = 0, u1 = 1, v1 = 1 }\n\n--- Where the frames of a stream come from, where it is not the app: something with a frame to\n--- hand over and, if it loops, a way back to the first one. What `image` opens a file as is this.\n---@class wonderland.FrameSource\n---@field next fun(source: any): image.Image?\n---@field rewind fun(source: any)?\n\n--- A stream of frames, drawn as the clock reaches them, and which of them is being shown.\n---\n--- What it holds is what has been shown so far: how many frames a source has, and so how long the\n--- whole of it runs for, is not known until it has been played through once.\n---@class wonderland.Stream\n---@field width number\n---@field height number\n---@field index number # Which frame is being shown, from one\n---@field at number? # When that frame started being shown, on the ui's clock\n---@field delay number # How long a frame is shown for where it does not say for itself\n---@field single boolean # Whether there turned out to be one frame, which never moves on\n---@field shown wonderland.Frame? # The one being drawn, which is what `current` answers with\n---@field private source wonderland.FrameSource? # Where the frames come from, for one read as it plays\n---@field private textureManager TextureManager\n---@field private texture number # The texture of layers the frames are written into\n---@field private layers number\n---@field private slots wonderland.Frame[] # What a frame is drawn by, made as they come\n---@field private count number # How many frames have been shown since the source last started over\n---@field private ringed boolean # Whether the frames come from the app rather than from a source\nlocal Stream = {}\nStream.__index = Stream\n\n---@param textureManager TextureManager\n---@param opts { width: number, height: number, layers: number?, delay: number?, source: wonderland.FrameSource? }\n---@return wonderland.Stream\nfunction Stream.new(textureManager, opts)\n\tlocal layers = opts.layers or RING\n\n\t---@type wonderland.Stream\n\treturn setmetatable({\n\t\twidth = opts.width,\n\t\theight = opts.height,\n\t\ttextureManager = textureManager,\n\t\ttexture = textureManager:uploadLayers(opts.width, opts.height, layers),\n\t\tlayers = layers,\n\t\tsource = opts.source,\n\t\tringed = opts.source == nil,\n\t\tdelay = opts.delay or MIN_DELAY,\n\t\tsingle = false,\n\t\tslots = {},\n\t\tcount = 0,\n\t\tindex = 1,\n\t}, Stream)\nend\n\n--- The frame that is being shown: how big it is, the picture it is drawn with, and how long it is\n--- shown for. Nothing at all until the first frame of a stream the app writes into has been given.\n---@return wonderland.Frame?\nfunction Stream:current()\n\treturn self.shown\nend\n\n--- When the frame being shown is due to change, on the clock the ui keeps.\n---@return number\nfunction Stream:due()\n\treturn (self.at or 0) + (self.shown and self.shown.delay or self.delay)\nend\n\n--- Where a frame of the file is drawn from: the layer of the ring its turn came to, named by a\n--- slot of its own.\n---\n--- A slot per frame index rather than per layer is what says a screen changed when the animation\n--- moves on: two frames of a gif are drawn out of the same texture, and it is the id a quad names\n--- that tells them apart.\n---@param index number\n---@return wonderland.Frame\nfunction Stream:frameAt(index)\n\tlocal known = self.slots[index]\n\n\tif known == nil then\n\t\tknown = {\n\t\t\twidth = self.width,\n\t\t\theight = self.height,\n\t\t\ttexture = self.textureManager:createSlot(self.width, self.height, self.texture,\n\t\t\t\t(index - 1) % self.layers),\n\t\t\tuv = FULL,\n\t\t\tdelay = 0,\n\t\t}\n\n\t\tself.slots[index] = known\n\tend\n\n\treturn known\nend\n\n--- Puts a frame where it is drawn from: the layer whose turn it is, named by a slot of its own,\n--- with the time it is shown for.\n---\n--- What a frame is written into is a layer of the ring rather than a picture of its own, so the\n--- frame being drawn by the gpu is not the one being written over -- which is what makes a stream\n--- of frames cost a copy each and no waiting for the display at all.\n---@param frame image.Image\n---@param delay number? # How long it is shown for, in seconds, where it does not say for itself\n---@return wonderland.Frame\nfunction Stream:put(frame, delay)\n\tself.count = self.count + 1\n\n\t-- A stream the app writes into names its slots by the ring, so that a video of any length\n\t-- costs the layers it cycles through; one read from a file names them by the frame, because\n\t-- what frame of it is being shown is what it comes back to.\n\tlocal index = self.ringed and ((self.count - 1) % self.layers) + 1 or self.count\n\tlocal shown = self:frameAt(index)\n\n\tself.textureManager:writeLayer(shown.texture, frame)\n\n\t-- A gif says how long a frame is shown for in milliseconds and the clock here counts seconds.\n\tshown.delay = delay or (frame.delay ~= nil and math.max(frame.delay / 1000, MIN_DELAY) or nil)\n\t\tor self.delay\n\n\treturn shown\nend\n\n--- A frame the app decoded, shown now: what a video being played is, where the frames come from\n--- something other than a file. What it does is put the frame in the ring and make it the one the\n--- screen draws -- and the screen is asked for again by whoever drew it, since the clock a decoder\n--- keeps is its own: see `wonderland.Tick`.\n---@param frame image.Image\n---@param delay number? # How long it is shown for, in seconds\n---@return wonderland.Frame\nfunction Stream:frame(frame, delay)\n\tlocal shown = self:put(frame, delay)\n\tlocal now = time.now()\n\n\tself.index = self.count\n\tself.shown = shown\n\tself.at = now\n\n\treturn shown\nend\n\n--- Reads the frame after the ones already read, which is the frame the animation is at. What is\n--- after the last frame of an animation is its first frame again; a file of a single frame has\n--- nothing after it at all, which is nothing here.\n---@return wonderland.Frame? frame\nfunction Stream:read()\n\tlocal frame = assert(self.source):next()\n\n\tif frame == nil then\n\t\t-- The end of the file. A file of one frame is that frame forever; anything else runs again\n\t\t-- from the top, which is what a gif that says nothing about it does.\n\t\tif self.count < 2 then\n\t\t\tself.single = true\n\n\t\t\treturn nil\n\t\tend\n\n\t\tassert(self.source).rewind(self.source)\n\t\tself.count = 0\n\t\tframe = self.source:next()\n\n\t\tif frame == nil then\n\t\t\treturn nil\n\t\tend\n\tend\n\n\treturn self:put(frame)\nend\n\n--- Moves on to the next frame when this one has been shown for as long as it said, and answers\n--- whether it did. A file of one frame stays on it, so nothing is asked for again.\n---\n--- What it is compared against is the time the frame is due rather than the delay worked out\n--- again: a clock is a double, and the difference between two times a tenth of a second apart is\n--- not always that tenth -- which is a frame that comes or goes a hair early.\n---@param now number # Seconds, on the clock the ui keeps\n---@return boolean # Whether the frame a screen draws changed\nfunction Stream:advance(now)\n\t-- A stream the app writes into is the app's own clock: nothing here moves it on, and what comes\n\t-- of a frame it gave is the frame it is drawing.\n\tif self.source == nil then\n\t\treturn false\n\tend\n\n\t-- A file the clock has not looked at yet starts its time now rather than at nought, which on a\n\t-- clock counting from some fixed point is a very long time ago: its first frame would go by\n\t-- before it was ever drawn.\n\tif self.at == nil then\n\t\tself.at = now\n\n\t\treturn false\n\tend\n\n\tif now < self:due() then\n\t\treturn false\n\tend\n\n\tif self.single then\n\t\treturn false\n\tend\n\n\tlocal frame = self:read()\n\n\tif frame == nil then\n\t\treturn false\n\tend\n\n\t-- The frame read is the frame the animation is at, counted from the start of the file: a frame\n\t-- the animation has come back around to is the first one again.\n\tself.index = self.count\n\tself.shown = frame\n\tself.at = now\n\n\treturn true\nend\n\n---@class wonderland.Assets\n---@field textureManager TextureManager\n---@field images table<string, wonderland.Asset> # What each path came to\n---@field streams table<string, wonderland.Stream> # And what each animated file came to\n---@field playing wonderland.Stream[] # The ones being played, which the clock is asked about\nlocal Assets = {}\nAssets.__index = Assets\n\n---@param textureManager TextureManager\n---@return wonderland.Assets\nfunction Assets.new(textureManager)\n\treturn setmetatable({ textureManager = textureManager, images = {}, streams = {}, playing = {} }, Assets)\nend\n\n--- Frames that come from somewhere other than a file: a video being decoded, a camera, anything\n--- that hands over a picture a frame at a time.\n---\n---   local video = assets:stream({ width = 1920, height = 1080 })\n---   video:frame(decoded)     -- when the decoder has one, and the app asks for a frame\n---\n--- A stream with a source reads it as the clock reaches each frame, which is what a file is: what\n--- it comes to is the same stream, drawn and moved on the same way.\n---@param opts { width: number?, height: number?, layers: number?, delay: number?, source: wonderland.FrameSource? }\n---@return wonderland.Stream\nfunction Assets:stream(opts)\n\tlocal source = opts.source\n\tlocal first = nil\n\n\tif source ~= nil then\n\t\t-- The first frame of a source is read here, and it is the frame the stream starts on as\n\t\t-- well as the answer to how large its frames are: reading one to measure it and another\n\t\t-- to draw would start an animation on its second frame.\n\t\tfirst = assert(source.next(source), \"The stream holds no frames\")\n\tend\n\n\tlocal width = opts.width or (first and first.width)\n\tlocal height = opts.height or (first and first.height)\n\n\tassert(width and height, \"A stream with no source needs the size of its frames\")\n\n\t---@cast width number\n\t---@cast height number\n\tlocal stream = Stream.new(self.textureManager, {\n\t\twidth = width,\n\t\theight = height,\n\t\tlayers = opts.layers,\n\t\tdelay = opts.delay,\n\t\tsource = source,\n\t})\n\n\tif first ~= nil then\n\t\tstream.shown = stream:put(first)\n\n\t\t-- A source is played until the process ends: there is nothing here that pauses one,\n\t\t-- because what a screen shows is the app's to say, and it says it by not drawing it.\n\t\tself.playing[#self.playing + 1] = stream\n\tend\n\n\treturn stream\nend\n\n--- One picture, uploaded into a texture of its own. A picture the app drew itself goes through here\n--- as well, and is not remembered by anything: what a path came to is, and this is what it came to.\n---@param decoded image.Image\n---@return wonderland.Asset\nfunction Assets:upload(decoded)\n\t-- Widened here rather than by the texture, because what the gpu holds is four channels and a\n\t-- copy of a picture that already has four is a copy nothing needs.\n\tlocal source = decoded.channels ~= 4 and decoded:convert(4) or decoded\n\n\treturn {\n\t\twidth = source.width,\n\t\theight = source.height,\n\t\ttexture = self.textureManager:upload({\n\t\t\twidth = source.width,\n\t\t\theight = source.height,\n\t\t\tchannels = 4,\n\t\t\tpixels = source.pixels,\n\t\t}),\n\t\tuv = FULL,\n\t}\nend\n\n--- A still picture, decoded once and remembered by path. What the bytes are is what decides\n--- the format: the extension is only a hint for a file whose bytes say nothing.\n---@param path string\n---@return wonderland.Asset\nfunction Assets:image(path)\n\tlocal known = self.images[path]\n\n\tif known then\n\t\treturn known\n\tend\n\n\tlocal decoded, err = image.load(path)\n\tassert(decoded, err)\n\n\tlocal asset = self:upload(decoded)\n\n\t-- The texture has the pixels now: the buffer they were decoded into is let go of rather than\n\t-- kept for the life of the app.\n\tdecoded:close()\n\n\tself.images[path] = asset\n\n\treturn asset\nend\n\n--- An animated file, opened and read a frame at a time, remembered by path. What comes back is\n--- its first frame, ready to draw, and the rest are read as the clock reaches them.\n---\n--- A file with one picture in it is an animation of that one frame, which never moves on.\n---@param path string\n---@return wonderland.Stream\nfunction Assets:gif(path)\n\tlocal known = self.streams[path]\n\n\tif known then\n\t\treturn known\n\tend\n\n\tlocal file, err = image.stream(path)\n\tassert(file, err)\n\n\t---@cast file image.Stream\n\tlocal gif = self:stream({ source = file, delay = MIN_DELAY })\n\n\tself.streams[path] = gif\n\n\treturn gif\nend\n\n--- Moves every playing stream on to its next frame where that is due, and answers whether any of\n--- them is a screen the gpu does not have yet.\n---@param now number # Seconds, on the clock the ui keeps\n---@return boolean\nfunction Assets:advance(now)\n\tlocal changed = false\n\n\tfor _, stream in ipairs(self.playing) do\n\t\tif stream:advance(now) then\n\t\t\tchanged = true\n\t\tend\n\tend\n\n\treturn changed\nend\n\n--- When the next frame of a playing stream is due, which is when a loop that waits for its next\n--- event has to be woken: nothing, where none of them is playing.\n---@return number?\nfunction Assets:due()\n\tlocal due = nil\n\n\tfor _, stream in ipairs(self.playing) do\n\t\t-- A file of one frame never moves on, and one the clock has not started has nothing due\n\t\t-- yet: the tick that starts it is the one that asks it again.\n\t\tif not stream.single and stream.at ~= nil then\n\t\t\tlocal at = stream:due()\n\n\t\t\tif due == nil or at < due then\n\t\t\t\tdue = at\n\t\t\tend\n\t\tend\n\tend\n\n\treturn due\nend\n\nreturn Assets\n", "@wonderland.util.assets")(...) end
package.preload["hood-vk.command_encoder"] = function(...) return load("local ffi = require(\"ffi\")\n\nlocal vk = require(\"vkapi\")\nlocal vkConversions = require(\"hood-vk.convert\")\nlocal memory = require(\"hood-vk.memory\")\n\nlocal VKCommandBuffer = require(\"hood-vk.command_buffer\")\n\n--- Staging allocations start at this much memory and grow by doubling, so a\n--- frame that uploads a few small uniform blocks does not allocate per write.\nlocal STAGING_MIN_SIZE = 256 * 1024\n\n---@class hood-vk.CommandEncoder\n---@field buffer hood-vk.CommandBuffer\n---@field device hood-vk.Device\n---@field pendingDescriptor any\n---@field imageViews vk.ffi.ImageView[]\n---@field framebuffers vk.ffi.Framebuffer[]\n---@field pipeline hood-vk.Pipeline?\n---@field computePipeline hood-vk.ComputePipeline?\n---@field bindGroups table<number, hood-vk.BindGroup>\n---@field renderPasses vk.ffi.RenderPass[]\n---@field bufferCopy vk.ffi.BufferCopy[] scratch for vkCmdCopyBuffer regions\n---@field memoryBarrier vk.ffi.MemoryBarrier[] scratch for _flushStagedWrites\n---@field stagedWrites boolean true while a staged copy is waiting to be made visible\n---@field inRenderPass boolean true between beginRendering and endRendering\n---@field _swapchain hood-vk.Swapchain?\n---@field _reusableRpDesc table?\nlocal VKCommandEncoder = {}\nVKCommandEncoder.__index = VKCommandEncoder\n\nlocal beginInfo = vk.CommandBufferBeginInfo({})\n\n-- Pre-allocated working buffers for the common single-attachment case.\n-- These are reused across frames to avoid per-frame FFI allocation.\nlocal _reusableClearValues = vk.ClearValueArray(1)\nlocal _reusableBeginInfo = vk.RenderPassBeginInfo()\nlocal _reusableImageViews = ffi.new(\"VkImageView[1]\")\n\n-- Same idea for the two-attachment case (colour + depth), which is what a\n-- depth-tested 2D/3D pass uses.\nlocal _reusableClearValues2 = vk.ClearValueArray(2)\n\n---@param device hood-vk.Device\n---@param reuseBuffer hood-vk.CommandBuffer? If provided, the buffer is reset and reused instead of allocating a new one.\n---@return hood-vk.CommandEncoder\nfunction VKCommandEncoder.new(device, reuseBuffer)\n\tlocal buffer\n\tif reuseBuffer then\n\t\tbuffer = reuseBuffer\n\t\tbuffer:reset()\n\telse\n\t\tbuffer = VKCommandBuffer.new(device)\n\tend\n\tdevice.handle:beginCommandBuffer(buffer.handle, beginInfo)\n\n\t-- Reuse the encoder owned by this command buffer. Command buffers are\n\t-- pre-allocated per swapchain image, so the encoder and its tracking tables\n\t-- live as long as the swapchain instead of being allocated every frame.\n\tlocal encoder = buffer._encoder\n\tif encoder then\n\t\tencoder.pendingDescriptor = nil\n\t\tencoder.pipeline = nil\n\t\tencoder.inRenderPass = false\n\t\tencoder.computePipeline = nil\n\t\tencoder._swapchain = nil\n\t\tencoder.sampleableDepth = nil\n\t\tencoder.sampleableDepthLayers = nil\n\n\t\t-- Bind groups are only consulted by compute passes; drop stale entries\n\t\t-- so a later frame never sees groups from an earlier one. This costs\n\t\t-- nothing on the render-only path.\n\t\tif next(encoder.bindGroups) ~= nil then\n\t\t\tencoder.bindGroups = {}\n\t\tend\n\n\t\treturn encoder\n\tend\n\n\tencoder = setmetatable({\n\t\tdevice = device,\n\t\tbuffer = buffer,\n\t\timageViews = {},\n\t\tframebuffers = {},\n\t\trenderPasses = {},\n\t\tbindGroups = {},\n\t\tbufferCopy = vk.BufferCopyArray(1),\n\t\tmemoryBarrier = vk.MemoryBarrierArray(1),\n\t\tdepthBarrier = vk.ImageMemoryBarrierArray(1),\n\t\tinRenderPass = false,\n\t\tstagedWrites = false,\n\t\tsampleableDepth = nil,\n\t\tsampleableDepthLayers = nil,\n\t\t_swapchain = nil,\n\t}, VKCommandEncoder)\n\tbuffer._encoder = encoder\n\treturn encoder\nend\n\n--- Begin a render pass.\n--- Two calling conventions:\n---   1. Full descriptor table: encoder:beginRendering({ colorAttachments = {...} })\n---   2. Simple single-attachment: encoder:beginRendering(textureView, clearColor?)\n---       where textureView is a hood-vk.TextureView. The descriptor tables are\n---       allocated once and reused internally, avoiding per-frame table churn.\n---@overload fun(self, textureView: hood-vk.TextureView, clearColor?: { r: number, g: number, b: number, a: number })\n---@overload fun(self, descriptor: hood.RenderPassDescriptor)\nfunction VKCommandEncoder:beginRendering(descriptor, clearColor)\n\tif descriptor and descriptor.colorAttachments then\n\t\t-- Full descriptor table (backward compatible)\n\t\tself.pendingDescriptor = descriptor\n\telse\n\t\t-- Simple path: descriptor is a TextureView, clearColor is optional.\n\t\t-- Use a reusable descriptor stored on the encoder to avoid allocation.\n\t\tlocal d = self._reusableRpDesc\n\t\tif not d then\n\t\t\tlocal clear = { r = 0, g = 0, b = 0, a = 1 }\n\t\t\tlocal op = { type = \"clear\", color = clear }\n\t\t\td = {\n\t\t\t\tcolorAttachments = { {\n\t\t\t\t\top = op,\n\t\t\t\t\ttexture = nil,\n\t\t\t\t} },\n\t\t\t}\n\t\t\tself._reusableRpDesc = d\n\t\tend\n\t\td.colorAttachments[1].texture = descriptor\n\t\tif clearColor then\n\t\t\tlocal c = d.colorAttachments[1].op.color\n\t\t\tc.r = clearColor.r\n\t\t\tc.g = clearColor.g\n\t\t\tc.b = clearColor.b\n\t\t\tc.a = clearColor.a\n\t\tend\n\t\tself.pendingDescriptor = d\n\tend\nend\n\n---@param pipeline hood-vk.Pipeline\nfunction VKCommandEncoder:setPipeline(pipeline)\n\tif self.pendingDescriptor then\n\t\tself:_beginRenderPass(pipeline, self.pendingDescriptor)\n\t\tself.pendingDescriptor = nil\n\tend\n\n\tself.pipeline = pipeline\n\tself.device.handle:cmdBindPipeline(self.buffer.handle, vk.PipelineBindPoint.GRAPHICS, pipeline.handle)\nend\n\n---@param pipeline hood-vk.Pipeline\n---@param descriptor hood.RenderPassDescriptor\nfunction VKCommandEncoder:_beginRenderPass(pipeline, descriptor)\n\t-- Anything staged earlier has to be visible before the first draw reads it.\n\tself:_flushStagedWrites()\n\n\tlocal colorAttachments = descriptor.colorAttachments or {}\n\tlocal depthAttachment = descriptor.depthStencilAttachment\n\tlocal totalAttachments = #colorAttachments + (depthAttachment and 1 or 0)\n\n\tlocal width, height\n\tif colorAttachments[1] then\n\t\tlocal view = colorAttachments[1].texture --[[@as hood-vk.TextureView]]\n\t\twidth, height = view.texture.width, view.texture.height\n\telseif depthAttachment then\n\t\tlocal view = depthAttachment.texture --[[@as hood-vk.TextureView]]\n\t\twidth, height = view.texture.width, view.texture.height\n\tend\n\n\t-- Detect if the first color attachment is a swapchain texture, so we can\n\t-- use pre-created image views and cached framebuffers from the swapchain.\n\tlocal swapchainForFB = nil\n\tif colorAttachments[1] then\n\t\tlocal view = colorAttachments[1].texture --[[@as hood-vk.TextureView]]\n\t\tif view.texture and view.texture.isSwapchain and view.texture.swapchain then\n\t\t\tswapchainForFB = view.texture.swapchain\n\t\tend\n\tend\n\n\t-- Fast path: rendering into the swapchain with the render pass already\n\t-- cached. Everything below only exists to *create* the render pass and its\n\t-- framebuffer, so on a cache hit we skip all of it (no tables, no loops,\n\t-- no per-frame allocation) and go straight to vkCmdBeginRenderPass.\n\t--\n\t-- This covers any attachment count, including the colour + depth pass lupa\n\t-- uses; previously it was limited to a single colour attachment, which made\n\t-- every depth-attached frame rebuild two attachment tables and create and\n\t-- destroy a VkFramebuffer.\n\tif swapchainForFB and swapchainForFB._cachedRenderPass then\n\t\tself._swapchain = swapchainForFB\n\n\t\tlocal renderPass = swapchainForFB._cachedRenderPass\n\n\t\tlocal depthView = nil\n\t\tif depthAttachment then\n\t\t\tdepthView = depthAttachment.texture.handle\n\t\tend\n\t\tlocal framebuffer = swapchainForFB:getFramebuffer(renderPass, width, height, depthView)\n\n\t\tlocal clearValues\n\t\tif totalAttachments == 1 then\n\t\t\tclearValues = _reusableClearValues\n\t\telseif totalAttachments == 2 then\n\t\t\tclearValues = _reusableClearValues2\n\t\telse\n\t\t\tclearValues = vk.ClearValueArray(totalAttachments)\n\t\tend\n\n\t\tfor i = 1, #colorAttachments do\n\t\t\tlocal att = colorAttachments[i]\n\t\t\tif att.op.type == \"clear\" then\n\t\t\t\tlocal c = att.op.color\n\t\t\t\tlocal v = clearValues[i - 1].color.float32\n\t\t\t\tv[0] = c.r\n\t\t\t\tv[1] = c.g\n\t\t\t\tv[2] = c.b\n\t\t\t\tv[3] = c.a\n\t\t\tend\n\t\tend\n\n\t\tif depthAttachment and depthAttachment.op.type == \"clear\" then\n\t\t\tlocal ds = clearValues[totalAttachments - 1].depthStencil\n\t\t\tds.depth = depthAttachment.op.depth\n\t\t\tds.stencil = 0\n\t\tend\n\n\t\tlocal beginInfo = _reusableBeginInfo\n\t\tbeginInfo.renderPass = renderPass\n\t\tbeginInfo.framebuffer = framebuffer\n\t\tbeginInfo.renderArea.offset.x = 0\n\t\tbeginInfo.renderArea.offset.y = 0\n\t\tbeginInfo.renderArea.extent.width = width\n\t\tbeginInfo.renderArea.extent.height = height\n\t\tbeginInfo.clearValueCount = totalAttachments\n\t\tbeginInfo.pClearValues = clearValues\n\n\t\tself:_beginRenderPassRaw(beginInfo)\n\t\treturn\n\tend\n\n\tlocal imageViews\n\tif totalAttachments == 1 then\n\t\timageViews = _reusableImageViews\n\telse\n\t\timageViews = ffi.new(\"VkImageView[?]\", totalAttachments)\n\tend\n\tlocal attachmentDescs = {}\n\tlocal colorRefs = {}\n\n\t-- Color attachments — use numeric for loop for JIT-friendliness\n\tfor i = 1, #colorAttachments do\n\t\tlocal att = colorAttachments[i]\n\t\tlocal view = att.texture --[[@as hood-vk.TextureView]]\n\t\tlocal isSwapchain = view.texture and view.texture.isSwapchain\n\n\t\t-- Image views are owned by their textures and must outlive this command\n\t\t-- buffer, so they are never tracked here for cleanup.\n\t\tif isSwapchain and view.texture.swapchain then\n\t\t\tself._swapchain = view.texture.swapchain\n\t\tend\n\t\timageViews[i - 1] = view.handle\n\n\t\tattachmentDescs[#attachmentDescs + 1] = {\n\t\t\tformat = view.texture.format,\n\t\t\tsamples = vk.SampleCountFlagBits.COUNT_1,\n\t\t\tloadOp = att.op.type == \"clear\" and vk.AttachmentLoadOp.CLEAR or vk.AttachmentLoadOp.LOAD,\n\t\t\tstoreOp = vk.AttachmentStoreOp.STORE,\n\t\t\tstencilLoadOp = vk.AttachmentLoadOp.DONT_CARE,\n\t\t\tstencilStoreOp = vk.AttachmentStoreOp.DONT_CARE,\n\t\t\tinitialLayout = vk.ImageLayout.UNDEFINED,\n\t\t\tfinalLayout = isSwapchain and vk.ImageLayout.PRESENT_SRC_KHR or vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL,\n\t\t}\n\n\t\tcolorRefs[#colorRefs + 1] = {\n\t\t\tattachment = #attachmentDescs - 1,\n\t\t\tlayout = vk.ImageLayout.COLOR_ATTACHMENT_OPTIMAL\n\t\t}\n\tend\n\n\tlocal depthRef = nil\n\tif depthAttachment then\n\t\tlocal view = depthAttachment.texture --[[@as hood-vk.TextureView]]\n\t\timageViews[totalAttachments - 1] = view.handle\n\n\t\t-- A depth texture made with TEXTURE_BINDING is one that is going to be sampled,\n\t\t-- the way WebGPU and D3D12 both read usages, so the pass leaves it in the layout\n\t\t-- a shader reads rather than the one a pass ends in. A pass that loads therefore\n\t\t-- finds it in the read layout and says so, rather than calling it UNDEFINED and\n\t\t-- inviting the driver to discard what it is about to load.\n\t\tlocal sampled = view.texture.usage\n\t\t\tand bit.band(view.texture.usage, vk.ImageUsageFlagBits.SAMPLED) ~= 0\n\t\tlocal finalLayout = sampled\n\t\t\tand vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\n\t\t\tor vk.ImageLayout.DEPTH_STENCIL_ATTACHMENT_OPTIMAL\n\n\t\tlocal initialLayout = vk.ImageLayout.UNDEFINED\n\t\tif depthAttachment.op.type ~= \"clear\" and sampled then\n\t\t\tinitialLayout = vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\n\t\tend\n\n\t\tattachmentDescs[#attachmentDescs + 1] = {\n\t\t\tformat = view.texture.format,\n\t\t\tsamples = vk.SampleCountFlagBits.COUNT_1,\n\t\t\tloadOp = depthAttachment.op.type == \"clear\" and vk.AttachmentLoadOp.CLEAR or vk.AttachmentLoadOp.LOAD,\n\t\t\tstoreOp = vk.AttachmentStoreOp.STORE,\n\t\t\tstencilLoadOp = vk.AttachmentLoadOp.DONT_CARE,\n\t\t\tstencilStoreOp = vk.AttachmentStoreOp.DONT_CARE,\n\t\t\tinitialLayout = initialLayout,\n\t\t\tfinalLayout = finalLayout,\n\t\t}\n\n\t\tif sampled then\n\t\t\tself.sampleableDepth = view.texture\n\t\t\tself.sampleableDepthLayers = view.layerCount\n\t\tend\n\n\t\tdepthRef = {\n\t\t\tattachment = #attachmentDescs - 1,\n\t\t\tlayout = vk.ImageLayout.DEPTH_STENCIL_ATTACHMENT_OPTIMAL,\n\t\t}\n\tend\n\n\tlocal depthStageMask = 0\n\tlocal depthAccessMask = 0\n\tif depthAttachment then\n\t\tdepthStageMask = bit.bor(vk.PipelineStageFlagBits.EARLY_FRAGMENT_TESTS,\n\t\t\tvk.PipelineStageFlagBits.LATE_FRAGMENT_TESTS)\n\t\tdepthAccessMask = bit.bor(vk.AccessFlags.DEPTH_STENCIL_ATTACHMENT_READ,\n\t\t\tvk.AccessFlags.DEPTH_STENCIL_ATTACHMENT_WRITE)\n\tend\n\n\t-- Look up the render pass: for swapchain, store directly on the swapchain\n\t-- (avoids building a string key every frame). For non-swapchain, use the\n\t-- device-level cache with a string key.\n\tlocal renderPass\n\tif swapchainForFB then\n\t\trenderPass = swapchainForFB._cachedRenderPass\n\t\tif not renderPass then\n\t\t\trenderPass = self.device.handle:createRenderPass({\n\t\t\t\tattachments = attachmentDescs,\n\t\t\t\tsubpasses = {\n\t\t\t\t\t{\n\t\t\t\t\t\tpipelineBindPoint = vk.PipelineBindPoint.GRAPHICS,\n\t\t\t\t\t\tcolorAttachments = colorRefs,\n\t\t\t\t\t\tdepthStencilAttachment = depthRef,\n\t\t\t\t\t},\n\t\t\t\t},\n\t\t\t\tdependencies = {\n\t\t\t\t\t{\n\t\t\t\t\t\tsrcSubpass = vk.SUBPASS_EXTERNAL,\n\t\t\t\t\t\tdstSubpass = 0,\n\t\t\t\t\t\tsrcStageMask = bit.bor(vk.PipelineStageFlagBits.COLOR_ATTACHMENT_OUTPUT, depthStageMask),\n\t\t\t\t\t\tdstStageMask = bit.bor(vk.PipelineStageFlagBits.COLOR_ATTACHMENT_OUTPUT, depthStageMask),\n\t\t\t\t\t\tdstAccessMask = bit.bor(vk.AccessFlags.COLOR_ATTACHMENT_WRITE, depthAccessMask),\n\t\t\t\t\t},\n\t\t\t\t},\n\t\t\t})\n\t\t\tswapchainForFB._cachedRenderPass = renderPass\n\t\tend\n\telse\n\t\t-- Build a cache key from attachment properties for non-swapchain rendering\n\t\tlocal cacheKey = \"\"\n\t\tfor attIdx = 1, #attachmentDescs do\n\t\t\tlocal att = attachmentDescs[attIdx]\n\t\t\tcacheKey = cacheKey .. \",\" .. att.format .. \",\" .. att.loadOp .. \",\" .. att.finalLayout\n\t\tend\n\t\tcacheKey = cacheKey .. \",d=\" .. (depthAttachment and \"1\" or \"0\")\n\n\t\trenderPass = self.device._renderPassCache[cacheKey]\n\t\tif not renderPass then\n\t\t\trenderPass = self.device.handle:createRenderPass({\n\t\t\t\tattachments = attachmentDescs,\n\t\t\t\tsubpasses = {\n\t\t\t\t\t{\n\t\t\t\t\t\tpipelineBindPoint = vk.PipelineBindPoint.GRAPHICS,\n\t\t\t\t\t\tcolorAttachments = colorRefs,\n\t\t\t\t\t\tdepthStencilAttachment = depthRef,\n\t\t\t\t\t},\n\t\t\t\t},\n\t\t\t\tdependencies = {\n\t\t\t\t\t{\n\t\t\t\t\t\tsrcSubpass = vk.SUBPASS_EXTERNAL,\n\t\t\t\t\t\tdstSubpass = 0,\n\t\t\t\t\t\tsrcStageMask = bit.bor(vk.PipelineStageFlagBits.COLOR_ATTACHMENT_OUTPUT, depthStageMask),\n\t\t\t\t\t\tdstStageMask = bit.bor(vk.PipelineStageFlagBits.COLOR_ATTACHMENT_OUTPUT, depthStageMask),\n\t\t\t\t\t\tdstAccessMask = bit.bor(vk.AccessFlags.COLOR_ATTACHMENT_WRITE, depthAccessMask),\n\t\t\t\t\t},\n\t\t\t\t},\n\t\t\t})\n\t\t\tself.device._renderPassCache[cacheKey] = renderPass\n\t\tend\n\tend\n\n\t-- Use a cached framebuffer when rendering to a swapchain (the common case).\n\t-- Swapchain framebuffers are lazily created and cached per\n\t-- (renderPass, imageIdx, dimensions) -- and per depth view when one is\n\t-- attached, so a depth-attached pass is cached too rather than building and\n\t-- destroying a VkFramebuffer every frame.\n\t-- For non-swapchain rendering, create a transient framebuffer tracked per-frame.\n\tlocal framebuffer\n\tif swapchainForFB then\n\t\tlocal depthView = nil\n\t\tif depthAttachment then\n\t\t\tdepthView = depthAttachment.texture.handle\n\t\tend\n\t\tframebuffer = swapchainForFB:getFramebuffer(renderPass, width, height, depthView)\n\telse\n\t\tframebuffer = self.device.handle:createFramebuffer({\n\t\t\trenderPass = renderPass,\n\t\t\tattachmentCount = totalAttachments,\n\t\t\tpAttachments = imageViews,\n\t\t\twidth = width,\n\t\t\theight = height,\n\t\t\tlayers = 1,\n\t\t})\n\t\tself.framebuffers[#self.framebuffers + 1] = framebuffer\n\tend\n\n\tlocal clearValues\n\tif totalAttachments == 1 then\n\t\tclearValues = _reusableClearValues\n\telse\n\t\tclearValues = vk.ClearValueArray(totalAttachments)\n\tend\n\n\tfor i = 1, #colorAttachments do\n\t\tlocal att = colorAttachments[i]\n\t\tif att.op.type == \"clear\" then\n\t\t\tlocal c = att.op.color\n\t\t\tclearValues[i - 1].color.float32[0] = c.r\n\t\t\tclearValues[i - 1].color.float32[1] = c.g\n\t\t\tclearValues[i - 1].color.float32[2] = c.b\n\t\t\tclearValues[i - 1].color.float32[3] = c.a\n\t\tend\n\tend\n\n\tif depthAttachment and depthAttachment.op.type == \"clear\" then\n\t\tclearValues[totalAttachments - 1].depthStencil.depth = depthAttachment.op.depth\n\t\tclearValues[totalAttachments - 1].depthStencil.stencil = 0\n\tend\n\n\tlocal beginInfo = _reusableBeginInfo\n\tbeginInfo.renderPass = renderPass\n\tbeginInfo.framebuffer = framebuffer\n\tbeginInfo.renderArea.offset.x = 0\n\tbeginInfo.renderArea.offset.y = 0\n\tbeginInfo.renderArea.extent.width = width\n\tbeginInfo.renderArea.extent.height = height\n\tbeginInfo.clearValueCount = totalAttachments\n\tbeginInfo.pClearValues = clearValues\n\n\tself:_beginRenderPassRaw(beginInfo)\nend\n\ndo\n\tlocal viewport = vk.Viewport()\n\tlocal scissor = vk.Rect2D()\n\n\t---@param x number\n\t---@param y number\n\t---@param width number\n\t---@param height number\n\tfunction VKCommandEncoder:setViewport(x, y, width, height)\n\t\tviewport.x = x\n\t\tviewport.y = y + height\n\t\tviewport.width = width\n\t\tviewport.height = -height\n\t\tviewport.minDepth = 0\n\t\tviewport.maxDepth = 1\n\n\t\tscissor.offset.x = x\n\t\tscissor.offset.y = y\n\t\tscissor.extent.width = width\n\t\tscissor.extent.height = height\n\n\t\tself.device.handle:cmdSetViewport(self.buffer.handle, 0, 1, viewport)\n\t\tself.device.handle:cmdSetScissor(self.buffer.handle, 0, 1, scissor)\n\tend\nend\n\ndo\n\tlocal buffers = ffi.new(\"VkBuffer[1]\")\n\tlocal offsets = ffi.new(\"VkDeviceSize[1]\")\n\n\t---@param slot number\n\t---@param buffer hood-vk.Buffer\n\t---@param offset number?\n\tfunction VKCommandEncoder:setVertexBuffer(slot, buffer, offset)\n\t\tbuffers[0] = buffer.handle\n\t\toffsets[0] = offset or 0\n\t\tself.device.handle:cmdBindVertexBuffers(self.buffer.handle, slot, 1, buffers, offsets)\n\tend\nend\n\n---@param buffer hood-vk.Buffer\n---@param format hood.IndexFormat\n---@param offset number?\nfunction VKCommandEncoder:setIndexBuffer(buffer, format, offset)\n\tself.device.handle:cmdBindIndexBuffer(self.buffer.handle, buffer.handle, offset or 0,\n\t\tvkConversions.indexFormat[format])\nend\n\n---@param indexCount number\n---@param instanceCount number\n---@param firstIndex number?\n---@param baseVertex number?\n---@param firstInstance number?\nfunction VKCommandEncoder:drawIndexed(indexCount, instanceCount, firstIndex, baseVertex, firstInstance)\n\tself.device.handle:cmdDrawIndexed(self.buffer.handle, indexCount, instanceCount or 1, firstIndex or 0,\n\t\tbaseVertex or 0, firstInstance or 0)\nend\n\n---@param vertexCount number\n---@param instanceCount number\n---@param firstVertex number?\n---@param firstInstance number?\nfunction VKCommandEncoder:draw(vertexCount, instanceCount, firstVertex, firstInstance)\n\tself.device.handle:cmdDraw(self.buffer.handle, vertexCount, instanceCount or 1, firstVertex or 0,\n\t\tfirstInstance or 0)\nend\n\nlocal descriptorSetArray = vk.DescriptorSetArray(1)\n\n---@param index number\n---@param bindGroup hood-vk.BindGroup\n--- Put every subresource of a freshly created texture into one layout.\n---\n--- A texture is sampled through a view, and a descriptor covers the whole view,\n--- so every layer of a sampled texture has to be in the layout the descriptor is\n--- written with -- even the ones nothing was ever written to. A layer left in\n--- UNDEFINED fails VUID-vkCmdDraw-None-09600 and reads as nothing, so writing\n--- layer 0 of an array would otherwise make every later layer sample as empty.\n---\n--- This belongs at creation, which is the only point with a command buffer of\n--- its own outside a render pass: hood's render passes do not allow barriers\n--- within them (VUID-vkCmdPipelineBarrier-None-07889).\n---\n--- Only correct before the image has been written to, since a layer with its own\n--- tracked layout has already been moved somewhere deliberately. Texture\n--- creators call it once; `texture.layoutDefault` records the result.\n---@param texture hood-vk.Texture\n---@return boolean claimed\nfunction VKCommandEncoder:claimTexture(texture)\n\tif texture.layoutDefault then\n\t\treturn false\n\tend\n\n\t-- A depth texture is left alone: the barrier below is a colour one, and a depth\n\t-- image is moved into the layout a shader reads by the pass that writes it, which\n\t-- is the only place that can put it there before anything samples it.\n\tif texture.isDepth then\n\t\treturn false\n\tend\n\n\t-- Only a texture that can be sampled is moved into a shader read layout:\n\t-- VUID-VkImageMemoryBarrier-oldLayout-01211 requires the SAMPLED usage for\n\t-- it, and render attachment layouts are the render pass's business.\n\tlocal canSample = texture.usage\n\t\tand bit.band(texture.usage, vk.ImageUsageFlagBits.SAMPLED) ~= 0\n\tif not canSample then\n\t\treturn false\n\tend\n\n\tlocal whole = vk.ImageMemoryBarrierArray(1)\n\twhole[0].srcAccessMask = 0\n\twhole[0].dstAccessMask = vk.AccessFlags.SHADER_READ\n\twhole[0].oldLayout = vk.ImageLayout.UNDEFINED\n\twhole[0].newLayout = vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\n\twhole[0].srcQueueFamilyIndex = 0xFFFFFFFF -- VK_QUEUE_FAMILY_IGNORED\n\twhole[0].dstQueueFamilyIndex = 0xFFFFFFFF\n\twhole[0].image = texture.handle\n\twhole[0].subresourceRange.aspectMask = vk.ImageAspectFlagBits.COLOR\n\twhole[0].subresourceRange.baseMipLevel = 0\n\twhole[0].subresourceRange.levelCount = vk.REMAINING_MIP_LEVELS\n\twhole[0].subresourceRange.baseArrayLayer = 0\n\twhole[0].subresourceRange.layerCount = vk.REMAINING_ARRAY_LAYERS\n\n\tself.device.handle:cmdPipelineBarrier(\n\t\tself.buffer.handle,\n\t\tvk.PipelineStageFlagBits.TOP_OF_PIPE,\n\t\tvk.PipelineStageFlagBits.FRAGMENT_SHADER,\n\t\t1, whole)\n\n\ttexture.layerLayouts = {}\n\ttexture.layoutDefault = vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\n\treturn true\nend\n\nfunction VKCommandEncoder:setBindGroup(index, bindGroup)\n\tlocal bindPoint, layout\n\tif self.pipeline then\n\t\tbindPoint = vk.PipelineBindPoint.GRAPHICS\n\t\tlayout = self.pipeline.layout\n\telseif self.computePipeline then\n\t\tbindPoint = vk.PipelineBindPoint.COMPUTE\n\t\tlayout = self.computePipeline.layout\n\telse\n\t\terror(\"No pipeline set\")\n\tend\n\n\tself.bindGroups[index] = bindGroup\n\tdescriptorSetArray[0] = bindGroup.set\n\n\tself.device.handle:cmdBindDescriptorSets(\n\t\tself.buffer.handle,\n\t\tbindPoint,\n\t\tlayout,\n\t\tindex,\n\t\t1,\n\t\tdescriptorSetArray,\n\t\t0\n\t)\nend\n\n--- End the open render pass.\n---\n--- A pass is only started when a pipeline is bound, so calling this without one\n--- means the frame recorded an end with no matching begin. The driver does not\n--- validate that: it executes a command buffer whose render pass never started,\n--- which on at least one desktop driver is a segfault rather than an error.\nfunction VKCommandEncoder:endRendering()\n\tif not self.inRenderPass then\n\t\terror(\"hood: endRendering was called with no open render pass; a pass is \"\n\t\t\t.. \"started by setPipeline, so bind the pipeline before drawing, even \"\n\t\t\t.. \"for a frame with nothing in it\")\n\tend\n\n\tself.inRenderPass = false\n\tself.device.handle:cmdEndRenderPass(self.buffer.handle)\n\n\t-- A depth attachment the frame goes on to sample was left by the pass in the layout\n\t-- a shader reads, so what is left is to make its writes visible to those reads. A\n\t-- barrier cannot be recorded inside a render pass, which is why it is here rather\n\t-- than with the pass that wrote it\n\tlocal depth = self.sampleableDepth\n\tif depth then\n\t\tlocal layers = self.sampleableDepthLayers or 1\n\t\tself.sampleableDepth = nil\n\t\tself.sampleableDepthLayers = nil\n\n\t\tlocal barrier = self.depthBarrier[0]\n\t\tbarrier.srcAccessMask = vk.AccessFlags.DEPTH_STENCIL_ATTACHMENT_WRITE\n\t\tbarrier.dstAccessMask = vk.AccessFlags.SHADER_READ\n\t\tbarrier.oldLayout = vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\n\t\tbarrier.newLayout = vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\n\t\tbarrier.srcQueueFamilyIndex = 0xFFFFFFFF -- VK_QUEUE_FAMILY_IGNORED\n\t\tbarrier.dstQueueFamilyIndex = 0xFFFFFFFF\n\t\tbarrier.image = depth.handle\n\t\tbarrier.subresourceRange.aspectMask = vk.ImageAspectFlagBits.DEPTH\n\t\tbarrier.subresourceRange.baseMipLevel = 0\n\t\tbarrier.subresourceRange.levelCount = 1\n\t\tbarrier.subresourceRange.baseArrayLayer = 0\n\t\tbarrier.subresourceRange.layerCount = layers\n\n\t\tself.device.handle:cmdPipelineBarrier(\n\t\t\tself.buffer.handle,\n\t\t\tvk.PipelineStageFlagBits.LATE_FRAGMENT_TESTS,\n\t\t\tvk.PipelineStageFlagBits.FRAGMENT_SHADER,\n\t\t\t1, self.depthBarrier)\n\tend\nend\n\n--- Begin the pass, refusing to nest one inside another.\n---\n--- Vulkan rejects a second vkCmdBeginRenderPass before the matching end, and the\n--- driver's response to the resulting command stream is a crash rather than an\n--- error, so this is checked here where the offending call is identifiable.\n---@param beginInfo vk.ffi.RenderPassBeginInfo\n---@private\nfunction VKCommandEncoder:_beginRenderPassRaw(beginInfo)\n\tif self.inRenderPass then\n\t\terror(\"hood: beginRendering was called while a render pass is already open\")\n\tend\n\n\tself.inRenderPass = true\n\tself.device.handle:cmdBeginRenderPass(self.buffer.handle, beginInfo, vk.SubpassContents.INLINE)\nend\n\n--- Make staged uploads visible to the commands that read them.\n---\n--- A vkCmdCopyBuffer into a buffer that a later draw reads is a transfer write\n--- followed by a read with no dependency between them, which is undefined\n--- behaviour; sync validation reports it as SYNC-HAZARD-READ-AFTER-WRITE. The\n--- previous vkCmdUpdateBuffer path had exactly the same hole, so this is a\n--- pre-existing bug rather than one the staging rewrite introduced.\n---\n--- One barrier covers everything staged in this command buffer, emitted when\n--- the reads are about to start rather than after every copy.\n---@private\nfunction VKCommandEncoder:_flushStagedWrites()\n\tif not self.stagedWrites then\n\t\treturn\n\tend\n\tself.stagedWrites = false\n\n\tlocal barrier = self.memoryBarrier[0]\n\tbarrier.srcAccessMask = vk.AccessFlags.TRANSFER_WRITE\n\tbarrier.dstAccessMask = bit.bor(\n\t\tvk.AccessFlags.MEMORY_READ,\n\t\tvk.AccessFlags.INDEX_READ,\n\t\tvk.AccessFlags.VERTEX_ATTRIBUTE_READ,\n\t\tvk.AccessFlags.UNIFORM_READ,\n\t\tvk.AccessFlags.SHADER_READ,\n\t\tvk.AccessFlags.INDIRECT_COMMAND_READ)\n\n\t-- Not usable inside a render pass, where the stage masks have to stay within\n\t-- the graphics stages; both call sites are outside one.\n\tself.device.handle:cmdPipelineBarrier(\n\t\tself.buffer.handle,\n\t\tvk.PipelineStageFlagBits.TRANSFER,\n\t\tvk.PipelineStageFlagBits.ALL_COMMANDS,\n\t\t0, nil,\n\t\t1, self.memoryBarrier)\nend\n\n--- Hand out `size` bytes of host-visible staging memory for this command\n--- buffer, allocating or growing the staging buffer as needed.\n---\n--- The staging buffer lives on the command buffer rather than the encoder,\n--- because copies recorded from it are only finished once the command buffer\n--- retires at the end of the frame. Swapchain command buffers are reused per\n--- frame slot and the slot waits its fence before being re-recorded, so the\n--- same allocation is safely reused next frame; a command buffer destroyed\n--- after one use frees it with everything else.\n---\n--- A staging buffer that is outgrown mid-frame is still referenced by copies\n--- already recorded into it, so it is handed to the transient resource list and\n--- freed when the command buffer is recycled instead of immediately.\n---\n--- It is made the size it has to be rather than the next power of two past it: an\n--- upload of a picture is one of these, and doubling a four megabyte one to eight\n--- is memory asked of a driver that may not have it to spare -- the window host\n--- visible memory comes out of is a small one on most machines.\n---@param size number\n---@return { buffer: vk.ffi.Buffer, memory: vk.ffi.DeviceMemory, pointer: ffi.cdata*, size: number, offset: number }\n---@private\nfunction VKCommandEncoder:_staging(size)\n\tlocal staging = self.buffer.staging\n\n\tif staging and staging.offset + size <= staging.size then\n\t\treturn staging\n\tend\n\n\tif staging then\n\t\tself:_trackStagingResource(staging.buffer, staging.memory)\n\tend\n\n\tlocal needed = (staging and staging.offset or 0) + size\n\tlocal capacity = math.max(STAGING_MIN_SIZE, needed)\n\n\tstaging = memory.createMapped(self.device, capacity,\n\t\tvk.BufferUsageFlagBits.TRANSFER_SRC)\n\tstaging.offset = 0\n\tself.buffer.staging = staging\n\n\treturn staging\nend\n\n--- Upload CPU data into a buffer.\n---\n--- A mapped buffer is written directly by the CPU: no staging, no copy command,\n--- nothing submitted. That is the path per-frame data should take.\n---\n--- Everything else goes through host-visible staging memory and a\n--- vkCmdCopyBuffer. vkCmdUpdateBuffer was the old path here, but the spec\n--- intends it for small updates only, and it is stricter than a copy: its\n--- dataSize must be a multiple of 4 (validation reports\n--- VUID-vkCmdUpdateBuffer-dataSize-00038), so writing a 6 byte index buffer was\n--- never actually valid, and it is capped at 65536 bytes per call, which hood\n--- used to work around by chunking. vkCmdCopyBuffer has neither restriction,\n--- and drivers implement it as a straight transfer instead of as an internal\n--- update path intended for a few hundred bytes.\n---@param buffer hood-vk.Buffer\n---@param size number\n---@param data ffi.cdata*\n---@param offset number?\nfunction VKCommandEncoder:writeBuffer(buffer, size, data, offset)\n\toffset = offset or 0\n\tif size == 0 then\n\t\treturn\n\tend\n\n\tbuffer:assertWriteFits(size, offset, data)\n\n\tif buffer.isMapped then\n\t\tffi.copy(buffer:mappedPointer(offset), data, size)\n\t\treturn\n\tend\n\n\tlocal staging = self:_staging(size)\n\tffi.copy(staging.pointer + staging.offset, data, size)\n\n\tlocal region = self.bufferCopy[0]\n\tregion.srcOffset = staging.offset\n\tregion.dstOffset = offset\n\tregion.size = size\n\n\tself.device.handle:cmdCopyBuffer(self.buffer.handle, staging.buffer,\n\t\tbuffer.handle, 1, self.bufferCopy)\n\n\tstaging.offset = staging.offset + size\n\tself.stagedWrites = true\nend\n\n--- Issue `drawCount` indexed draws recorded in `buffer`, reading one command\n--- every `stride` bytes from `offset`.\n---\n--- Every draw shares the bound vertex buffers and index buffer, so each command\n--- selects its geometry through firstIndex and vertexOffset rather than by\n--- rebinding. That is what lets a whole frame's instanced draws go out as one\n--- call, and it costs one 20 byte record per draw instead of a draw command in\n--- the command stream.\n---\n--- The buffer needs the INDIRECT usage, and its commands need the\n--- drawIndirectFirstInstance feature when firstInstance is nonzero.\n---@param buffer hood-vk.Buffer\n---@param offset number\n---@param drawCount number\n---@param stride number\nfunction VKCommandEncoder:drawIndexedIndirect(buffer, offset, drawCount, stride)\n\tself.device.handle:cmdDrawIndexedIndirect(self.buffer.handle, buffer.handle,\n\t\toffset or 0, drawCount, stride)\nend\n\n--- Copy bytes between two buffers on the GPU. The source needs COPY_SRC and\n--- the destination COPY_DST.\n---\n--- Vulkan only for now: the OpenGL backend would need\n--- glCopyNamedBufferSubData, which glapi does not expose yet.\n---@param source hood-vk.Buffer\n---@param destination hood-vk.Buffer\n---@param size number\n---@param sourceOffset number?\n---@param destinationOffset number?\nfunction VKCommandEncoder:copyBuffer(source, destination, size, sourceOffset, destinationOffset)\n\tsourceOffset = sourceOffset or 0\n\tdestinationOffset = destinationOffset or 0\n\tif size == 0 then\n\t\treturn\n\tend\n\n\t-- Both the read and the write have to stay inside their own buffer.\n\tsource:assertWriteFits(size, sourceOffset)\n\tdestination:assertWriteFits(size, destinationOffset)\n\n\tlocal region = self.bufferCopy[0]\n\tregion.srcOffset = sourceOffset\n\tregion.dstOffset = destinationOffset\n\tregion.size = size\n\n\tself.device.handle:cmdCopyBuffer(self.buffer.handle, source.handle,\n\t\tdestination.handle, 1, self.bufferCopy)\n\tself.stagedWrites = true\nend\n\n---@param stagingBuffer vk.ffi.Buffer\n---@param stagingMemory vk.ffi.DeviceMemory\nfunction VKCommandEncoder:_trackStagingResource(stagingBuffer, stagingMemory)\n\tif not self.buffer.stagingResources then\n\t\tself.buffer.stagingResources = {}\n\tend\n\tself.buffer.stagingResources[#self.buffer.stagingResources + 1] = {\n\t\tbuffer = stagingBuffer,\n\t\tmemory = stagingMemory,\n\t}\nend\n\n-- TODO: Completely rewrite this\n---@param texture hood-vk.Texture\n---@param descriptor hood.TextureWriteDescriptor\n---@param data ffi.cdata*\nfunction VKCommandEncoder:writeTexture(texture, descriptor, data)\n\tlocal width = descriptor.width\n\tlocal height = descriptor.height\n\tlocal depth = descriptor.depth or 1\n\tlocal dataSize = (descriptor.bytesPerRow or (width * 4)) * height * depth\n\n\t-- Staging is bump-allocated per command buffer and shared with buffer\n\t-- uploads, instead of a fresh buffer, memory allocation and mapping on\n\t-- every single texture.\n\tlocal staging = self:_staging(dataSize)\n\tlocal stagingBuffer = staging.buffer\n\tlocal stagingOffset = staging.offset\n\n\tffi.copy(staging.pointer + stagingOffset, data + (descriptor.offset or 0), dataSize)\n\tstaging.offset = stagingOffset + math.ceil(dataSize / 4) * 4\n\n\t-- Transition image to TRANSFER_DST_OPTIMAL\n\tlocal mip = descriptor.mip or 0\n\tlocal layer = descriptor.layer or 0\n\n\t-- Use tracked layout if available, then whatever the image was claimed with\n\t-- at creation, and only then UNDEFINED for a texture nothing has touched.\n\ttexture.layerLayouts = texture.layerLayouts or {}\n\tlocal oldLayout = texture.layerLayouts[layer] or texture.layoutDefault or vk.ImageLayout.UNDEFINED\n\tlocal srcAccessMask = 0\n\tlocal srcStage = vk.PipelineStageFlagBits.TOP_OF_PIPE\n\tif oldLayout == vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL then\n\t\tsrcAccessMask = vk.AccessFlags.SHADER_READ\n\t\tsrcStage = vk.PipelineStageFlagBits.FRAGMENT_SHADER\n\tend\n\n\tlocal barriers = vk.ImageMemoryBarrierArray(1)\n\tbarriers[0].srcAccessMask = srcAccessMask\n\tbarriers[0].dstAccessMask = vk.AccessFlags.TRANSFER_WRITE\n\tbarriers[0].oldLayout = oldLayout\n\tbarriers[0].newLayout = vk.ImageLayout.TRANSFER_DST_OPTIMAL\n\tbarriers[0].srcQueueFamilyIndex = 0xFFFFFFFF -- VK_QUEUE_FAMILY_IGNORED\n\tbarriers[0].dstQueueFamilyIndex = 0xFFFFFFFF\n\tbarriers[0].image = texture.handle\n\tbarriers[0].subresourceRange.aspectMask = vk.ImageAspectFlagBits.COLOR\n\tbarriers[0].subresourceRange.baseMipLevel = mip\n\tbarriers[0].subresourceRange.levelCount = 1\n\tbarriers[0].subresourceRange.baseArrayLayer = layer\n\tbarriers[0].subresourceRange.layerCount = 1\n\n\tself.device.handle:cmdPipelineBarrier(\n\t\tself.buffer.handle,\n\t\tsrcStage,\n\t\tvk.PipelineStageFlagBits.TRANSFER,\n\t\t1, barriers)\n\n\t-- Copy buffer to image. The staging allocation is bump-allocated, so the\n\t-- region has to point at this upload's slice of it rather than assuming the\n\t-- data starts at zero.\n\tlocal region = vk.BufferImageCopyArray(1)\n\tregion[0].bufferOffset = stagingOffset\n\tregion[0].bufferRowLength = descriptor.bytesPerRow and (descriptor.bytesPerRow / 4) or 0\n\tregion[0].bufferImageHeight = descriptor.rowsPerImage or 0\n\tregion[0].imageSubresource.aspectMask = vk.ImageAspectFlagBits.COLOR\n\tregion[0].imageSubresource.mipLevel = mip\n\tregion[0].imageSubresource.baseArrayLayer = layer\n\tregion[0].imageSubresource.layerCount = 1\n\tregion[0].imageExtent.width = width\n\tregion[0].imageExtent.height = height\n\tregion[0].imageExtent.depth = depth\n\n\tself.device.handle:cmdCopyBufferToImage(\n\t\tself.buffer.handle, stagingBuffer, texture.handle,\n\t\tvk.ImageLayout.TRANSFER_DST_OPTIMAL, 1, region)\n\n\t-- Transition image to SHADER_READ_ONLY_OPTIMAL\n\tbarriers[0].srcAccessMask = vk.AccessFlags.TRANSFER_WRITE\n\tbarriers[0].dstAccessMask = vk.AccessFlags.SHADER_READ\n\tbarriers[0].oldLayout = vk.ImageLayout.TRANSFER_DST_OPTIMAL\n\tbarriers[0].newLayout = vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\n\n\tself.device.handle:cmdPipelineBarrier(\n\t\tself.buffer.handle,\n\t\tvk.PipelineStageFlagBits.TRANSFER,\n\t\tvk.PipelineStageFlagBits.FRAGMENT_SHADER,\n\t\t1, barriers)\n\n\t-- Track current layout per layer\n\ttexture.layerLayouts[layer] = vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\nend\n\nlocal copyBarrier = vk.ImageMemoryBarrierArray(1)\n\n---@param source hood.ImageCopyTexture\n---@param destination hood.ImageCopyBuffer\n---@param copySize hood.Extent3D\nfunction VKCommandEncoder:copyTextureToBuffer(source, destination, copySize)\n\tlocal texture = source.texture --[[@as hood-vk.Texture]]\n\tlocal buffer = destination.buffer --[[@as hood-vk.Buffer]]\n\tlocal mipLevel = source.mipLevel or 0\n\tlocal origin = source.origin or {}\n\tlocal layer = origin.z or 0\n\n\ttexture.layerLayouts = texture.layerLayouts or {}\n\tlocal oldLayout = texture.layerLayouts[layer] or vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL\n\n\tlocal srcAccessMask = vk.AccessFlags.COLOR_ATTACHMENT_WRITE\n\tlocal srcStage = vk.PipelineStageFlagBits.COLOR_ATTACHMENT_OUTPUT\n\tif oldLayout == vk.ImageLayout.SHADER_READ_ONLY_OPTIMAL then\n\t\tsrcAccessMask = vk.AccessFlags.SHADER_READ\n\t\tsrcStage = vk.PipelineStageFlagBits.FRAGMENT_SHA