package.preload["hood.instance"] = function(...) return load("-- Which backend an instance is made on.\n--\n-- The backends are packages of their own and a program installs the one it runs on: an app\n-- whose lde.json names hood with `\"features\": [ \"vk\" ]` is a vulkan program, \"gl\" is an\n-- opengl one, and naming both is a program that picks at runtime. Neither is installed\n-- unless it is named, because the backend a program does not run on is a graphics API's\n-- worth of code sitting in its bundle for nothing -- so asking for one that is not here\n-- says so, rather than failing somewhere inside a require.\nlocal Instance = {}\n\n---@type table<hood.InstanceBackend, string> # the package each backend lives in\nlocal PACKAGES = {\n\tvulkan = \"hood-vk\",\n\topengl = \"hood-gl\",\n}\n\n---@param descriptor hood.InstanceDescriptor\n---@return hood.Instance\nfunction Instance.new(descriptor)\n\t---@type hood.InstanceBackend\n\tlocal backend = descriptor.backend\n\n\tlocal package = PACKAGES[backend]\n\n\tif not package then\n\t\terror(\"No supported backends specified in instance descriptor.\")\n\tend\n\n\t-- NOTE: This dynamically requires the backend specific module to avoid loading unnecessary code\n\tlocal ok, instance = pcall(require, package)\n\n\tif not ok then\n\t\terror(\"hood was installed without the \" .. backend .. \" backend: name it where hood \"\n\t\t\t.. \"is depended on, as {\\\"features\\\": [\\\"\"\n\t\t\t.. (backend == \"vulkan\" and \"vk\" or \"gl\") .. \"\\\"]}\")\n\tend\n\n\treturn instance.new(descriptor)\nend\n\nreturn Instance\n", "@hood.instance")(...) end
package.preload["hood-vk.queue"] = function(...) return load("local vk = require(\"vkapi\")\nlocal ffi = require(\"ffi\")\n\nlocal VKCommandBuffer = require(\"hood-vk.command_buffer\")\nlocal VKCommandEncoder = require(\"hood-vk.command_encoder\")\n\n---@class hood-vk.Queue\n---@field device hood-vk.Device\n---@field handle vk.ffi.Queue\n---@field familyIdx number\n---@field idx number\n---@field _transient hood-vk.CommandBuffer? # The buffer this queue's own uploads are recorded into\nlocal VKQueue = {}\nVKQueue.__index = VKQueue\n\n---@param device hood-vk.Device\n---@param familyIdx number\n---@param idx number\nfunction VKQueue.new(device, familyIdx, idx)\n\tlocal handle = device.handle:getDeviceQueue(familyIdx, idx)\n\treturn setmetatable({ device = device, handle = handle, familyIdx = familyIdx, idx = idx }, VKQueue)\nend\n\nlocal commandBuffers = ffi.new(\"VkCommandBuffer[1]\")\nlocal waitSemaphores = ffi.new(\"VkSemaphore[1]\")\nlocal signalSemaphores = ffi.new(\"VkSemaphore[1]\")\nlocal waitStages = ffi.new(\"uint32_t[1]\", vk.PipelineStageFlagBits.COLOR_ATTACHMENT_OUTPUT)\nlocal submitArray = vk.SubmitInfoArray(1)\n\n-- Cold path: keep the message formatting out of the hot function so the trace\n-- recorded for submit() stays small enough to compile.\nlocal function submitFailed(result)\n\terror(\"Failed to submit to Vulkan queue, error code: \" .. tostring(result))\nend\n\n---@param buffer hood-vk.CommandBuffer\nfunction VKQueue:submit(buffer)\n\tcommandBuffers[0] = buffer.handle\n\n\tlocal info = submitArray[0]\n\tinfo.commandBufferCount = 1\n\tinfo.pCommandBuffers = commandBuffers\n\n\t-- Use the swapchain directly (stored as a single ref, not a table)\n\tlocal swapchain = buffer._swapchain\n\tlocal fence\n\n\tif swapchain then\n\t\t-- Both semaphores are indexed by currentFrame (per frame-in-flight).\n\t\t-- This ensures each frame slot has a dedicated pair of semaphores,\n\t\t-- avoiding index desync between currentFrame and currentVkImageIdx.\n\t\tlocal frame = swapchain.currentFrame\n\t\twaitSemaphores[0] = swapchain.imageAvailableSemaphores[frame]\n\t\tsignalSemaphores[0] = swapchain.renderFinishedSemaphores[frame]\n\t\tinfo.waitSemaphoreCount = 1\n\t\tinfo.pWaitSemaphores = waitSemaphores\n\t\tinfo.pWaitDstStageMask = waitStages\n\t\tinfo.signalSemaphoreCount = 1\n\t\tinfo.pSignalSemaphores = signalSemaphores\n\t\tfence = swapchain.inFlightFences[frame]\n\telse\n\t\tinfo.waitSemaphoreCount = 0\n\t\tinfo.pWaitSemaphores = nil\n\t\tinfo.pWaitDstStageMask = nil\n\t\tinfo.signalSemaphoreCount = 0\n\t\tinfo.pSignalSemaphores = nil\n\t\tfence = 0\n\tend\n\n\tlocal result = self.device.handle.v1_0.vkQueueSubmit(self.handle, 1, submitArray, fence)\n\tif result ~= 0 then\n\t\tsubmitFailed(result)\n\tend\nend\n\n-- TODO: This currently uses a blocking wait for simplicity and to avoid a use after free (from lua's gc)\n-- Should eventually use a form of garbage collection managed by the VKQueue\n\n--- Helper method to write data to a buffer\n---@param buffer hood-vk.Buffer\n---@param size number\n---@param data ffi.cdata*\n---@param offset number?\n--- The command buffer the queue's own uploads are recorded into: one per queue, recorded\n--- again for each of them. Every caller waits for the queue to be idle before it is done,\n--- so the recording that follows is free to be the same buffer -- which is what keeps an\n--- upload from costing a command buffer, and the pool one would be allocated from, every\n--- time it happens.\n---@return hood-vk.CommandBuffer\nfunction VKQueue:transientBuffer()\n\tif not self._transient then\n\t\tself._transient = VKCommandBuffer.new(self.device)\n\tend\n\n\treturn self._transient\nend\n\n---@param buffer hood-vk.Buffer\n---@param size number\n---@param data ffi.cdata*\n---@param offset number?\nfunction VKQueue:writeBuffer(buffer, size, data, offset)\n\toffset = offset or 0\n\tif size == 0 then\n\t\treturn\n\tend\n\tbuffer:assertWriteFits(size, offset, data)\n\n\t-- A mapped buffer is