package.preload["hood-vk.surface"] = function(...) return load("local vk = require(\"vkapi\")\nlocal vkConversions = require(\"hood-vk.convert\")\n\nlocal VKSwapchain = require(\"hood-vk.swapchain\")\n\nlocal isWindows = jit.os == \"Windows\"\n\n---@class hood-vk.Surface\n---@field window winit.Window\n---@field handle vk.ffi.SurfaceKHR\n---@field instance hood-vk.Instance\nlocal VKSurface = {}\nVKSurface.__index = VKSurface\n\n---@param instance hood-vk.Instance\n---@param window winit.Window\nfunction VKSurface.new(instance, window)\n\tlocal handle ---@type vk.ffi.SurfaceKHR\n\tif isWindows then ---@cast window winit.win32.Window\n\t\tlocal kernel32 = require(\"winapi.kernel32\")\n\n\t\thandle = instance.handle:createWin32SurfaceKHR({\n\t\t\thinstance = kernel32.getModuleHandle(nil),\n\t\t\thwnd = window.hwnd,\n\t\t})\n\telse ---@cast window winit.x11.Window\n\t\thandle = instance.handle:createXlibSurfaceKHR({\n\t\t\tdpy = window.display,\n\t\t\twindow = window.id,\n\t\t})\n\tend\n\n\treturn setmetatable({ window = window, handle = handle, instance = instance }, VKSurface)\nend\n\n---@param device hood-vk.Device\n---@param config hood.SurfaceConfig\n---@param oldSwapchain hood-vk.Swapchain?\n---@return hood-vk.Swapchain\nfunction VKSurface:configure(device, config, oldSwapchain)\n\t-- The old swapchain is deliberately not torn down here: it is still needed\n\t-- as the `oldSwapchain` argument below so the new one can take over its\n\t-- images. It is destroyed in full once the replacement exists.\n\n\tlocal caps = vk.getPhysicalDeviceSurfaceCapabilitiesKHR(device.pd, self.handle)\n\tlocal formats = vk.getPhysicalDeviceSurfaceFormatsKHR(device.pd, self.handle)\n\n\t---@type vk.ffi.SurfaceFormatKHR\n\tlocal format = formats[1]\n\n\tlocal imageCount = caps.minImageCount + 1\n\tif caps.maxImageCount > 0 and imageCount > caps.maxImageCount then\n\t\timageCount = caps.maxImageCount\n\tend\n\n\tlocal extent = caps.currentExtent\n\tif extent.width == 0xFFFFFFFF then\n\t\textent.width = self.window.width\n\t\textent.height = self.window.height\n\tend\n\n\tlocal hoodFormat = vkConversions.from.textureFormat[format.format]\n\tif not hoodFormat then\n\t\terror(\"Unsupported swapchain format: \" .. tostring(format.format))\n\tend\n\n\t-- Query supported present modes and validate requested mode\n\tlocal presentModes = vk.getPhysicalDeviceSurfacePresentModesKHR(device.pd, self.handle)\n\tlocal requestedPresentMode = vkConversions.presentMode[config.presentMode]\n\n\t---@type vk.PresentModeKHR?\n\tlocal presentMode = nil\n\tfor _, mode in ipairs(presentModes) do\n\t\tif mode == requestedPresentMode then\n\t\t\tpresentMode = requestedPresentMode\n\t\t\tbreak\n\t\tend\n\tend\n\n    if not presentMode then\n        error(\"Requested present mode not supported: \" .. tostring(config.presentMode))\n    end\n\n    local swapchainInfo = vk.SwapchainCreateInfoKHR({\n    \tsurface = self.handle,\n\t\tminImageCount = imageCount,\n\t\timageFormat = format.format,\n\t\timageColorSpace = format.colorSpace,\n\t\timageExtent = extent,\n\t\timageArrayLayers = 1,\n\t\timageUsage = vk.ImageUsageFlagBits.COLOR_ATTACHMENT,\n\t\timageSharingMode = vk.SharingMode.EXCLUSIVE,\n\t\tpreTransform = caps.currentTransform,\n\t\tcompositeAlpha = vk.CompositeAlphaFlagBitsKHR.OPAQUE,\n\t\tpresentMode = presentMode,\n\t\tclipped = 1,\n\t\toldSwapchain = oldSwapchain and oldSwapchain.handle or nil\n    })\n\n\tlocal newSwapchain = VKSwapchain.new(device, hoodFormat, swapchainInfo)\n\n\tif oldSwapchain then\n\t\t-- Full teardown, not just the sync objects and command buffers: the\n\t\t-- old swapchain's framebuffers and image views reference images that\n\t\t-- destroySwapchainKHR is about to invalidate, so they have to go first.\n\t\t-- This waits for the queue to go idle, which also makes it safe for the\n\t\t-- caller to drop anything the old swapchain was rendering into.\n\t\toldSwapchain:destroy()\n\tend\n\n\treturn newSwapchain\nend\n\nreturn VKSurface\n", "@hood-vk.surface")(...) end
package.preload["wonderland.backend"] = function(...) return load("-- Which GPU backend the app runs on.\n--\n-- Vulkan is the default; OpenGL is there for machines without it, and both the\n-- build and the runtime have to agree on the choice, hence the one place:\n--\n--   OPENGL=1 lde ./examples/app.lua\n-- A build embeds the shader flavor it was made for, so what the build left behind is what the\n-- run is: asking for the flavor the other backend needs is asking for a module that was never\n-- written, and a build for OpenGL run without OPENGL=1 is exactly that. The environment chooses\n-- only when the build has both flavors, which is what a build with no setting leaves.\nlocal spirv = pcall(require, \"wonderland.shaders.main.vert.spv\")\nlocal glsl = pcall(require, \"wonderland.shaders.main.vert.glsl\")\n\nlocal name = os.getenv(\"OPENGL\") and \"opengl\" or \"vulkan\"\n\nif spirv and not glsl then\n\tname = \"vulkan\"\nelseif glsl and not spirv then\n\tname = \"opengl\"\nend\n\nlocal isVulkan = name == \"vulkan\"\n\n---@class wonderland.Backend\n---@field name hood.InstanceBackend\n---@field isVulkan boolean\n---@field shaderType \"spirv\" | \"glsl\" # What the backend's pipelines take\n---@field shaderExt \"spv\" | \"glsl\" # The embedded shader flavor that matches\nlocal backend = {\n\tname = name,\n\tisVulkan = isVulkan,\n\tshaderType = isVulkan and \"spirv\" or \"glsl\",\n\tshaderExt = isVulkan and \"spv\" or \"glsl\",\n}\n\nreturn backend\n", "@wonderland.backend")(...) end
package.preload["hood-vk.swapchain"] = function(...) return load("local ffi = require(\"ffi\")\nlocal vk = require(\"vkapi\")\n\nlocal VKTexture = require(\"hood-vk.texture\")\nlocal VKCommandBuffer = require(\"hood-vk.command_buffer\")\nlocal VKCommandEncoder = require(\"hood-vk.command_encoder\")\n\n\n---@class hood-vk.Swapchain\n---@field handle vk.ffi.SwapchainKHR\n---@field device hood-vk.Device\n---@field images vk.ffi.Image[] # 1 indexed array of VkImage handles\n---@field currentVkImageIdx integer\n---@field imageAvailableSemaphores vk.ffi.Semaphore[]\n---@field renderFinishedSemaphores vk.ffi.Semaphore[]\n---@field inFlightFences vk.ffi.Fence[]\n---@field currentFrame integer\n---@field imageFormat vk.Format\n---@field format hood.TextureFormat\n---@field width number\n---@field height number\n---@field commandBuffers hood-vk.CommandBuffer[] Pre-allocated command buffers, one per swapchain image\n---@field imageCount integer Number of swapchain images (cached to avoid #images per frame)\n---@field imageViews vk.ffi.ImageView[] # 1 indexed array of pre-created VkImageViews\n---@field _framebufferCache table<userdata, table<integer, { framebuffer: vk.ffi.Framebuffer, width: number, height: number }>>\n---@field _cachedRenderPass vk.ffi.RenderPass?\nlocal VKSwapchain = {}\nVKSwapchain.__index = VKSwapchain\n\n---@param device hood-vk.Device\n---@param format hood.TextureFormat\n---@param info vk.ffi.SwapchainCreateInfoKHR\nfunction VKSwapchain.new(device, format, info)\n\tlocal handle = device.handle:createSwapchainKHR(info)\n\tlocal images = device.handle:getSwapchainImagesKHR(handle)\n\n\tlocal imageAvailableSemaphores = {}\n\tlocal renderFinishedSemaphores = {}\n\tlocal inFlightFences = {}\n\tfor i = 1, #images do\n\t\timageAvailableSemaphores[i] = device.handle:createSemaphore({})\n\t\trenderFinishedSemaphores[i] = device.handle:createSemaphore({})\n\t\tinFlightFences[i] = device.handle:createFence({ flags = vk.FenceCreateFlagBits.SIGNALED })\n\tend\n\n\t-- Pre-allocate command buffers (one per swapchain image) to avoid\n\t-- creating and destroying pools every frame.\n\tlocal commandBuffers = {}\n\tfor i = 1, #images do\n\t\tcommandBuffers[i] = VKCommandBuffer.new(device)\n\tend\n\n\t-- Pre-create image views for each swapchain image so we don't\n\t-- create and destroy them every frame.\n\tlocal imageViews = {}\n\n\tfor i = 1, #images do\n\t\timageViews[i] = device.handle:createImageView({\n\t\t\timage = images[i],\n\t\t\tviewType = vk.ImageViewType.TYPE_2D,\n\t\t\tformat = info.imageFormat,\n\t\t\tsubresourceRange = {\n\t\t\t\taspectMask = vk.ImageAspectFlagBits.COLOR,\n\t\t\t\tbaseMipLevel = 0,\n\t\t\t\tlevelCount = 1,\n\t\t\t\tbaseArrayLayer = 0,\n\t\t\t\tlayerCount = 1,\n\t\t\t},\n\t\t\tcomponents = nil, --[[@type vk.ffi.ComponentMapping]]\n\t\t})\n\tend\n\n\t-- Framebuffer cache: renderPass -> \"WxH\" string -> imageIdx -> VkFramebuffer\n\tlocal framebufferCache = {}\n\n\treturn setmetatable({\n\t\timages = images,\n\t\timageCount = #images,\n\t\timageViews = imageViews,\n\t\tdevice = device,\n\t\thandle = handle,\n\t\timageAvailableSemaphores = imageAvailableSemaphores,\n\t\trenderFinishedSemaphores = renderFinishedSemaphores,\n\t\tinFlightFences = inFlightFences,\n\t\tcommandBuffers = commandBuffers,\n\t\tcurrentFrame = 1,\n\t\t_framebufferCache = framebufferCache,\n\t\t_retiredFramebuffers = {},\n\t\timageFormat = info.imageFormat,\n\t\tformat = format,\n\t\twidth = info.imageExtent.width,\n\t\theight = info.imageExtent.height,\n\t}, VKSwapchain)\nend\n\nlocal fenceArray = vk.FenceArray(1)\n\nfunction VKSwapchain:getCurrentTexture()\n\tlocal fence = self.inFlightFences[self.currentFrame]\n\tfenceArray[0] = fence\n\n\t-- Wait for this frame's previous work to complete before reusing its semaphores\n\tself.device.handle:waitForFences(1, fenceArray, true, math.huge)\n\n\tlocal sem = self.imageAvailableSemaphores[self.currentFrame]\n\tlocal result, currentVkImageIdx = self.device.handle:acquireNextImageKHR(self.handle, math.huge, sem)\n\n\tif result == vk.Result.ERROR_OUT_OF_DATE_KHR then\n\t\t-- The swapchain no longer matches the surface; the caller has to\n\t\t-- recreate it. Deliberately do NOT reset the fence here: this frame\n\t\t-- will never be submitted, so clearing it would leave it unsignaled\n\t\t-- and the next call's infinite wait would deadlock the process.\n\t\treturn nil\n\telseif result ~= vk.Result.SUCCESS and result ~= vk.Result.SUBOPTIMAL_KHR then\n\t\terror(\"Failed to acquire next image: \" .. tostring(result))\n\tend\n\n\t-- SUBOPTIMAL_KHR still hands back a usable image, so it is a success: the\n\t-- swapchain just no longer matches the surface exactly. Treating it as a\n\t-- failure freezes apps on compositors that report it routinely.\n\n\t-- An image is held now, so this frame is committed to being submitted.\n\tself.device.handle:resetFences(1, fenceArray)\n\n\tlocal imageHandle = self.images[currentVkImageIdx + 1]\n\n\tself.currentVkImageIdx = currentVkImageIdx\n\n\t-- Reuse a single VKTexture to avoid per-frame table allocation and to\n\t-- keep cached texture views (from createView) alive across frames.\n\tif not self._currentTexture then\n\t\tself._currentTexture = VKTexture.fromSwapchainImg(self.device, self, imageHandle,\n\t\t\tself.imageFormat, self.width, self.height, currentVkImageIdx)\n\tend\n\tself._currentTexture.handle = imageHandle\n\tself._currentTexture.swapchainImageIdx = currentVkImageIdx\n\treturn self._currentTexture\nend\n\n--- Create a command encoder that reuses the pre-allocated command buffer\n--- for the current frame slot. This avoids pool allocation/destruction per frame.\n---@return hood-vk.CommandEncoder\nfunction VKSwapchain:createCommandEncoder()\n\treturn VKCommandEncoder.new(self.device, self.commandBuffers[self.currentFrame])\nend\n\n--- Look up or create a framebuffer for the given render pass and current swapchain image.\n--- The framebuffer uses the pre-created image view for this swapchain image index.\n--- Cached per (renderPass, imageIdx) with numeric dimensions, so the per-frame\n--- lookup is a table read plus two number comparisons (no string keys).\n---\n--- When `depthView` is given the framebuffer also holds that depth attachment.\n--- The view is part of the cache identity, so a depth-attached pass is cached\n--- exactly like a colour-only one instead of creating and destroying a\n--- VkFramebuffer every frame.\n---@param renderPass vk.ffi.RenderPass\n---@param width number\n---@param height number\n---@param depthView vk.ffi.ImageView?\nfunction VKSwapchain:getFramebuffer(renderPass, width, height, depthView)\n\tlocal imgIdx = self.currentVkImageIdx -- 0-based\n\n\tlocal cache = self._framebufferCache[renderPass]\n\tif not cache then\n\t\tcache = {}\n\t\tself._framebufferCache[renderPass] = cache\n\tend\n\n\tlocal entry = cache[imgIdx]\n\tif entry and entry.width == width and entry.height == height and entry.depthView == depthView then\n\t\treturn entry.framebuffer\n\tend\n\n\tlocal attachmentCount = depthView and 2 or 1\n\tlocal fbViews = ffi.new(\"VkImageView[?]\", attachmentCount)\n\tfbViews[0] = self.imageViews[imgIdx + 1]\n\tif depthView then\n\t\tfbViews[1] = depthView\n\tend\n\tlocal framebuffer = self.device.handle:createFramebuffer({\n\t\trenderPass = renderPass,\n\t\tattachmentCount = attachmentCount,\n\t\tpAttachments = fbViews,\n\t\twidth = width,\n\t\theight = height,\n\t\tlayers = 1,\n\t})\n\n\t-- Retire (rather than destroy) a replaced framebuffer: it may still be\n\t-- referenced by a command buffer the GPU has not finished executing.\n\tif entry and entry.framebuffer then\n\t\tself._retiredFramebuffers[#self._retiredFramebuffers + 1] = entry.framebuffer\n\tend\n\n\tcache[imgIdx] = {\n\t\tframebuffer = framebuffer,\n\t\twidth = width,\n\t\theight = height,\n\t\tdepthView = depthView,\n\t}\n\n\treturn framebuffer\nend\n\nfunction VKSwapchain:_destroySyncObjects()\n\tself.device.handle:queueWaitIdle(self.device.queue.handle)\n\tfor i = 1, #self.images do\n\t\tself.device.handle:destroySemaphore(self.imageAvailableSemaphores[i])\n\t\tself.device.handle:destroySemaphore(self.renderFinishedSemaphores[i])\n\t\tself.device.handle:destroyFence(self.inFlightFences[i])\n\tend\nend\n\nfunction VKSwapchain:destroy()\n\tself:_destroySyncObjects()\n\n\t-- Destroy pre-allocated command buffers\n\tfor _, buf in ipairs(self.commandBuffers) do\n\t\tbuf:destroy()\n\tend\n\n\t-- Destroy cached framebuffers\n\tfor _, cache in pairs(self._framebufferCache) do\n\t\tfor _, entry in pairs(cache) do\n\t\t\tself.device.handle:destroyFramebuffer(entry.framebuffer)\n\t\tend\n\tend\n\n\t-- Destroy framebuffers that were replaced in the cache\n\tfor _, fb in ipairs(self._retiredFramebuffers) do\n\t\tself.device.handle:destroyFramebuffer(fb)\n\tend\n\tself._retiredFramebuffers = {}\n\n\t-- Destroy pre-created image views\n\tfor _, iv in ipairs(self.imageViews) do\n\t\tself.device.handle:destroyImageView(iv)\n\tend\n\n\tself.device.handle:destroySwapchainKHR(self.handle)\nend\n\nreturn VKSwapchain\n", "@hood-vk.swapchain")(...) end
package.preload["wonderland.element"] = function(...) return load("-- Screens are built by calling: an element is made, given a style and children, and\n-- handed back for the next call.\n--\n--   div():style(card):children(text(\"Hello\"), text(\"World\"))\n--\n-- An element is a struct in one array that is handed out again every repaint, so a\n-- screen is built out of memory that is already there: what the layout reads is a number\n-- at a known offset rather than a table lookup by name. The values that cannot live in a\n-- struct -- the strings, the handlers, whatever the app carries -- are handed out as\n-- numbers as well, into the arrays of this frame's values, so a repaint allocates\n-- whatever the app itself allocates and nothing on top of it.\n--\n-- That is also what makes an element a thing of the frame it was made in: a tree is built\n-- by the view function every repaint and used in that repaint, and one kept across\n-- repaints would be reading what the next repaint put there. The calls say so rather than\n-- reading memory that is no longer theirs.\nlocal bit = require(\"bit\")\nlocal ffi = require(\"ffi\")\nlocal style = require(\"wonderland.style\")\n\nlocal element = {}\n\nffi.cdef [[\n\ttypedef struct {\n\t\tuint32_t baseStyle, hoverStyle, activeStyle, focusStyle;  // what it looks like\n\t\tuint32_t text, name, inputValue;  // strings of this frame, by handle\n\t\tuint32_t run;                // the line it measured into, by handle\n\t\tuint32_t valueRun;           // and the line what is typed into it measures into, for a\n\t\t                             // field that is sized by it: see `element.GROWS`\n\t\tuint32_t childFirst, childCount, nextSibling;  // the children, as a chain\n\t\tuint32_t onclick, onmousemove, onmousedown, onmouseup, ondblclick, oninput, onsubmit, onchange;\n\t\tuint32_t onscroll, oncontextmenu;  // the wheel and the bar of a box that scrolls, and the\n\t\t                                   // button that is not the left one\n\t\tuint32_t ondrop;                   // the files a window was given, over this box\n\t\tuint32_t oncanvas;                 // and the shapes this box draws itself, where it has any\n\t\tuint32_t userdata;           // whatever the app carries, by handle\n\t\tdouble scrollOffset;         // how far its content is scrolled up, 0 for not\n\t\tdouble maxLines;             // the most lines a field that takes a paragraph holds, 0 for no end to it\n\t\tdouble sliderValue;          // where a slider of an element is, and the values its\n\t\tdouble min, max;             // two ends are, which its dragging is reported between\n\t\tuint32_t fontId;             // the font its text is measured in, from the top down\n\t\tuint32_t flags;              // hovered, pressed, focused, takes typing\n\t\tuint32_t index;              // which element this is, from one\n\t\tuint32_t frame;              // the frame it belongs to\n\t} wl_element;\n]]\n\n-- What state an element is in. A hover or press style is used in place of the base one,\n-- so this is what the layout reads to pick which style it is.\nelement.HOVERED, element.PRESSED, element.FOCUSED, element.TEXT_INPUT = 1, 2, 4, 8\nelement.SCROLLS = 16\n\n--- A field that takes more than one line: what it is typed into is one string with breaks in\n--- it, and a break is what return types rather than what submits it.\nelement.MULTILINE = 32\n\n--- A box that is dragged along: pressing in it, and moving while pressed, says where in it the\n--- pointer is. What that means -- a value, a position, a level -- is the app's.\nelement.SLIDE = 64\n\n--- The nub of a slider: a child of one, which is put where the slider's value is rather than\n--- wherever the layout would have stacked it. The box it travels across is the slider's own --\n--- less the nub, so the ends of the box are the ends of the slider -- and how wide that box came\n--- out is the one thing an app cannot work out for itself, which is why the layout does this.\nelement.THUMB = 128\n\n--- A field that is as tall as what has been typed into it: its height is the value's, up to\n--- `maxLines` of it, so a box does not have to be sized for what a field might hold. A field\n--- without this keeps the height its style gave it.\nelement.GROWS = 256\n\n--- One element, as the arena holds it. The language server cannot see an ffi.cdef, so the\n--- fields are spelled out here: it is the only way to get them checked. The ones that\n--- hold a number are a handle -- `text`, `name`, `run`, the handlers -- and are read\n--- through the arrays the frame keeps, not as strings or functions.\n---@class wonderland.Element<T>: ffi.cdata*\n---@field baseStyle number # The slot of the style it is laid out and drawn with\n---@field hoverStyle number # And the one used while the pointer is over it, 0 for none\n---@field activeStyle number # And the one used while it is held down\n---@field focusStyle number\n---@field text number # The line it draws, by handle, 0 for none\n---@field name number # Its own name, for input focus and for finding it\n---@field inputValue number # What has been typed into it, by handle\n---@field run number # The line it measured into, by handle\n---@field valueRun number # And the line what is typed into it measured into, where it is sized by it\n---@field childFirst number\n---@field childCount number\n---@field nextSibling number\n---@field onclick number\n---@field onmousemove number\n---@field onmousedown number\n---@field onmouseup number\n---@field ondblclick number\n---@field oninput number\n---@field onchange number\n---@field sliderValue number # Where a slider is: the value, as the app last said\n---@field min number # And the values its two ends are\n---@field max number\n---@field onsubmit number\n---@field onscroll number\n---@field oncontextmenu number\n---@field oncanvas number # The draw of this element's canvas, by handle, which an app sets with `:canvas`\n---@field ondrop number\n---@field userdata number # Whatever the app carries, by handle\n---@field fontId number\n---@field scrollOffset number # How far its content is scrolled up, and what clips it to its box\n---@field maxLines number # The most lines what is typed into it may hold, 0 for as many as it takes\n---@field flags number\n---@field index number\n---@field frame number\n---@field style fun(self: wonderland.Element, value: wonderland.StyleBuilder | wonderland.Style): wonderland.Element\n---@field hover fun(self: wonderland.Element, value: wonderland.StyleBuilder | wonderland.Style): wonderland.Element\n---@field active fun(self: wonderland.Element, value: wonderland.StyleBuilder | wonderland.Style): wonderland.Element\n---@field focus fun(self: wonderland.Element, value: wonderland.StyleBuilder | wonderland.Style): wonderland.Element\n---@field children fun(self: wonderland.Element, ...: wonderland.IntoElement | wonderland.IntoElement[]): wonderland.Element\n---@field named fun(self: wonderland.Element, name: string): wonderland.Element\n---@field data fun(self: wonderland.Element, data: any): wonderland.Element\n---@field input fun(self: wonderland.Element, opts: wonderland.InputOpts<any>): wonderland.Element\n---@field slider fun(self: wonderland.Element, opts: wonderland.SliderOpts<any>): wonderland.Element\n---@field thumb fun(self: wonderland.Element): wonderland.Element\n---@field scroll fun(self: wonderland.Element, offset: number): wonderland.Element\n---@field onMouseMove fun(self: wonderland.Element, message: any): wonderland.Element\n---@field onClick fun(self: wonderland.Element, message: any): wonderland.Element\n---@field onMouseDown fun(self: wonderland.Element, cons: fun(x: number, y: number, elementWidth: number, elementHeight: number): any): wonderland.Element\n---@field onMouseUp fun(self: wonderland.Element, message: any): wonderland.Element\n---@field onDoubleClick fun(self: wonderland.Element, message: any): wonderland.Element\n---@field onScroll fun(self: wonderland.Element, cons: wonderland.ScrollHandler): wonderland.Element\n---@field onContextMenu fun(self: wonderland.Element, cons: wonderland.ContextMenuHandler): wonderland.Element\n---@field onDrop fun(self: wonderland.Element, cons: wonderland.DropHandler): wonderland.Element\nlocal Element = {}\nelement.Element = Element\n\n---@alias wonderland.IntoElement wonderland.Element | string\n\n--- What a box that scrolls is asked about being scrolled: how far a wheel moved it, or where a bar\n--- dragged to, and one of the two is always nothing. It answers with the message the app is told.\n---@alias wonderland.ScrollHandler fun(by: number?, to: number?): any?\n\n--- What a box is asked when it is pressed with a button that is not the left one, and what it\n--- answers with: the message the app is told. The modifiers are the ones held when it was pressed,\n--- which is the last the keyboard said.\n---@alias wonderland.ContextMenuHandler fun(x: number, y: number, width: number, height: number, modifiers: winit.KeyModifiers?): any?\n\n--- What a box is asked when files are dropped on it: the paths, and where in the box they landed.\n--- It answers with the message the app is told.\n---@alias wonderland.DropHandler fun(paths: string[], x: number, y: number): any?\n\n-- The calls live in their own table rather than on the element: a table is what an ffi\n-- metatype is given for `__index`, and a field of a struct is read before it is asked\n-- for, which is what keeps `element.index` a number and not a call that answers for it.\nlocal methods = {}\nmethods.__index = methods\n\n-- ────────────────────────────────────────────────────────────────\n-- the arena\n-- ────────────────────────────────────────────────────────────────\n\n-- Elements are handed out of blocks that are never moved: growing the arena adds a block\n-- rather than copying the one before it, because an element is a pointer the moment it is\n-- returned and a pointer into memory that has moved is a bug that reads as garbage\n-- later. A block is a few tens of kilobytes, one is enough for a screen of a few hundred\n-- elements, and a screen that needs more is one more.\nlocal BLOCK = 512 -- a power of two: the index picks its block with shifts\nlocal SHIFT, MASK = 9, BLOCK - 1\n\n-- Asserted because `ffi.sizeof` is a number the language server calls possibly-nothing.\nlocal SIZE = assert(ffi.sizeof(\"wl_element\"))\n\nlocal blocks = {}\nlocal pointers = {} -- the elements of this frame, by index, which is what a node holds\nlocal count = 0\nlocal frame = 1\n\n-- The values of this frame that are not numbers: a string a line draws, a handler a click\n-- sends, whatever an element carries. They are held by index and the index spaces are\n-- shared, so an element's `text` and its `name` are two handles into the same array.\nlocal strings, stringCount = {}, 0\nlocal callbacks, callbackCount = {}, 0\nlocal runs, runCount = {}, 0\nlocal data, dataCount = {}, 0\n\n---@param index number\n---@return wonderland.Element\nfunction element.at(index)\n\treturn pointers[index]\nend\n\n---@param value string\n---@return number\nlocal function pushString(value)\n\tstringCount = stringCount + 1\n\tstrings[stringCount] = value\n\n\treturn stringCount\nend\n\n---@param value any\n---@return number # 0 for nothing, which is what a handler that was never set is\nlocal function pushCallback(value)\n\tif value == nil then\n\t\treturn 0\n\tend\n\n\tcallbackCount = callbackCount + 1\n\tcallbacks[callbackCount] = value\n\n\treturn callbackCount\nend\n\n--- One element, zeroed, which is what makes a slot handed out again look new: the array\n--- is reused, so nothing here is zero because it is new.\n---@return wonderland.Element\nlocal function make()\n\tcount = count + 1\n\n\tlocal block = bit.rshift(count - 1, SHIFT) + 1\n\n\tif blocks[block] == nil then\n\t\tblocks[block] = ffi.new(\"wl_element[?]\", BLOCK)\n\tend\n\n\tlocal made = blocks[block][bit.band(count - 1, MASK)]\n\n\tffi.fill(made, SIZE)\n\tmade.index = count\n\tmade.frame = frame\n\n\tpointers[count] = made\n\n\treturn made\nend\n\n--- An element lives for the frame it was made in. This is the check that says so: what it\n--- would otherwise read is the element the next frame has already put in its slot.\n---@param self wonderland.Element\nlocal function check(self)\n\tassert(self.frame == frame,\n\t\t\"This element was made in an earlier frame: an element is built by the view function and used in the repaint it was built for\")\nend\n\n--- Every repaint builds its tree again, so the frame starts empty: the elements are\n--- handed out from the first block again and the values of the last frame are let go.\nfunction element.beginFrame()\n\tframe = frame + 1\n\tcount = 0\n\n\tfor index = 1, stringCount do\n\t\tstrings[index] = nil\n\tend\n\n\tfor index = 1, callbackCount do\n\t\tcallbacks[index] = nil\n\tend\n\n\tfor index = 1, runCount do\n\t\truns[index] = nil\n\tend\n\n\tfor index = 1, dataCount do\n\t\tdata[index] = nil\n\tend\n\n\tstringCount, callbackCount, runCount, dataCount = 0, 0, 0, 0\nend\n\n--- How many elements the frame has made, for a test that wants to know what a screen\n--- costs.\n---@return number\nfunction element.count()\n\treturn count\nend\n\n-- ────────────────────────────────────────────────────────────────\n-- making one\n-- ────────────────────────────────────────────────────────────────\n\n--- There is one kind of element. A line of text is an element with a string on it and no\n--- children, so nothing in the engine has to know what sort of element it is looking at.\n---@return wonderland.Element\nfunction Element.new()\n\treturn make()\nend\n\n--- A box. It draws nothing until a style gives it something to draw, or a string gives\n--- it a line to draw.\n---@return wonderland.Element\nfunction element.div()\n\treturn make()\nend\n\n--- A line of text, sized by the font it is drawn in. It is an element like any other, so\n--- a string handed to `children` becomes one of these.\n---@param value string\n---@return wonderland.Element\nfunction element.text(value)\n\tlocal line = make()\n\tline.text = pushString(value)\n\n\treturn line\nend\n\n---@param value wonderland.IntoElement\n---@return wonderland.Element\nlocal function intoElement(value)\n\tlocal kind = type(value)\n\n\tif kind == \"string\" then\n\t\treturn element.text(value)\n\tend\n\n\t-- A type test rather than a message built for every child: this runs for every child\n\t-- of every element of every repaint, and a message that is only needed when the call\n\t-- fails is a message that is not built when it does not. What it is is checked by\n\t-- reading it: `wl_element` has the fields and nothing else does.\n\tif kind ~= \"cdata\" or not ffi.istype(\"wl_element\", value) then\n\t\terror(\"Cannot convert value to Element: \" .. tostring(value), 2)\n\tend\n\n\t---@cast value wonderland.Element\n\n\t-- Checked here rather than where it is read, because this is where an element of an\n\t-- older frame arrives: it would otherwise be linked into the tree and read as whatever\n\t-- the frame that owns the slot has put there.\n\tcheck(value)\n\n\treturn value\nend\n\n---@param value wonderland.IntoElement\n---@return wonderland.Element\nfunction element.from(value)\n\treturn intoElement(value)\nend\n\n---@param self wonderland.Element\n---@return wonderland.Element? # The child it should follow, if it has one\nlocal function lastChild(self)\n\tlocal index = self.childFirst\n\tif index == 0 then\n\t\treturn nil\n\tend\n\n\tlocal child = pointers[index]\n\twhile child.nextSibling ~= 0 do\n\t\tchild = pointers[child.nextSibling]\n\tend\n\n\treturn child\nend\n\n---@param parent wonderland.Element\n---@param after wonderland.Element?\n---@param child wonderland.Element\n---@return wonderland.Element # The child, so the next one knows what to follow\nlocal function link(parent, after, child)\n\tif after then\n\t\tafter.nextSibling = child.index\n\telse\n\t\tparent.childFirst = child.index\n\tend\n\n\tparent.childCount = parent.childCount + 1\n\n\treturn child\nend\n\n-- ────────────────────────────────────────────────────────────────\n-- the calls\n-- ────────────────────────────────────────────────────────────────\n\n--- What it looks like and how it lays out. One style can be shared by every element\n--- that should look the same, and the same style written twice is interned once.\n---@param value wonderland.StyleBuilder | wonderland.Style\n---@return wonderland.Element\nfunction methods:style(value)\n\tcheck(self)\n\tself.baseStyle = style.intern(value)\n\n\treturn self\nend\n\n--- Used instead of the base style while the pointer is over the element. Changing how\n--- the element looks costs a repaint but no upload, since the frame is compared before\n--- the gpu is given it. Text is measured before this is known, so a hover style that\n--- names a font does not re-measure the line.\n---@param value wonderland.StyleBuilder | wonderland.Style\n---@return wonderland.Element\nfunction methods:hover(value)\n\tcheck(self)\n\tself.hoverStyle = style.intern(value)\n\n\treturn self\nend\n\n--- Used instead of the base style while the pointer is held down on the element.\n---@param value wonderland.StyleBuilder | wonderland.Style\n---@return wonderland.Element\nfunction methods:active(value)\n\tcheck(self)\n\tself.activeStyle = style.intern(value)\n\n\treturn self\nend\n\n---@param value wonderland.StyleBuilder | wonderland.Style\n---@return wonderland.Element\nfunction methods:focus(value)\n\tcheck(self)\n\tself.focusStyle = style.intern(value)\n\n\treturn self\nend\n\n--- Adds children, in the order they are given. A string becomes a text element, and a\n--- table of elements is taken apart, so a list built in a loop can be passed as one.\n---@param ... wonderland.IntoElement | wonderland.IntoElement[]\n---@return wonderland.Element\nfunction methods:children(...)\n\tcheck(self)\n\n\tlocal after = lastChild(self)\n\n\tfor index = 1, select(\"#\", ...) do\n\t\tlocal value = select(index, ...)\n\n\t\tif type(value) == \"table\" then\n\t\t\tfor _, nested in ipairs(value) do\n\t\t\t\tafter = link(self, after, intoElement(nested))\n\t\t\tend\n\t\telse\n\t\t\tafter = link(self, after, intoElement(value))\n\t\tend\n\tend\n\n\treturn self\nend\n\n---@param name string\n---@return wonderland.Element\nfunction methods:named(name)\n\tcheck(self)\n\tself.name = pushString(name)\n\n\treturn self\nend\n\n--- Anything the element wants to carry: the message a click sends, a row's own data.\n---@param value any\n---@return wonderland.Element\nfunction methods:data(value)\n\tcheck(self)\n\tdataCount = dataCount + 1\n\tdata[dataCount] = value\n\tself.userdata = dataCount\n\n\treturn self\nend\n\n---@generic T\n---@param message T\n---@return wonderland.Element\nfunction methods:onMouseMove(message)\n\tcheck(self)\n\tself.onmousemove = pushCallback(message)\n\n\treturn self\nend\n\n---@generic T\n---@param message T\n---@return wonderland.Element\nfunction methods:onClick(message)\n\tcheck(self)\n\tself.onclick = pushCallback(message)\n\n\treturn self\nend\n\n---@generic T\n---@param cons fun(x: number, y: number, elementWidth: number, elementHeight: number): T\n---@return wonderland.Element\nfunction methods:onMouseDown(cons)\n\tcheck(self)\n\tself.onmousedown = pushCallback(cons)\n\n\treturn self\nend\n\n---@generic T\n---@param message T\n---@return wonderland.Element\nfunction methods:onMouseUp(message)\n\tcheck(self)\n\tself.onmouseup = pushCallback(message)\n\n\treturn self\nend\n\n---@generic T\n---@param message T\n---@return wonderland.Element\nfunction methods:onDoubleClick(message)\n\tcheck(self)\n\tself.ondblclick = pushCallback(message)\n\n\treturn self\nend\n\n--- What a box that scrolls does about being scrolled: the wheel over it, and its own bar being\n--- dragged.\n---\n--- The handler is asked with one of two things and answers with one message, which is what the app\n--- is told: `by` is how far a wheel asks the content to move, and `to` is where a bar dragged puts\n--- it, an absolute distance into the content. Which one is not nothing is what says which it was,\n--- and the app is what holds the offset, so it is the app that clamps it -- see `:scroll`.\n---\n---   div():scroll(self.offset)\n---       :onScroll(function(by, to)\n---           return { type = \"scroll\", by = to or (by or 0) * ROW_STEP }\n---       end)\n---\n--- A message given instead of a handler is the answer as it is, which is what a box with nothing to\n--- work out about it wants.\n---@param cons wonderland.ScrollHandler\n---@return wonderland.Element\nfunction methods:onScroll(cons)\n\tcheck(self)\n\tself.onscroll = pushCallback(cons)\n\n\treturn self\nend\n\n--- The button that is not the left one, which is what a menu is opened with: a context menu. The\n--- handler is asked with where in the box it was pressed, how large the box is, and which\n--- modifiers were held; a message given instead is the answer as it is.\n---\n--- A press with this button is not a click: what answers a click is not told about it, and it does\n--- not move the keyboard either -- a menu is opened where the pointer is, and the field that had\n--- the caret keeps it.\n---@param cons wonderland.ContextMenuHandler\n---@return wonderland.Element\nfunction methods:onContextMenu(cons)\n\tcheck(self)\n\tself.oncontextmenu = pushCallback(cons)\n\n\treturn self\nend\n\n--- Files dropped on the window, where they landed in this box: what a window that takes a track\n--- from a file manager is. The paths are the whole of what a platform hands over -- a window is\n--- given a list of files, not the bytes of them -- and what it does with them is the app's.\n---\n---   div():style(PANE):onDrop(function(paths)\n---       return { type = \"add\", paths = paths }\n---   end)\n---\n--- A drop goes to the innermost box under the pointer that asked for one, and a window with no box\n--- for it is one the app hears about itself: see `App:event`, which is handed the event with its\n--- paths when no element claimed it.\n---@param cons wonderland.DropHandler\n---@return wonderland.Element\nfunction methods:onDrop(cons)\n\tcheck(self)\n\tself.ondrop = pushCallback(cons)\n\n\treturn self\nend\n\n--- What this box draws itself, which is what a shape that is not a box is drawn with.\n---\n---   div():style(METER):canvas(function(canvas)\n---       canvas:rect(0, canvas.height - level, canvas.width, level, \"#3b82f6\")\n---   end)\n---\n--- The draw is handed a `wonderland.Canvas` -- a box as wide and as tall as the room this element's\n--- padding leaves, in whole pixels from its top left corner -- and what it draws goes into the frame\n--- in this element's place: over what is under the element, under what is over it, and cut by the\n--- pane the element is in. It is called once for every frame the screen is drawn in, so what it\n--- draws is whatever the app's state is at that moment. See `wonderland.Canvas` for the shapes\n--- there are, and `wonderland.plugin.Render:target` for a picture an app's shader drew, which is\n--- what a texture of its own is shown by.\n---@param draw fun(canvas: wonderland.Canvas)\n---@return wonderland.Element\nfunction methods:canvas(draw)\n\tcheck(self)\n\tself.oncanvas = pushCallback(draw)\n\n\treturn self\nend\n\n--- How far a box's content is scrolled up. It is what an app keeps, because it is state: the\n--- library clips the box to itself, moves the content by this much, and answers a click by what\n--- it lands on, and how far is up to the app -- which is what the wheel does, and where a scroll\n--- bar is drawn from. A box that scrolls and does not clip would draw its content over whatever\n--- is under it, so the two are one call.\n---@param offset number\n---@return wonderland.Element\nfunction methods:scroll(offset)\n\tcheck(self)\n\tself.flags = bit.bor(self.flags, element.SCROLLS)\n\tself.scrollOffset = offset or 0\n\n\treturn self\nend\n\n---@class wonderland.InputOpts<T>\n---@field name string\n---@field value string\n---@field multiline boolean? # Whether return should break the line instead of submitting it\n---@field maxLines number? # The most lines it holds: return does nothing at the end of them\n---@field grow boolean? # Whether the box is as tall as what is typed into it, up to `maxLines`\n---@field oninput fun(value: string): T\n---@field onsubmit fun(value: string): T\n\n--- Takes the keyboard, and sends what is typed. It is called `input` rather than `textInput`\n--- because a field of an element is read before a call is asked for, and it is the call an app\n--- makes. With `multiline` the field is a paragraph: return breaks the line rather than sending\n--- it, and control with return is what sends it.\n---\n--- A paragraph grows downwards as it fills up, which is a box that would have to be sized for\n--- everything it might hold: `maxLines` is how many lines it takes before it stops, and `grow`\n--- is the box following what is in it. A field of one line is unaffected by both.\n---@generic T\n---@param opts wonderland.InputOpts<T>\n---@return wonderland.Element\nfunction methods:input(opts)\n\tcheck(self)\n\tself.flags = bit.bor(self.flags, element.TEXT_INPUT)\n\n\tif opts.multiline then\n\t\tself.flags = bit.bor(self.flags, element.MULTILINE)\n\tend\n\n\tif opts.grow then\n\t\tself.flags = bit.bor(self.flags, element.GROWS)\n\tend\n\n\tself.maxLines = opts.maxLines or 0\n\tself.name = pushString(opts.name)\n\tself.inputValue = pushString(opts.value or \"\")\n\tself.oninput = pushCallback(opts.oninput)\n\tself.onsubmit = pushCallback(opts.onsubmit)\n\n\treturn self\nend\n\n---@class wonderland.SliderOpts<T>\n---@field value number # Where the slider is, as a number between the two ends of it\n---@field min number? # The value at the left end, nought by default\n---@field max number? # And the one at the right end, one by default\n---@field onchange fun(value: number): T\n\n--- A slider: the box reports where in it the pointer was pressed and dragged, in pixels, as the\n--- value between `min` and `max` that sits there. What is drawn -- a track, a filled part, a\n--- nub -- is the app's, as the look of a field is: an element here is a box and how it behaves.\n---\n---   local value = 0.4\n---\n---   div():style(track):slider({ value = value, onchange = function(now) return { type = \"volume\", value = now } end })\n---     :children({\n---       div():style(fill):wrel(value),\n---       div():style(nub):thumb(),\n---     })\n---\n--- The nub is the app's too, and is a child of the slider marked with `:thumb()`: the layout puts\n--- it where the value is, which is the only part of a slider an app cannot lay out itself, since\n--- it cannot know how wide the box the slider was given came out.\n---@generic T\n---@param opts wonderland.SliderOpts<T>\n---@return wonderland.Element\nfunction methods:slider(opts)\n\tcheck(self)\n\tself.flags = bit.bor(self.flags, element.SLIDE)\n\tself.sliderValue = opts.value\n\tself.min, self.max = opts.min or 0, opts.max or 1\n\tself.onchange = pushCallback(opts.onchange)\n\n\treturn self\nend\n\n--- Marks an element as a slider's nub, which is where the slider puts it: across the box less the\n--- nub itself, so the nub's ends are the ends of the slider. Anywhere but inside a slider it is a\n--- flag nothing reads, and the element stays where the layout stacked it.\n---@return wonderland.Element\nfunction methods:thumb()\n\tcheck(self)\n\tself.flags = bit.bor(self.flags, element.THUMB)\n\n\treturn self\nend\n\n-- A style is built the same way, so sty() is reached through here rather than making\n-- every caller require two modules.\nelement.sty = style.new\n\n-- ────────────────────────────────────────────────────────────────\n-- what the frame's values are, by handle\n-- ────────────────────────────────────────────────────────────────\n\n-- The arrays themselves, so a pass over a screen reads a handle where it wants the value\n-- and pays no call for it. They are the same tables every frame: what changes is how far\n-- into them the frame has written.\nelement.strings, element.callbacks, element.runs, element.data, element.pointers = strings, callbacks, runs, data,\n\tpointers\n\n--- A measured line, kept for this frame, and the handle an element holds of it. A run is\n--- interned by the font that measured it, so measuring the same line again is a lookup.\n---@param run wonderland.font.Run\n---@return number\nfunction element.pushRun(run)\n\trunCount = runCount + 1\n\truns[runCount] = run\n\n\treturn runCount\nend\n\n--- Says what an element draws, for a tree measured by hand rather than by the text\n--- plugin: a test laying a line out without a font.\n---@param self wonderland.Element\n---@param run wonderland.font.Run\nfunction element.setRun(self, run)\n\tcheck(self)\n\tself.run = element.pushRun(run)\nend\n\n--- The measured line an element draws, if it draws one.\n---@param self wonderland.Element\n---@return wonderland.font.Run?\nfunction element.runOf(self)\n\treturn self.run ~= 0 and runs[self.run] or nil\nend\n\n--- What the pointer is doing to an element, which is what the layout picks a style by.\n---@param self wonderland.Element\n---@param on boolean\nfunction element.hovering(self, on)\n\tself.flags = on and bit.bor(self.flags, element.HOVERED)\n\t\tor bit.band(self.flags, bit.bnot(element.HOVERED))\nend\n\n---@param self wonderland.Element\n---@param on boolean\nfunction element.pressing(self, on)\n\tself.flags = on and bit.bor(self.flags, element.PRESSED)\n\t\tor bit.band(self.flags, bit.bnot(element.PRESSED))\nend\n\n--- The line an element draws, if it draws one.\n---@param self wonderland.Element\n---@return string?\nfunction element.textOf(self)\n\treturn self.text ~= 0 and strings[self.text] or nil\nend\n\n--- The element's own name, if it has one.\n---@param self wonderland.Element\n---@return string?\nfunction element.nameOf(self)\n\treturn self.name ~= 0 and strings[self.name] or nil\nend\n\n--- What has been typed into an element that takes typing.\n---@param self wonderland.Element\n---@return string\nfunction element.inputOf(self)\n\treturn self.inputValue ~= 0 and strings[self.inputValue] or \"\"\nend\n\n--- Whatever the app carries on an element.\n---@param self wonderland.Element\n---@return any\nfunction element.dataOf(self)\n\treturn self.userdata ~= 0 and data[self.userdata] or nil\nend\n\n-- Which is what makes an element answer its own calls while a field of it is still read\n-- as the number it holds.\nffi.metatype(\"wl_element\", methods)\n\nreturn element\n", "@wonderland.element")(...) end
package.preload["hood-vk.texture"] = function(...) return load("local vk = require(\"vkapi\")\n\nlocal vkConvert = require(\"hood-vk.convert\")\nlocal memory = require(\"hood-vk.memory\")\n\nlocal VKTextureView = require(\"hood-vk.texture_view\")\n\n---@class hood-vk.Texture\n---@field handle vk.ffi.Image\n---@field memory vk.ffi.DeviceMemory?\n---@field format vk.Format\n---@field width number?\n---@field height number?\n---@field viewType vk.ImageViewType\n---@field isDepth boolean?\n---@field usage vk.ImageUsageFlagBits\n---@field isSwapchain boolean?\n---@field swapchain hood-vk.Swapchain?\n---@field swapchainImageIdx integer? 0-based index into the swapchain images, set when isSwapchain is true\n---@field private device hood-vk.Device\nlocal VKTexture = {}\nVKTexture.__index = VKTexture\n\n--- TODO: Deduplicate this code from the pipeline\n---@param format hood.TextureFormat\nlocal function isDepthFormat(format)\n\treturn format == \"depth16unorm\"\n\t\tor format == \"depth24plus\"\n\t\tor format == \"depth32float\"\nend\n\n---@param extents hood.TextureExtents\nlocal function viewTypeFromExtents(extents)\n\tif extents.dim == \"3d\" then\n\t\treturn vk.ImageViewType.TYPE_3D\n\telseif extents.dim == \"2d\" and (extents.count and extents.count > 1) then\n\t\treturn vk.ImageViewType.TYPE_2D_ARRAY\n\telseif extents.dim == \"2d\" then\n\t\treturn vk.ImageViewType.TYPE_2D\n\telseif extents.dim == \"1d\" and (extents.count and extents.count > 1) then\n\t\treturn vk.ImageViewType.TYPE_1D_ARRAY\n\telseif extents.dim == \"1d\" then\n\t\treturn vk.ImageViewType.TYPE_1D\n\telse\n\t\terror(\"Unsupported texture dimension: \" .. tostring(extents.dim))\n\tend\nend\n\n---@param device hood-vk.Device\n---@param descriptor hood.TextureDescriptor\nfunction VKTexture.new(device, descriptor)\n\tlocal samples = vkConvert.sampleCount[descriptor.sampleCount or 1]\n\tif not samples then\n\t\terror(\"Unsupported sample count: \" .. tostring(descriptor.sampleCount))\n\tend\n\n\tlocal layers = descriptor.extents.dim ~= \"3d\" and descriptor.extents.count or 1\n\tlocal isDepth = isDepthFormat(descriptor.format)\n\n\t---@type vk.ImageUsageFlagBits\n\tlocal vkUsage = 0\n\tfor _, usage in ipairs(descriptor.usages) do\n\t\tlocal flag = vkConvert.textureUsage[usage]\n\t\tif usage == \"RENDER_ATTACHMENT\" and isDepth then\n\t\t\tflag = vk.ImageUsageFlagBits.DEPTH_STENCIL_ATTACHMENT\n\t\tend\n\n\t\tvkUsage = bit.bor(vkUsage, flag)\n\tend\n\n\tassert(descriptor.format, \"Texture format must be specified\")\n\tlocal format = vkConvert.textureFormat[descriptor.format]\n\n\tlocal handle = device.handle:createImage({\n\t\timageType = vkConvert.textureType[descriptor.extents.dim],\n\t\tformat = format,\n\t\textent = {\n\t\t\twidth = descriptor.extents.width,\n\t\t\theight = descriptor.extents.height,\n\t\t\tdepth = descriptor.extents.depth or 1,\n\t\t},\n\t\tmipLevels = descriptor.mipLevelCount or 1,\n\t\tarrayLayers = layers,\n\t\tsamples = samples,\n\t\ttiling = vk.ImageTiling.OPTIMAL,\n\t\tusage = vkUsage,\n\t\tsharingMode = vk.SharingMode.EXCLUSIVE,\n\t\tinitialLayout = vk.ImageLayout.UNDEFINED,\n\t})\n\n\t-- A texture is device-local memory, and the types beside that one are the same memory asked\n\t-- for without it: an image the first heap has no room for lands in the next one rather than\n\t-- nowhere.\n\tlocal requirements = device.handle:getImageMemoryRequirements(handle)\n\tlocal imageMemory = memory.allocate(device, requirements, vk.MemoryPropertyFlagBits.DEVICE_LOCAL, 0, \"image\")\n\n\tdevice.handle:bindImageMemory(handle, imageMemory, 0)\n\n\treturn setmetatable({\n\t\tdevice = device,\n\t\thandle = handle,\n\t\tmemory = imageMemory,\n\t\tformat = format,\n\t\twidth = descriptor.extents.width,\n\t\theight = descriptor.extents.height,\n\t\tisDepth = isDepth,\n\t\tviewType = viewTypeFromExtents(descriptor.extents),\n\t\tusage = vkUsage,\n\t}, VKTexture)\nend\n\n---@param device hood-vk.Device\n---@param swapchain hood-vk.Swapchain\n---@param handle vk.ffi.Image\n---@param format vk.Format\n---@param width number\n---@param height number\n---@param swapchainImageIdx integer 0-based index into the swapchain's images\nfunction VKTexture.fromSwapchainImg(device, swapchain, handle, format, width, height, swapchainImageIdx)\n\treturn setmetatable({\n\t\tdevice = device,\n\t\tswapchain = swapchain,\n\t\thandle = handle,\n\t\tformat = format,\n\t\twidth = width,\n\t\theight = height,\n\t\tisSwapchain = true,\n\t\tswapchainImageIdx = swapchainImageIdx,\n\t\tviewType = vk.ImageViewType.TYPE_2D,\n\t}, VKTexture)\nend\n\nfunction VKTexture:destroy()\n\tif self.isSwapchain then return end\n\tself.device.handle:destroyImage(self.handle)\n\tif self.memory then\n\t\tself.device.handle:freeMemory(self.memory)\n\tend\nend\n\n---@param descriptor hood.TextureViewDescriptor?\nfunction VKTexture:createView(descriptor)\n\t-- For swapchain textures, lazily create and cache a view per swapchain image.\n\t-- The swapchain already has pre-created VkImageView handles, so we wrap one\n\t-- without calling createImageView. Subsequent frames reuse the cached view,\n\t-- eliminating the per-frame createImageView overhead.\n\tif self.isSwapchain and self.swapchain then\n\t\tself._viewCache = self._viewCache or {}\n\t\tlocal idx = self.swapchainImageIdx --[[@as integer]]\n\t\tlocal cached = self._viewCache[idx]\n\t\tif not cached then\n\t\t\tlocal rawHandle = self.swapchain.imageViews[idx + 1]\n\t\t\t-- descriptor is ignored for swapchain views (uses pre-created config)\n\t\t\tcached = VKTextureView.fromHandle(self.device, self, rawHandle, nil)\n\t\t\tself._viewCache[idx] = cached\n\t\tend\n\t\treturn cached\n\tend\n\treturn VKTextureView.new(self.device, self, descriptor or {})\nend\n\nreturn VKTexture\n", "@hood-vk.texture")(...) end
package.preload["wonderland.layout"] = function(...) return load("-- Solving a screen's geometry.\n--\n-- Every repaint lays the screen out again, so the nodes it is laid out into live in one\n-- array that is filled in place rather than a table per node per repaint. The array is\n-- grown to the largest screen seen and then reused, which is what makes a repaint cost\n-- its arithmetic and nothing else.\n--\n-- Two arrays, in step:\n--\n--   nodes         one struct per element, in the order the elements were walked\n--   childIndices  each node's children, one contiguous run per node\n--\n-- The second exists because a tree written into one array cannot have its children next\n-- to it: a child's own subtree sits between it and its next sibling.\nlocal bit = require(\"bit\")\nlocal ffi = require(\"ffi\")\nlocal style = require(\"wonderland.style\")\nlocal wonderlandElement = require(\"wonderland.element\")\n\n-- The element arena and the style arena are what the solver reads, so their arrays are\n-- taken once: what the frame has written into them changes, which of them it is does not.\nlocal pointers = wonderlandElement.pointers\nlocal runs = wonderlandElement.runs\nlocal HOVERED, PRESSED = wonderlandElement.HOVERED, wonderlandElement.PRESSED\nlocal ABS, REL, AUTO = style.ABS, style.REL, style.AUTO\nlocal PRESENT = style.PRESENT\nlocal SCROLLS = wonderlandElement.SCROLLS\nlocal SLIDE, THUMB = wonderlandElement.SLIDE, wonderlandElement.THUMB\nlocal GROWS = wonderlandElement.GROWS\nlocal WIDTH, HEIGHT = PRESENT.width, PRESENT.height\n\n-- Which style array the nodes are read out of. It is replaced when the arena grows, and\n-- the arena only grows while a screen is being *built* from a tree -- never while the\n-- nodes are made from one -- so it is taken again at the start of each frame.\nlocal styleArena = style.arena\n\nffi.cdef [[\n\t// Under ffi.C because LuaJIT only knows the symbols it has been told about: this is\n\t// how a whole frame is compared at once.\n\tint memcmp(const void *a, const void *b, size_t n);\n\n\ttypedef struct {\n\t\t// The style this node was made with, in the same order and the same types as `wl_style`,\n\t\t// so that the whole of it is one ffi.copy: see the check below, which refuses to load if\n\t\t// the two ever disagree. Every field of a node being written one at a time is what made\n\t\t// the build long, and a build the recorder gives up on runs in the interpreter.\n\t\t//\n\t\t// A share of the space is a fraction, and a fraction in a float32 is not the fraction:\n\t\t// 0.7 becomes 0.69999999, which is 1.4e-5 of a 1200 pixel screen and enough to round a\n\t\t// position the wrong way. So the numbers the solver works in are doubles.\n\t\tdouble wantWidth, wantHeight;\n\t\tdouble bgR, bgG, bgB, bgA;     // what it is painted with, if anything\n\t\tdouble borderR, borderG, borderB, borderA;\n\t\tdouble u0, v0, u1, v1;         // and the part of its texture to use\n\t\tint32_t gap, zIndex;\n\t\tint32_t paddingTop, paddingRight, paddingBottom, paddingLeft;\n\t\tint32_t marginTop, marginRight, marginBottom, marginLeft;\n\t\tint32_t top, left, right, bottom;\n\t\tint32_t borderTop, borderRight, borderBottom, borderLeft;\n\t\tuint32_t fgR, fgG, fgB, fgA;   // text colour as bytes, 0 for nothing\n\t\tuint32_t texture, font;        // the texture it paints, and the font it is drawn in\n\t\tdouble bright;                 // a multiplier on the colours, 1.0 for not one\n\t\tdouble radius;                 // how round its corners are, in pixels, 0 for square\n\t\tint32_t shadowX, shadowY;      // where its shadow sits, how far it fades out, and\n\t\tint32_t shadowBlur;\n\t\tuint8_t shadowR, shadowG, shadowB, shadowA;  // what colour it is, 0 alpha for none\n\t\tuint32_t styleFlags;           // and which of that style's fields were set\n\t\tuint8_t widthUnit, heightUnit, direction, align, justify, position, visible, paint;\n\n\t\t// Text inside it is drawn in the family, at the size, at the weight and on the slant the\n\t\t// nearest element above it that named them says: nought is one the element above says.\n\t\tuint32_t fontFamily;\n\t\tdouble fontSize;\n\t\tuint32_t fontWeight;\n\t\tuint8_t fontItalic, ellipsis;\n\n\t\t// -- nothing above this line is the node's own: it is the style it was built from.\n\n\t\tuint32_t style;                // the slot it was styled with\n\t\tuint32_t scrolls;              // whether it clips its content to its own box\n\t\tdouble scroll;                 // and how far its content is moved up\n\t\tuint32_t run;                  // which run of the screen's runs to draw\n\t\tuint32_t runId;                // and which measured line that was\n\t\tuint32_t element;              // the element this came from, 1 based, 0 for none\n\t\tuint32_t thumb;                // whether it is the nub of the slider above it\n\n\t\t// how it came out\n\t\tdouble x, y;\n\t\tdouble width, height;\n\t\tuint32_t firstChild, childCount;\n\t} wl_node;\n]]\n\n-- The build is one long function by nature: every field of every node is written from the style\n-- it was made with, and that is what makes a repaint a copy of a struct rather than a walk of a\n-- tree of tables. It is long enough that the recorder gives up on it -- \"trace too long\" -- and a\n-- loop it gives up on is a loop that runs in the interpreter, which measured ten times slower\n-- than the same work compiled. So it is allowed to record more before it gives up, and this is\n-- the only thing in the library that asks for that. The proper fix is a shorter function -- the\n-- style of a node copied into it with one ffi.copy rather than a write per field -- and until\n-- then this is the number that keeps the loop compiled.\njit.opt.start(\"maxrecord=12000\")\n\n-- What a scroll bar is told: how far there is to scroll, and how it is drawn. It lives beside the\n-- nodes rather than in them because only a box that scrolls has one, and every field of a node is\n-- written for every node of every frame -- which is what makes the build one long function, and a\n-- function the recorder gives up on is a build that runs in the interpreter, ten times slower.\nffi.cdef [[\n\ttypedef struct {\n\t\tdouble max;                    // how far the content goes past what the box shows\n\t\tint32_t width, least;          // the strip it takes, and the least a thumb of it is\n\t\tdouble r, g, b, a;\n\t} wl_bar;\n]]\n\n-- The two structs have to agree, field for field and type for type, for as many bytes as a node\n-- copies: a field added to one and not the other would have every node reading a style's worth of\n-- memory that does not line up, which shows up as a screen that draws nonsense. Checked once, at\n-- load, so it is the library that refuses rather than a frame that comes out wrong.\nfor _, field in ipairs({ \"wantWidth\", \"wantHeight\", \"bgR\", \"borderR\", \"u0\", \"gap\", \"zIndex\", \"paddingTop\",\n\t\"marginTop\", \"top\", \"left\", \"borderTop\", \"fgR\", \"texture\", \"font\", \"bright\", \"radius\", \"shadowX\",\n\t\"shadowBlur\", \"shadowA\", \"widthUnit\", \"paint\", \"fontFamily\", \"fontSize\", \"fontWeight\", \"fontItalic\",\n\t\"ellipsis\" }) do\n\tassert(ffi.offsetof(\"wl_node\", field) == ffi.offsetof(\"wl_style\", field),\n\t\t\"wl_node and wl_style disagree about \" .. field .. \": the build copies one into the other\")\nend\n\nassert(ffi.offsetof(\"wl_node\", \"styleFlags\") == ffi.offsetof(\"wl_style\", \"flags\"),\n\t\"wl_node and wl_style disagree about their flags\")\n\n--- How many bytes of a style a node takes: all of it but the scroll bar's, which a box that\n--- scrolls keeps beside its nodes.\nlocal STYLE_COPY = ffi.offsetof(\"wl_style\", \"barWidth\")\n\nlocal nodeArray = ffi.typeof(\"wl_node[?]\")\nlocal barArray = ffi.typeof(\"wl_bar[?]\")\nlocal NODE_SIZE = assert(ffi.sizeof(\"wl_node\"))\n\n--- A position is put on a whole pixel. Glyph quads are exactly as wide as their ink, so\n--- one that starts halfway across a pixel loses its last column, and a background edge\n--- that lands between pixels is uneven. Sizes are left alone: they are shares of the\n--- space, and rounding them would take the rounding error out of the layout.\n---@param value number\n---@return number\nlocal function snap(value)\n\treturn math.floor(value + 0.5)\nend\n\nlocal layout = {}\n\n--- One node of a laid out screen, as the struct it is. The language server cannot see\n--- an ffi.cdef, so the fields are spelled out here: it is the only way to get them checked.\n---@class wonderland.Node: ffi.cdata*\n---@field wantWidth number\n---@field wantHeight number\n---@field widthUnit number\n---@field heightUnit number\n---@field gap number\n---@field paddingTop number\n---@field paddingRight number\n---@field paddingBottom number\n---@field paddingLeft number\n---@field marginTop number\n---@field marginRight number\n---@field marginBottom number\n---@field marginLeft number\n---@field top number\n---@field left number\n---@field right number\n---@field bottom number\n---@field zIndex number\n---@field borderTop number\n---@field borderRight number\n---@field borderBottom number\n---@field borderLeft number\n---@field bgR number\n---@field bgG number\n---@field bgB number\n---@field bgA number\n---@field borderR number\n---@field borderG number\n---@field borderB number\n---@field borderA number\n---@field texture number\n---@field u0 number\n---@field v0 number\n---@field u1 number\n---@field v1 number\n---@field style number\n---@field styleFlags number\n---@field bright number\n---@field radius number\n---@field shadowX number\n---@field shadowY number\n---@field shadowBlur number\n---@field shadowR number\n---@field shadowG number\n---@field shadowB number\n---@field shadowA number\n---@field scrolls number\n---@field scroll number\n---@field fgR number\n---@field fgG number\n---@field fgB number\n---@field fgA number\n---@field font number\n---@field run number\n---@field runId number\n---@field element number\n---@field thumb number # Whether it is the nub of the slider above it\n---@field x number\n---@field y number\n---@field width number # Solved\n---@field height number # Solved\n---@field firstChild number\n---@field childCount number\n---@field direction number\n---@field align number\n---@field justify number\n---@field position number\n---@field visible number\n---@field paint number\n---@field fontFamily number\n---@field fontSize number\n---@field fontWeight number\n---@field fontItalic number\n---@field ellipsis number\n\n--- What a screen is laid out against. A real window has more than this and a headless\n--- screen has less; both are laid out by their size, the redraw flag is how the ui asks for\n--- another frame, and the cursor is there to be pointed with when there is one.\n---@alias wonderland.RenderWindow { width: number, height: number, shouldRedraw: boolean?, frameAsked: boolean?, setCursor: (fun(self: any, shape: string))?, resetCursor: (fun(self: any))? }\n\n---@class wonderland.layout\n---@field new fun(capacity: number?): wonderland.Layout.Screen\n---@field screen fun(element: wonderland.Element, width: number, height: number): wonderland.Layout.Screen\n\n---@class wonderland.Layout.Screen\n---@field nodes wonderland.Node[] # The node array itself\n---@field childIndices ffi.cdata* # uint32_t, one run per node\n---@field bars ffi.cdata* # `wl_bar` per node, for the ones that scroll\n---@field count number # Nodes in use\n---@field childCount number # Child indices in use\n---@field capacity number\n---@field runs wonderland.font.Run[] # And the measured line each text node draws\n---@field changed boolean # Whether this frame is different from the one the gpu has\n---@field private last ffi.cdata* # The frame the gpu was last given\n---@field private lastCount number\n---@field private lastChildren number\n---@field root number # 1 based index of the root\nlocal Screen = {}\nScreen.__index = Screen\n\n--- A screen's storage, kept between repaints and grown when a bigger screen arrives.\n---@param capacity number? # Roughly how many nodes to start with\n---@return wonderland.Layout.Screen\nfunction layout.new(capacity)\n\tcapacity = capacity or 256\n\n\treturn setmetatable({\n\t\tnodes = nodeArray(capacity),\n\t\tchildIndices = ffi.new(\"uint32_t[?]\", capacity),\n\t\tbars = barArray(capacity),\n\t\tbarNone = ffi.new(\"wl_bar\"),\n\t\tlast = nodeArray(capacity),\n\t\tcapacity = capacity,\n\t\tcount = 0,\n\t\tchildCount = 0,\n\t\tlastCount = 0,\n\t\tlastChildren = 0,\n\t\tchanged = true,\n\t\truns = {},\n\t\troot = 0,\n\t}, Screen)\nend\n\n---@param nodes number\nfunction Screen:reserve(nodes)\n\tif nodes <= self.capacity then\n\t\treturn\n\tend\n\n\tlocal capacity = self.capacity\n\twhile capacity < nodes do\n\t\tcapacity = capacity * 2\n\tend\n\n\t-- Growing happens while a screen is being built, so what is already in the arrays has\n\t-- to come along, and the runs of child indices move with their nodes.\n\tlocal nodes_ = nodeArray(capacity)\n\tlocal childIndices = ffi.new(\"uint32_t[?]\", capacity)\n\tlocal bars = barArray(capacity)\n\n\tif self.count > 0 then\n\t\tffi.copy(nodes_, self.nodes, self.count * NODE_SIZE)\n\tend\n\n\tif self.childCount > 0 then\n\t\tffi.copy(childIndices, self.childIndices, self.childCount * ffi.sizeof(\"uint32_t\"))\n\tend\n\n\tif self.count > 0 and self.bars ~= nil then\n\t\tffi.copy(bars, self.bars, self.count * ffi.sizeof(\"wl_bar\"))\n\tend\n\n\tself.nodes = nodes_\n\tself.childIndices = childIndices\n\tself.bars = bars\n\tself.last = nodeArray(capacity)\n\tself.lastCount = 0\n\tself.capacity = capacity\nend\n\n-- The fields of a style that stands in for another one: what it names is written over what the\n-- style it stands in for said. It is a call of its own because it is the rare path -- an element\n-- the pointer is over -- and the common one is a copy of one style and no more.\n---@param given wonderland.StyleSlot\n---@param node wonderland.Node\nlocal function applyOver(given, node)\n\tlocal present = given.flags\n\n\tif bit.band(present, PRESENT.width) ~= 0 then\n\t\tnode.widthUnit, node.wantWidth = given.widthUnit, given.wantWidth\n\tend\n\n\tif bit.band(present, PRESENT.height) ~= 0 then\n\t\tnode.heightUnit, node.wantHeight = given.heightUnit, given.wantHeight\n\tend\n\n\tif bit.band(present, PRESENT.gap) ~= 0 then\n\t\tnode.gap = given.gap\n\tend\n\n\tif bit.band(present, PRESENT.z) ~= 0 then\n\t\tnode.zIndex = given.zIndex\n\tend\n\n\tif bit.band(present, PRESENT.direction) ~= 0 then\n\t\tnode.direction = given.direction\n\tend\n\n\tif bit.band(present, PRESENT.align) ~= 0 then\n\t\tnode.align = given.align\n\tend\n\n\tif bit.band(present, PRESENT.justify) ~= 0 then\n\t\tnode.justify = given.justify\n\tend\n\n\tif bit.band(present, PRESENT.position) ~= 0 then\n\t\tnode.position = given.position\n\tend\n\n\tif bit.band(present, PRESENT.visible) ~= 0 then\n\t\tnode.visible = given.visible\n\tend\n\n\tif bit.band(present, PRESENT.padding) ~= 0 then\n\t\tnode.paddingTop, node.paddingRight = given.paddingTop, given.paddingRight\n\t\tnode.paddingBottom, node.paddingLeft = given.paddingBottom, given.paddingLeft\n\tend\n\n\tif bit.band(present, PRESENT.margin) ~= 0 then\n\t\tnode.marginTop, node.marginRight = given.marginTop, given.marginRight\n\t\tnode.marginBottom, node.marginLeft = given.marginBottom, given.marginLeft\n\tend\n\n\tif bit.band(present, PRESENT.offset) ~= 0 then\n\t\tnode.top, node.left, node.right, node.bottom = given.top, given.left, given.right, given.bottom\n\tend\n\n\tif bit.band(present, PRESENT.border) ~= 0 then\n\t\tnode.borderTop, node.borderRight = given.borderTop, given.borderRight\n\t\tnode.borderBottom, node.borderLeft = given.borderBottom, given.borderLeft\n\t\tnode.borderR, node.borderG = given.borderR, given.borderG\n\t\tnode.borderB, node.borderA = given.borderB, given.borderA\n\tend\n\n\tif bit.band(present, PRESENT.bg) ~= 0 then\n\t\tnode.bgR, node.bgG, node.bgB, node.bgA = given.bgR, given.bgG, given.bgB, given.bgA\n\tend\n\n\tif bit.band(present, PRESENT.fg) ~= 0 then\n\t\tnode.fgR, node.fgG, node.fgB, node.fgA = given.fgR, given.fgG, given.fgB, given.fgA\n\tend\n\n\tif bit.band(present, PRESENT.texture) ~= 0 then\n\t\tnode.texture = given.texture\n\t\tnode.u0, node.v0, node.u1, node.v1 = given.u0, given.v0, given.u1, given.v1\n\tend\n\n\tif bit.band(present, PRESENT.bright) ~= 0 then\n\t\tnode.bright = given.bright\n\tend\n\n\tif bit.band(present, PRESENT.radius) ~= 0 then\n\t\tnode.radius = given.radius\n\tend\n\n\tif bit.band(present, PRESENT.shadow) ~= 0 then\n\t\tnode.shadowX, node.shadowY, node.shadowBlur = given.shadowX, given.shadowY, given.shadowBlur\n\t\tnode.shadowR, node.shadowG = given.shadowR, given.shadowG\n\t\tnode.shadowB, node.shadowA = given.shadowB, given.shadowA\n\tend\nend\n\n--- What a node is drawn with, lit differently: a multiplier over the colours it already has, so\n--- a hover style can say \"brighter\" instead of naming a second set of colours that has to be kept\n--- in step with the first. Transparency is not a colour and is left alone.\n---@param node wonderland.Node\nlocal function lighten(node)\n\tlocal bright = node.bright\n\n\tnode.bgR, node.bgG, node.bgB = math.min(1.0, node.bgR * bright), math.min(1.0, node.bgG * bright),\n\t\tmath.min(1.0, node.bgB * bright)\n\tnode.borderR, node.borderG = math.min(1.0, node.borderR * bright), math.min(1.0, node.borderG * bright)\n\tnode.borderB = math.min(1.0, node.borderB * bright)\n\n\t-- A text colour is bytes, so it is rounded to one and stops at white.\n\tnode.fgR = math.min(255, math.floor(node.fgR * bright + 0.5))\n\tnode.fgG = math.min(255, math.floor(node.fgG * bright + 0.5))\n\tnode.fgB = math.min(255, math.floor(node.fgB * bright + 0.5))\nend\n\n---@param element wonderland.Element\n---@return number # The node the element became\nfunction Screen:add(element)\n\tself.count = self.count + 1\n\tself:reserve(self.count)\n\n\t-- For the frame, not for the node: the arena is only replaced while a tree is being\n\t-- built, and this runs after that.\n\tlocal node = self.nodes[self.count - 1]\n\n\t-- What it is drawn and laid out with. A style is a slot in the arena, so \"which style\n\t-- does the pointer make this\" is two numbers the element holds, and what that style\n\t-- says is one struct the layout reads: no table lookups by name, and no comparing\n\t-- strings to find out which way a box stacks.\n\tlocal flags = element.flags\n\tlocal over = 0\n\n\tif bit.band(flags, PRESSED) ~= 0 and element.activeStyle ~= 0 then\n\t\tover = element.activeStyle\n\telseif bit.band(flags, HOVERED) ~= 0 and element.hoverStyle ~= 0 then\n\t\tover = element.hoverStyle\n\tend\n\n\tlocal given = styleArena[element.baseStyle]\n\n\t-- The arrays are reused, so nothing is zero because it is new: every field is written\n\t-- from the style whether the style named it or not, which is also why a style that\n\t-- names nothing is a slot like any other -- the layout has one path through here.\n\t-- The whole style in one copy: the node's first fields are laid out as a style is, so this is\n\t-- the work of thirty writes in one call, and the reason the build is short enough for the\n\t-- recorder. Everything below is the node's own.\n\tffi.copy(node, given, STYLE_COPY)\n\n\tnode.element = element.index\n\tnode.thumb = bit.band(flags, THUMB) ~= 0 and 1 or 0\n\tnode.style = over ~= 0 and over or element.baseStyle\n\tnode.x, node.y, node.width, node.height = 0, 0, 0, 0\n\tnode.firstChild, node.childCount = 0, 0\n\tnode.run, node.runId = 0, 0\n\n\t-- A box that scrolls shows only what is inside it: how far its content is moved up is the\n\t-- app's, and snapped to a whole pixel so the text in it stays crisp.\n\tnode.scrolls = bit.band(element.flags, SCROLLS) ~= 0 and 1 or 0\n\tnode.scroll = snap(element.scrollOffset)\n\n\t-- A bar is taken out of the content rather than drawn over it, so nothing is under the strip it\n\t-- is in. A box that does not scroll has no bar, whatever its style says -- and no bar is\n\t-- written for it either, since the nodes the frame is not longer than keep theirs.\n\tif node.scrolls ~= 0 then\n\t\tlocal bar = self.bars[self.count - 1]\n\n\t\tbar.max = 0\n\t\tbar.width, bar.least = given.barWidth, given.barLeast\n\t\tbar.r, bar.g, bar.b, bar.a = given.barR, given.barG, given.barB, given.barA\n\n\t\tif bar.width > 0 then\n\t\t\tnode.paddingRight = node.paddingRight + bar.width\n\t\tend\n\tend\n\n\t-- A style kept for the pointer stands in for the base one and says what it names: what it\n\t-- does not name is what the base style says, so a hover style that only names a background\n\t-- leaves the size, the padding and the direction alone. It is written after the base style\n\t-- rather than before it, because what it says is what wins.\n\tlocal worn = over ~= 0 and styleArena[over]\n\n\tif worn then\n\t\tnode.styleFlags = bit.bor(node.styleFlags, bit.band(worn.flags, 0xffff))\n\t\tapplyOver(worn, node)\n\tend\n\n\t-- Brightness is the one thing that is not a field of the frame's own: it is applied to the\n\t-- colours the node ends up with, whichever style said it, and the children inherit the\n\t-- result because they are built from the node after this.\n\tif node.bright ~= 1.0 then\n\t\tlighten(node)\n\tend\n\n\treturn self.count\nend\n\n--- A line of text is the size of the line it measured into, unless the style named a size\n--- of its own, and the run is kept for the quad pass to draw the glyphs of. Kept out of\n--- `add` because only a text element reaches it, and because a trace of a function this\n--- long is one the recorder gives up on -- and a trace it gives up on is a loop that runs\n--- a reference allocation at a time.\n---@param screen wonderland.Layout.Screen\n---@param node wonderland.Node\n---@param index number\n---@param run wonderland.font.Run\nlocal function sizeToRun(screen, node, index, run)\n\tscreen.runs[index] = run\n\tnode.run, node.runId = index, run.id\n\n\tif bit.band(node.styleFlags, WIDTH) == 0 then\n\t\tnode.widthUnit, node.wantWidth = ABS, run.width\n\tend\n\n\tif bit.band(node.styleFlags, HEIGHT) == 0 then\n\t\tnode.heightUnit, node.wantHeight = ABS, run.height\n\tend\nend\n\n--- Builds the nodes for an element tree, depth first, and the runs of child indices that\n--- go with them.\n---@param element wonderland.Element\n---@param fgR number? # What the elements above this one draw text in\n---@param fgG number?\n---@param fgB number?\n---@param fgA number?\n---@param font number? # And the font they draw it with\n---@return number # The node the element became\nfunction Screen:build(element, fgR, fgG, fgB, fgA, font)\n\tlocal node = self:add(element)\n\tlocal entry = self.nodes[node - 1]\n\n\t-- Text properties are inherited; everything else is not, because a background belongs\n\t-- to the box that has it rather than to everything inside it.\n\tif entry.fgA == 0 then\n\t\tentry.fgR, entry.fgG, entry.fgB, entry.fgA = fgR or 0, fgG or 0, fgB or 0, fgA or 0\n\tend\n\n\t-- The font a line is drawn in is the one it was measured in. It is resolved from the\n\t-- base style rather than the one the pointer picked, because that is the font the run\n\t-- was measured with: a style that changes it would be drawing glyphs baked for\n\t-- another one.\n\tlocal base = styleArena[element.baseStyle]\n\tlocal named = base.font ~= 0 and base.font or element.fontId\n\tentry.font = (named ~= 0 and named or font or 0) + 1\n\n\t-- Most elements draw no line at all, so the walk for one is only made when there is\n\t-- one to find.\n\tlocal measured = runs[element.run]\n\n\tif measured ~= nil then\n\t\tsizeToRun(self, entry, node, measured)\n\tend\n\n\t-- A field that is as tall as what is typed into it: the height its style gave it is not what\n\t-- the box is, what has been typed into it is -- up to the lines it is held to, which is the\n\t-- last of it that shows. The value was measured with everything else the frame draws, in the\n\t-- font it is drawn in, so the box comes out exactly as tall as the text in it.\n\tlocal valueRun = runs[element.valueRun]\n\n\tif valueRun ~= nil and bit.band(element.flags, GROWS) ~= 0 then\n\t\tlocal lines = valueRun.lineCount\n\t\tlocal most = element.maxLines\n\n\t\tif most > 0 and lines > most then\n\t\t\tlines = most\n\t\tend\n\n\t\tentry.heightUnit, entry.wantHeight = ABS, valueRun.height * lines / valueRun.lineCount\n\t\t\t+ entry.paddingTop + entry.paddingBottom + entry.borderTop + entry.borderBottom\n\tend\n\n\tlocal firstChild = self.childCount + 1\n\tlocal count = element.childCount\n\n\tself.childCount = self.childCount + count\n\tentry.firstChild = firstChild\n\tentry.childCount = count\n\n\t-- The children are one chain, and the run of child indices is filled in the order the\n\t-- chain hands them over, which is the order they were added in.\n\tlocal child = element.childFirst\n\n\tfor index = 1, count do\n\t\tlocal childElement = pointers[child]\n\t\tlocal childNode = self:build(childElement, entry.fgR, entry.fgG, entry.fgB, entry.fgA, entry.font)\n\n\t\tself.childIndices[firstChild + index - 2] = childNode\n\t\tchild = childElement.nextSibling\n\tend\n\n\treturn node\nend\n\n--- Solves a node into the space its parent gave it, laying its children out as it goes.\n--- The arithmetic is the layout: sizes are the space a node asked for, and the children\n--- are placed along and across the axis they are stacked on.\n---@param index number\n---@param parentWidth number\n---@param parentHeight number\n---@param mainOverride number? # Size to use along the axis the parent stacks on\n---@param overrideIsRow boolean? # Which axis that is\nlocal function solveNode(screen, index, parentWidth, parentHeight, mainOverride, overrideIsRow)\n\tlocal node = screen.nodes[index - 1]\n\n\tif node.visible == 0 then\n\t\tnode.x, node.y, node.width, node.height = 0, 0, 0, 0\n\n\t\treturn\n\tend\n\n\tlocal isRow = node.direction == 0\n\n\tif mainOverride then\n\t\t-- The size is given along the axis the parent stacks on, which is not necessarily\n\t\t-- the axis this node stacks its own children on.\n\t\tif overrideIsRow then\n\t\t\tnode.widthUnit, node.wantWidth = ABS, mainOverride\n\t\telse\n\t\t\tnode.heightUnit, node.wantHeight = ABS, mainOverride\n\t\tend\n\n\tend\n\n\tlocal availableWidth = parentWidth - node.marginLeft - node.marginRight\n\tlocal availableHeight = parentHeight - node.marginTop - node.marginBottom\n\n\tlocal width = node.widthUnit == AUTO and availableWidth\n\t\tor (node.widthUnit == REL and node.wantWidth * availableWidth)\n\t\tor node.wantWidth\n\n\tlocal height = node.heightUnit == AUTO and availableHeight\n\t\tor (node.heightUnit == REL and node.wantHeight * availableHeight)\n\t\tor node.wantHeight\n\n\tlocal borderWidth = node.borderLeft + node.borderRight\n\tlocal borderHeight = node.borderTop + node.borderBottom\n\n\tlocal contentWidth = width - node.paddingLeft - node.paddingRight - borderWidth\n\tlocal contentHeight = height - node.paddingTop - node.paddingBottom - borderHeight\n\n\tlocal containerMain = isRow and contentWidth or contentHeight\n\tlocal containerCross = isRow and contentHeight or contentWidth\n\tlocal count = node.childCount\n\tlocal first = node.firstChild\n\n\t-- What the children ask for along the main axis, and how many of them want whatever\n\t-- is left over.\n\tlocal totalMain = 0\n\tlocal visibleChildren = 0\n\tlocal autoCount = 0\n\n\tfor at = 0, count - 1 do\n\t\tlocal child = screen.nodes[screen.childIndices[first + at - 1] - 1]\n\n\t\tif child.position == 1 then\n\t\t\t-- Placed by hand, so it takes no room in the flow.\n\t\telse\n\t\t\tlocal childUnit = isRow and child.widthUnit or child.heightUnit\n\t\t\tlocal childWant = isRow and child.wantWidth or child.wantHeight\n\n\t\t\tif childUnit == 3 then\n\t\t\t\tautoCount = autoCount + 1\n\t\t\telse\n\t\t\t\ttotalMain = totalMain + (childUnit == 2 and childWant * containerMain or childWant)\n\t\t\t\tvisibleChildren = visibleChildren + 1\n\t\t\tend\n\t\tend\n\tend\n\n\tlocal totalGaps = math.max(0, count - 1) * node.gap\n\tlocal remaining = containerMain - totalMain - totalGaps\n\tlocal autoSpace = autoCount > 0 and (remaining / autoCount) or 0\n\n\t-- Solve the children, then place them.\n\tfor at = 0, count - 1 do\n\t\tlocal childIndex = screen.childIndices[first + at - 1]\n\t\tlocal child = screen.nodes[childIndex - 1]\n\t\tlocal childUnit = isRow and child.widthUnit or child.heightUnit\n\n\t\tsolveNode(screen, childIndex, contentWidth, contentHeight, childUnit == AUTO and autoSpace or nil, isRow)\n\tend\n\n\ttotalMain = 0\n\tvisibleChildren = 0\n\n\tfor at = 0, count - 1 do\n\t\tlocal child = assert(screen.nodes[screen.childIndices[first + at - 1] - 1])\n\n\t\tif (child.width > 0 or child.height > 0) and child.position ~= 1 then\n\t\t\tlocal childMainMargin = isRow and (child.marginLeft + child.marginRight)\n\t\t\t\tor (child.marginTop + child.marginBottom)\n\n\t\t\ttotalMain = totalMain + (isRow and child.width or child.height) + childMainMargin\n\t\t\tvisibleChildren = visibleChildren + 1\n\t\tend\n\tend\n\n\ttotalGaps = math.max(0, visibleChildren - 1) * node.gap\n\ttotalMain = totalMain + totalGaps\n\tlocal freeSpace = containerMain - totalMain\n\n\tlocal offset = 0\n\tlocal spacing = node.gap\n\n\tif node.justify == 1 then\n\t\toffset = freeSpace / 2\n\telseif node.justify == 2 then\n\t\toffset = freeSpace\n\telseif node.justify == 3 and count > 1 then\n\t\tspacing = spacing + freeSpace / (count - 1)\n\telseif node.justify == 4 and count > 0 then\n\t\tlocal unit = freeSpace / count\n\t\toffset = unit / 2\n\t\tspacing = spacing + unit\n\tend\n\n\tlocal placed = 0\n\n\tfor at = 0, count - 1 do\n\t\tlocal child = screen.nodes[screen.childIndices[first + at - 1] - 1]\n\t\tlocal shown = child.width > 0 or child.height > 0\n\n\t\tif shown and child.position == 1 then\n\t\t\t-- At the parent's content origin, moved by its own offset.\n\t\t\tif isRow then\n\t\t\t\tchild.x = snap(node.paddingLeft + child.x)\n\t\t\t\tchild.y = snap(node.paddingTop + child.y)\n\t\t\telse\n\t\t\t\tchild.y = snap(node.paddingTop + child.y)\n\t\t\t\tchild.x = snap(node.paddingLeft + child.x)\n\t\t\tend\n\t\telseif shown then\n\t\t\tplaced = placed + 1\n\t\t\tlocal last = placed == visibleChildren\n\n\t\t\tlocal mainPos = offset + (isRow and node.paddingLeft or node.paddingTop)\n\t\t\tlocal childMain = (isRow and child.x or child.y) + mainPos\n\n\t\t\tif isRow then\n\t\t\t\tchild.x = snap(childMain)\n\t\t\telse\n\t\t\t\tchild.y = snap(childMain)\n\t\t\tend\n\n\t\t\toffset = offset + (isRow and child.width or child.height) + (last and 0 or spacing)\n\n\t\t\tlocal crossOffset = (isRow and node.paddingTop or node.paddingLeft)\n\t\t\t\t+ (isRow and child.y or child.x)\n\t\t\tlocal childCrossMargin = isRow and (child.marginTop + child.marginBottom)\n\t\t\t\tor (child.marginLeft + child.marginRight)\n\t\t\tlocal cross = crossOffset\n\n\t\t\tif node.align == 1 then\n\t\t\t\tcross = crossOffset + (containerCross - (isRow and child.height or child.width) - childCrossMargin) / 2\n\t\t\telseif node.align == 2 then\n\t\t\t\tcross = crossOffset + containerCross - (isRow and child.height or child.width) - childCrossMargin\n\t\t\tend\n\n\t\t\tif isRow then\n\t\t\t\tchild.y = snap(cross)\n\t\t\telse\n\t\t\t\tchild.x = snap(cross)\n\t\t\tend\n\n\t\tend\n\n\tend\n\n\t-- A slider's nub is a child of it, and is put where the value is rather than where the layout\n\t-- stacked it: it travels across the box less its own size, which is what makes the ends of the\n\t-- box the ends of the slider, and along the axis the slider stacks on -- a slider that stacks\n\t-- down is one that is dragged up and down. The value is the app's, so a nub whose value did not\n\t-- move stays where the last frame put it, and a nub of a box that is not a slider stays where\n\t-- the layout put it.\n\tlocal slid = pointers[node.element]\n\n\tif slid ~= nil and bit.band(slid.flags, SLIDE) ~= 0 and count > 0 then\n\t\tlocal range = slid.max - slid.min\n\t\tlocal at1 = range ~= 0 and (slid.sliderValue - slid.min) / range or 0\n\t\tlocal along = at1 < 0 and 0 or (at1 > 1 and 1 or at1)\n\n\t\tfor at = 0, count - 1 do\n\t\t\tlocal child = screen.nodes[screen.childIndices[first + at - 1] - 1]\n\n\t\t\tif child.thumb ~= 0 then\n\t\t\t\tlocal size = isRow and child.width or child.height\n\t\t\t\tlocal travel = containerMain - size\n\n\t\t\t\tif travel < 0 then\n\t\t\t\t\ttravel = 0\n\t\t\t\tend\n\n\t\t\t\tif isRow then\n\t\t\t\t\tchild.x = snap(node.paddingLeft + along * travel)\n\t\t\t\telse\n\t\t\t\t\tchild.y = snap(node.paddingTop + along * travel)\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\t-- What is scrolled is shifted, and its own children come with it: their places are relative to\n\t-- it, so moving it moves the lot. How far it is shifted is what the content came out to less\n\t-- what the box shows -- which is only known once every child is placed -- so an offset past\n\t-- the end of the content draws the end rather than a hole. What the app keeps is its own.\n\tif node.scrolls ~= 0 then\n\t\tlocal most = math.max(0, offset - containerMain)\n\n\t\t-- Both ends, not just the far one: an offset below the start would put the content below\n\t\t-- the box and the thumb above it, and a thumb above its box is a bar that walks out of\n\t\t-- the pane as it is scrolled -- which is what a bar that would not stay put looked like.\n\t\tlocal scroll = math.min(math.max(node.scroll, 0), most)\n\n\t\t-- Kept, not just used: the bar is drawn from this, and an offset the app is still holding\n\t\t-- would walk the thumb out of the box its content was correctly clamped inside.\n\t\tnode.scroll = scroll\n\t\tscreen.bars[index - 1].max = most\n\n\t\tif scroll > 0 then\n\t\t\tfor at = 0, count - 1 do\n\t\t\t\tlocal child = screen.nodes[screen.childIndices[first + at - 1] - 1]\n\n\t\t\t\tif isRow then\n\t\t\t\t\tchild.x = child.x - scroll\n\t\t\t\telse\n\t\t\t\t\tchild.y = child.y - scroll\n\t\t\t\tend\n\t\t\tend\n\t\tend\n\tend\n\n\tlocal x = node.marginLeft\n\tlocal y = node.marginTop\n\n\tif node.position == 1 then\n\t\tif node.left ~= 0 then\n\t\t\tx = x + node.left\n\t\telseif node.right ~= 0 then\n\t\t\tx = x - node.right\n\t\tend\n\n\t\tif node.top ~= 0 then\n\t\t\ty = y + node.top\n\t\telseif node.bottom ~= 0 then\n\t\t\ty = y - node.bottom\n\t\tend\n\tend\n\n\tnode.width, node.height = width, height\n\tnode.x, node.y = snap(x), snap(y)\nend\n\n--- What the pointer is doing, worked out from the boxes the solve produced: everything the\n--- point is inside is hovered, so an element that has a box around others is hovered with them,\n--- and everything it is inside while the button is held is pressed.\n---\n--- Returns whether any of them is drawn differently for it, which is what says the screen has\n--- to be built again: a style that only changes what an element looks like still changes the\n--- frame, and the frame is what the gpu is given or not given.\n---@param screen wonderland.Layout.Screen\n---@param index number\n---@param x number\n---@param y number\n---@param parentX number\n---@param parentY number\n---@param pressed boolean\n---@return boolean marked\nlocal function markNode(screen, index, x, y, parentX, parentY, pressed)\n\tlocal node = screen.nodes[index - 1]\n\tlocal absX, absY = parentX + node.x, parentY + node.y\n\tlocal marked = false\n\n\tlocal inside = x >= absX and x <= absX + node.width and y >= absY and y <= absY + node.height\n\n\t-- What a box that scrolls has scrolled out of it is not drawn, hovered, or pressed either.\n\tif node.scrolls ~= 0 and not inside then\n\t\treturn marked\n\tend\n\n\tfor at = 0, node.childCount - 1 do\n\t\tif markNode(screen, screen.childIndices[node.firstChild + at - 1], x, y, absX, absY, pressed) then\n\t\t\tmarked = true\n\t\tend\n\tend\n\n\tif node.visible == 0 or not inside then\n\t\treturn marked\n\tend\n\n\tlocal element = pointers[node.element]\n\n\t-- The styles an element keeps for