f struct {\\n  int type;\\n  unsigned long serial;\\n  XBool send_event;\\n  XDisplay display;\\n  XWindow window;\\n  XWindow root;\\n  XWindow subwindow;\\n  XTime time;\\n  int x, y;\\n  int x_root, y_root;\\n  unsigned int state;\\n  unsigned int keycode;\\n  XBool same_screen;\\n} XKeyEvent;\\n\\ntypedef struct {\\n  int type;\\n  unsigned long serial;\\n  XBool send_event;\\n  XDisplay display;\\n  XWindow window;\\n} XAnyEvent;\\n\\ntypedef struct {\\n  int type;\\n  unsigned long serial;\\n  int send_event;\\n  XDisplay display;\\n  int extension;\\n  int evtype;\\n  unsigned int cookie;\\n  void *data;\\n} XGenericEventCookie;\\n\\n/* Selections (ICCCM). A window that owns a selection is asked for its data with a\\n   SelectionRequest carrying the window to put that data on, is told it lost the\\n   selection with a SelectionClear, and a window that asked for the data receives the\\n   answer as a SelectionNotify once the owner has put the data where it was asked to.\\n   The notify travels in XSelectionEvent, which names the requestor where the other\\n   two name the owner. */\\ntypedef struct {\\n  int type;\\n  unsigned long serial;\\n  XBool send_event;\\n  XDisplay display;\\n  XWindow owner;\\n  XWindow requestor;\\n  XAtom selection;\\n  XAtom target;\\n  XAtom property;\\n  XTime time;\\n} XSelectionRequestEvent;\\n\\ntypedef struct {\\n  int type;\\n  unsigned long serial;\\n  XBool send_event;\\n  XDisplay display;\\n  XWindow requestor;\\n  XAtom selection;\\n  XAtom target;\\n  XAtom property;\\n  XTime time;\\n} XSelectionEvent;\\n\\ntypedef struct {\\n  int type;\\n  unsigned long serial;\\n  XBool send_event;\\n  XDisplay display;\\n  XWindow owner;\\n  XAtom selection;\\n  XTime time;\\n} XSelectionClearEvent;\\n\\ntypedef union {\\n  int type;\\n  XAnyEvent xany;\\n  XClientMessageEvent xclient;\\n  XExposeEvent xexpose;\\n  XConfigureEvent xconfigure;\\n  XKeyEvent xkey;\\n  XMotionEvent xmotion;\\n  XButtonEvent xbutton;\\n  XGenericEventCookie xcookie;\\n  XSelectionRequestEvent xselectionrequest;\\n  XSelectionEvent xselection;\\n  XSelectionClearEvent xselectionclear;\\n  long pad[24];\\n} XEvent;\\n\\ntypedef struct {\\n  int x, y;\\n  int width, height;\\n  int border_width;\\n  int depth;\\n  XVisual visual;\\n  XWindow root;\\n  int class;\\n  int bit_gravity;\\n  int win_gravity;\\n  int backing_store;\\n  unsigned long backing_planes;\\n  unsigned long backing_pixel;\\n  XBool save_under;\\n  XColormap colormap;\\n  XBool map_installed;\\n  int map_state;\\n  long all_event_masks;\\n  long your_event_mask;\\n  long do_not_propagate_mask;\\n  XBool override_redirect;\\n  XScreen screen;\\n} XWindowAttributes;\\n\\nXDisplay XOpenDisplay(const char *display_name);\\nint XCloseDisplay(XDisplay display);\\nvoid XDestroyWindow(XDisplay display, unsigned long window);\\nXWindow XDefaultRootWindow(XDisplay display);\\nXWindow XCreateSimpleWindow(XDisplay display, XWindow parent, int x, int y,\\n                            unsigned int width, unsigned int height,\\n                            unsigned int border_width, unsigned long border,\\n                            unsigned long background);\\nXWindow XCreateWindow(XDisplay display, XWindow parent, int x, int y,\\n                      unsigned int width, unsigned int height,\\n                      unsigned int border_width, int depth,\\n                      unsigned int class, XVisual visual,\\n                      unsigned long valuemask,\\n                      XSetWindowAttributes *attributes);\\nvoid XMapWindow(XDisplay display, XWindow w);\\nXAtom XInternAtom(XDisplay display, const char *atom_name,\\n                  XBool only_if_exists);\\nXStatus XSetWMProtocols(XDisplay display, XWindow w, XAtom *protocols,\\n                        int count);\\nvoid XNextEvent(XDisplay display, XEvent *event_return);\\nvoid XPeekEvent(XDisplay display, XEvent *event_return);\\nint XDefaultScreen(XDisplay display);\\nXColormap XDefaultColormap(XDisplay display, int screen);\\nint XPending(XDisplay display);\\n\\n/* The socket a display talks to, which is what the ConnectionNumber macro reads and\\n   what a program needs to wait for events with a time on it: Xlib's own wait has none,\\n   and a screen with something to do on its own -- a caret that blinks -- is a program\\n   that has to be woken for it. What the macro reads is this far into the display\\n   structure: two pointers of the library's own come first, and the socket after them. */\\ntypedef struct { void *ext_data; void *free_funcs; int fd; } XConnection;\\nint XConnectionNumber(XDisplay display);\\nvoid XSelectInput(XDisplay display, XWindow w, long event_mask);\\nXStatus XGetWindowAttributes(XDisplay display, XWindow w,\\n                             XWindowAttributes *window_attributes_return);\\nXCursor XCreateFontCursor(XDisplay display, unsigned int shape);\\nvoid XDefineCursor(XDisplay display, XWindow w, XCursor cursor);\\nvoid XUndefineCursor(XDisplay display, XWindow w);\\nvoid XFreeCursor(XDisplay display, XCursor cursor);\\nvoid XFlush(XDisplay display);\\nvoid XChangeProperty(XDisplay display, XWindow w, XAtom property, XAtom type,\\n                     int format, int mode, const unsigned char *data,\\n                     int nelements);\\n\\n/* A selection is an atom a window claims to own -- clipboard, primary, or whatever\\n   else the clients of a screen agree on -- and the atom numbers are not fixed, so\\n   callers intern the names they mean. An owner of None means nobody holds it. */\\nXWindow XGetSelectionOwner(XDisplay display, XAtom selection);\\nint XSetSelectionOwner(XDisplay display, XAtom selection, XWindow owner,\\n                       XTime time);\\nXStatus XConvertSelection(XDisplay display, XAtom selection, XAtom target,\\n                          XAtom property, XWindow requestor, XTime time);\\n\\n/* XGetWindowProperty hands back a buffer the caller owns and must XFree. The offset\\n   and the length are